@Test
public void testExplainPlanLiteralOnly() throws Exception {
    SingleConnectionBrokerRequestHandler requestHandler = new SingleConnectionBrokerRequestHandler(new PinotConfiguration(), "testBrokerId", null, ACCESS_CONTROL_FACTORY, null, null, null, null, mock(ServerRoutingStatsManager.class), mock(FailureDetector.class));
    // Test 1: select constant
    BrokerResponse brokerResponse = requestHandler.handleRequest("EXPLAIN PLAN FOR SELECT 1.5, 'test'");
    checkExplainResultSchema(brokerResponse.getResultTable().getDataSchema(), new String[] { "Operator", "Operator_Id", "Parent_Id" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.STRING, DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.INT });
    assertEquals(brokerResponse.getResultTable().getRows().size(), 1);
    assertEquals(brokerResponse.getResultTable().getRows().get(0), new Object[] { "BROKER_EVALUATE", 0, -1 });
    assertEquals(brokerResponse.getTotalDocs(), 0);
    // Test 2: invoke compile time function -> literal only
    requestHandler.handleRequest("EXPLAIN PLAN FOR SELECT 6+8 AS addition, fromDateTime('2020-01-01 UTC', 'yyyy-MM-dd z') AS firstDayOf2020");
    checkExplainResultSchema(brokerResponse.getResultTable().getDataSchema(), new String[] { "Operator", "Operator_Id", "Parent_Id" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.STRING, DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.INT });
    assertEquals(brokerResponse.getResultTable().getRows().size(), 1);
    assertEquals(brokerResponse.getResultTable().getRows().get(0), new Object[] { "BROKER_EVALUATE", 0, -1 });
    assertEquals(brokerResponse.getTotalDocs(), 0);
}

