@Test
public void testGroovyScripts() throws JsonProcessingException {
    // setup secure groovy config
    GroovyFunctionEvaluator.setGroovyStaticAnalyzerConfig(GroovyStaticAnalyzerConfig.createDefault());
    String inValidGroovyQuery = "SELECT groovy('{\"returnType\":\"INT\",\"isSingleValue\":true}') FROM foo";
    runUnsupportedGroovy(inValidGroovyQuery, "Groovy transform function must have at least 2 argument");
    String groovyInvalidMethodInvokeQuery = "SELECT groovy('{\"returnType\":\"STRING\",\"isSingleValue\":true}', 'return [\"bash\", \"-c\", \"echo Hello," + " World!\"].execute().text') FROM foo";
    runUnsupportedGroovy(groovyInvalidMethodInvokeQuery, "Expression [MethodCallExpression] is not allowed");
    String groovyInvalidImportsQuery = "SELECT groovy( '{\"returnType\":\"INT\",\"isSingleValue\":true}', 'def args = [\"QuickStart\", \"-type\", " + "\"REALTIME\"] as String[]; org.apache.pinot.tools.admin.PinotAdministrator.main(args); 2') FROM foo";
    runUnsupportedGroovy(groovyInvalidImportsQuery, "Indirect import checks prevents usage of expression");
    String groovyInOrderByClause = "SELECT colA, colB FROM foo ORDER BY groovy('{\"returnType\":\"STRING\",\"isSingleValue\":true}', 'return " + "[\"bash\", \"-c\", \"echo Hello, World!\"].execute().text') DESC";
    runUnsupportedGroovy(groovyInOrderByClause, "Expression [MethodCallExpression] is not allowed");
    String groovyInHavingClause = "SELECT colA, SUM(colB) AS totalB, groovy('{\"returnType\":\"DOUBLE\",\"isSingleValue\":true}', 'arg0 / " + "arg1', SUM(colB), COUNT(*)) AS avgB FROM foo GROUP BY colA HAVING groovy('{\"returnType\":\"BOOLEAN\"," + "\"isSingleValue\":true}', 'System.metaClass.methods.each { method -> if (method.name.md5() == " + "\"f24f62eeb789199b9b2e467df3b1876b\") {method.invoke(System, 10)} }', SUM(colB))";
    runUnsupportedGroovy(groovyInHavingClause, "Indirect import checks prevents usage of expression");
    String groovyInWhereClause = "SELECT colA, colB FROM foo WHERE groovy('{\"returnType\":\"BOOLEAN\",\"isSingleValue\":true}', 'System.exit" + "(10)', colA)";
    runUnsupportedGroovy(groovyInWhereClause, "Indirect import checks prevents usage of expression");
    // Reset groovy config for rest of the testing
    GroovyFunctionEvaluator.setGroovyStaticAnalyzerConfig(null);
}

