@Test
public void reloadSslFactoryWhenFileStoreChanges() throws IOException, URISyntaxException, InterruptedException {
    SecureRandom secureRandom = new SecureRandom();
    SSLFactory sslFactory = RenewableTlsUtils.createSSLFactory(KEYSTORE_TYPE, TLS_KEYSTORE_FILE_PATH, PASSWORD, TRUSTSTORE_TYPE, TLS_TRUSTSTORE_FILE_PATH, PASSWORD, "TLS", secureRandom, true, false);
    X509ExtendedKeyManager x509ExtendedKeyManager = sslFactory.getKeyManager().get();
    X509ExtendedTrustManager x509ExtendedTrustManager = sslFactory.getTrustManager().get();
    SSLContext sslContext = sslFactory.getSslContext();
    PrivateKey privateKey = x509ExtendedKeyManager.getPrivateKey(KEY_NAME_ALIAS);
    Certificate certForPrivateKey = x509ExtendedKeyManager.getCertificateChain(KEY_NAME_ALIAS)[0];
    X509Certificate acceptedIssuerForCert = x509ExtendedTrustManager.getAcceptedIssuers()[0];
    // Start a new thread to reload the ssl factory when the tls files change
    // Avoid early finalization by not using Executors.newSingleThreadExecutor (java <= 20, JDK-8145304)
    ExecutorService executorService = Executors.newFixedThreadPool(1);
    executorService.execute(() -> {
        try {
            RenewableTlsUtils.reloadSslFactoryWhenFileStoreChanges(sslFactory, KEYSTORE_TYPE, TLS_KEYSTORE_FILE_PATH, PASSWORD, TRUSTSTORE_TYPE, TLS_TRUSTSTORE_FILE_PATH, PASSWORD, "TLS", secureRandom, () -> false);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    updateTlsFilesAndWaitForSslFactoryToBeRenewed();
    executorService.shutdown();
    // after tls file update, the returned values should be the same, since the wrapper is the same
    X509ExtendedKeyManager udpatedX509ExtendedKeyManager = sslFactory.getKeyManager().get();
    X509ExtendedTrustManager updatedX509ExtendedTrustManager = sslFactory.getTrustManager().get();
    SSLContext updatedSslContext = sslFactory.getSslContext();
    assertEquals(x509ExtendedKeyManager, udpatedX509ExtendedKeyManager);
    assertEquals(x509ExtendedTrustManager, updatedX509ExtendedTrustManager);
    assertEquals(sslContext, updatedSslContext);
    // after tls file update, the underlying values should be different
    assertNotEquals(privateKey, udpatedX509ExtendedKeyManager.getPrivateKey(KEY_NAME_ALIAS));
    assertNotEquals(certForPrivateKey, udpatedX509ExtendedKeyManager.getCertificateChain(KEY_NAME_ALIAS)[0]);
    assertNotEquals(acceptedIssuerForCert, updatedX509ExtendedTrustManager.getAcceptedIssuers()[0]);
}

@Test
public void enableAutoRenewalFromFileStoreForSSLFactoryThrows() {
    SSLFactory swappableSslFactory = RenewableTlsUtils.createSSLFactory(KEYSTORE_TYPE, TLS_KEYSTORE_FILE_PATH, PASSWORD, TRUSTSTORE_TYPE, TLS_TRUSTSTORE_FILE_PATH, PASSWORD, "TLS", null, true, false);
    TlsConfig tlsConfig = new TlsConfig();
    tlsConfig.setKeyStoreType(KEYSTORE_TYPE);
    tlsConfig.setKeyStorePath("ftp://" + TLS_KEYSTORE_FILE_PATH);
    tlsConfig.setKeyStorePassword(PASSWORD);
    tlsConfig.setTrustStoreType(TRUSTSTORE_TYPE);
    tlsConfig.setTrustStorePath(TLS_TRUSTSTORE_FILE_PATH);
    tlsConfig.setTrustStorePassword(PASSWORD);
    RuntimeException e = null;
    try {
        RenewableTlsUtils.enableAutoRenewalFromFileStoreForSSLFactory(swappableSslFactory, tlsConfig, () -> false);
    } catch (RuntimeException ex) {
        e = ex;
    }
    assertNotNull(e);
    assertEquals(e.getMessage(), "java.lang.IllegalArgumentException: key store path must be a local file path " + "or null when SSL auto renew is enabled");
    tlsConfig.setKeyStorePath(TLS_KEYSTORE_FILE_PATH);
    tlsConfig.setTrustStorePath("ftp://" + TLS_TRUSTSTORE_FILE_PATH);
    e = null;
    try {
        RenewableTlsUtils.enableAutoRenewalFromFileStoreForSSLFactory(swappableSslFactory, tlsConfig, () -> false);
    } catch (RuntimeException ex) {
        e = ex;
    }
    assertEquals(e.getMessage(), "java.lang.IllegalArgumentException: trust store path must be a local file path " + "or null when SSL auto renew is enabled");
    SSLFactory nonSwappableSslFactory = RenewableTlsUtils.createSSLFactory(KEYSTORE_TYPE, TLS_KEYSTORE_FILE_PATH, PASSWORD, TRUSTSTORE_TYPE, TLS_TRUSTSTORE_FILE_PATH, PASSWORD, "TLS", null, false, false);
    e = null;
    tlsConfig.setTrustStorePath(TLS_TRUSTSTORE_FILE_PATH);
    try {
        RenewableTlsUtils.enableAutoRenewalFromFileStoreForSSLFactory(nonSwappableSslFactory, tlsConfig, () -> false);
    } catch (RuntimeException ex) {
        e = ex;
    }
    assertEquals(e.getMessage(), "java.lang.IllegalArgumentException: key manager of the existing SSLFactory must be swappable");
    tlsConfig.setKeyStorePath(null);
    e = null;
    try {
        RenewableTlsUtils.enableAutoRenewalFromFileStoreForSSLFactory(nonSwappableSslFactory, tlsConfig, () -> false);
    } catch (RuntimeException ex) {
        e = ex;
    }
    assertEquals(e.getMessage(), "java.lang.IllegalArgumentException: trust manager of the existing SSLFactory must be swappable");
}

