@Test
public void testClpMatchRewrite() {
    MessageEncoder encoder = new MessageEncoder(BuiltInVariableHandlingRuleVersions.VariablesSchemaV2, BuiltInVariableHandlingRuleVersions.VariableEncodingMethodsV1);
    EncodedMessage encodedMessage = new EncodedMessage();
    try {
        String message;
        String[] dictionaryVars;
        Long[] encodedVars;
        // Query with no wildcards and no variables
        message = " INFO container ";
        encoder.encodeMessage(message, encodedMessage);
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s'", encodedMessage.getLogTypeAsString()));
        // Query with no wildcards and no variables using individual column names
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message_logtype, message_dictionaryVars," + " message_encodedVars, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s'", encodedMessage.getLogTypeAsString()));
        // Query with wildcards and no variables
        message = " INFO container ";
        encoder.encodeMessage(message, encodedMessage);
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '*%s*')", message), String.format("SELECT * FROM clpTable WHERE REGEXP_LIKE(message_logtype, '.*%s.*')", encodedMessage.getLogTypeAsString()));
        // Query with no wildcards and a single dictionary var
        message = " var123 ";
        encoder.encodeMessage(message, encodedMessage);
        dictionaryVars = encodedMessage.getDictionaryVarsAsStrings();
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s' AND message_dictionaryVars = '%s'", encodedMessage.getLogTypeAsString(), dictionaryVars[0]));
        // Query with no wildcards and a single encoded var
        message = " 123 ";
        encoder.encodeMessage(message, encodedMessage);
        encodedVars = encodedMessage.getEncodedVarsAsBoxedLongs();
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s' AND message_encodedVars = %s", encodedMessage.getLogTypeAsString(), encodedVars[0]));
        // Query with no wildcards and multiple dictionary vars
        message = " var123 var456 ";
        encoder.encodeMessage(message, encodedMessage);
        dictionaryVars = encodedMessage.getDictionaryVarsAsStrings();
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s' AND message_dictionaryVars = '%s'" + " AND message_dictionaryVars = '%s'" + " AND REGEXP_LIKE(clpdecode(message_logtype, message_dictionaryVars, message_encodedVars, '')," + " '%s')", encodedMessage.getLogTypeAsString(), dictionaryVars[0], dictionaryVars[1], String.format("^%s$", message)));
        // Query with no wildcards and multiple encoded vars
        message = " 123 456 ";
        encoder.encodeMessage(message, encodedMessage);
        encodedVars = encodedMessage.getEncodedVarsAsBoxedLongs();
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s' AND message_encodedVars = %s" + " AND message_encodedVars = %s" + " AND REGEXP_LIKE(clpdecode(message_logtype, message_dictionaryVars, message_encodedVars, '')," + " '%s')", encodedMessage.getLogTypeAsString(), encodedVars[0], encodedVars[1], String.format("^%s$", message)));
        // Query with no wildcards, a dictionary var, and an encoded var
        message = " var123 456 ";
        encoder.encodeMessage(message, encodedMessage);
        dictionaryVars = encodedMessage.getDictionaryVarsAsStrings();
        encodedVars = encodedMessage.getEncodedVarsAsBoxedLongs();
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '%s')", message), String.format("SELECT * FROM clpTable WHERE message_logtype = '%s' AND message_dictionaryVars = '%s'" + " AND message_encodedVars = %s", encodedMessage.getLogTypeAsString(), dictionaryVars[0], encodedVars[0]));
        // Query with wildcards for a single dictionary var
        message = "var123";
        encoder.encodeMessage(message, encodedMessage);
        dictionaryVars = encodedMessage.getDictionaryVarsAsStrings();
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '*%s*')", message), String.format("SELECT * FROM clpTable WHERE REGEXP_LIKE(message_logtype, '.*%s.*')" + " AND REGEXP_LIKE(message_dictionaryVars, '.*%s.*')" + " AND REGEXP_LIKE(clpdecode(message_logtype, message_dictionaryVars, message_encodedVars, '')," + " '%s')", encodedMessage.getLogTypeAsString(), dictionaryVars[0], String.format(".*%s.*", message)));
        // Query with wildcards for a single var which could be a float encoded var, int encoded var, or dictionary var
        encoder.encodeMessage("123", encodedMessage);
        String subquery1Logtype = encodedMessage.getLogTypeAsString();
        encoder.encodeMessage("123.0", encodedMessage);
        String subquery2Logtype = encodedMessage.getLogTypeAsString();
        encoder.encodeMessage("var123", encodedMessage);
        String subquery3Logtype = encodedMessage.getLogTypeAsString();
        message = "123";
        testQueryRewrite(String.format("SELECT * FROM clpTable WHERE clpMatch(message, '*%s*')", message), String.format("SELECT * FROM clpTable WHERE (" + "(REGEXP_LIKE(message_logtype, '.*%s.*')" + " AND clpEncodedVarsMatch(message_logtype, message_encodedVars, '*%s*', 0))" + " OR (REGEXP_LIKE(message_logtype, '.*%s.*')" + " AND clpEncodedVarsMatch(message_logtype, message_encodedVars, '*%s*', 1))" + " OR (REGEXP_LIKE(message_logtype, '.*%s.*') AND REGEXP_LIKE(message_dictionaryVars, '.*%s.*'))" + ") AND REGEXP_LIKE(clpdecode(message_logtype, message_dictionaryVars, message_encodedVars, '')," + " '.*%s.*')", subquery1Logtype, message, subquery2Logtype, message, subquery3Logtype, message, message));
    } catch (IOException e) {
        fail("Failed to encode message", e);
    }
}

