    verifySegments(2, 6);
}

@Test
public void testPinotSinkWrite() throws Exception {
    Configuration config = new Configuration();
    config.set(HeartbeatManagerOptions.HEARTBEAT_TIMEOUT, // Set heartbeat timeout to 60 seconds
    Duration.ofMillis(120000));
    StreamExecutionEnvironment execEnv = StreamExecutionEnvironment.getExecutionEnvironment(config);
    // Single-thread write
    execEnv.setParallelism(1);
    DataStream<Row> srcDs = execEnv.fromCollection(_data).returns(_typeInfo);
    srcDs.addSink(new PinotSinkFunction<>(new FlinkRowGenericRowConverter(_typeInfo), _tableConfig, _schema, PinotSinkFunction.DEFAULT_SEGMENT_FLUSH_MAX_NUM_RECORDS, PinotSinkFunction.DEFAULT_EXECUTOR_POOL_SIZE, "batch", 1724045185L));
    execEnv.execute();
    // 1 uploaded, 2 realtime in progress segment
    verifySegments(3, 4);
    // Parallel write with partitioned segments
    execEnv = StreamExecutionEnvironment.getExecutionEnvironment();
    execEnv.setParallelism(2);
    srcDs = execEnv.fromCollection(_data).returns(_typeInfo).partitionCustom((Partitioner<Integer>) (key, partitions) -> key % partitions, r -> (Integer) r.getField(0));
    srcDs.addSink(new PinotSinkFunction<>(new FlinkRowGenericRowConverter(_typeInfo), _tableConfig, _schema, PinotSinkFunction.DEFAULT_SEGMENT_FLUSH_MAX_NUM_RECORDS, PinotSinkFunction.DEFAULT_EXECUTOR_POOL_SIZE, "batch", 1724045186L));
    execEnv.execute();
    verifySegments(5, 8);
    // Generate next sequence segments in partitioned segments
    srcDs = execEnv.fromCollection(_data).returns(_typeInfo).partitionCustom((Partitioner<Integer>) (key, partitions) -> key % partitions, r -> (Integer) r.getField(0));
    srcDs.addSink(new PinotSinkFunction<>(new FlinkRowGenericRowConverter(_typeInfo), _tableConfig, _schema, 1, PinotSinkFunction.DEFAULT_EXECUTOR_POOL_SIZE, "batch", 1724045187L));
    execEnv.execute();
    verifySegments(9, 12);
    verifyContainsSegments(Arrays.asList("batch__mytable__0__1724045187__0", "batch__mytable__0__1724045187__1", "batch__mytable__1__1724045187__0", "batch__mytable__1__1724045187__1"));
}

