    checkInstanceInfo("Server_2.3.4.5_2345", "2.3.4.5", 2345, new String[] { "tag_OFFLINE", "tag_REALTIME" }, serverPools, 18090, 18091, 18092, 18093, false);
    // Test PUT instance API
    String newBrokerTag = "new-broker-tag";
    Instance newBrokerInstance = new Instance("1.2.3.4", 1234, InstanceType.BROKER, Collections.singletonList(newBrokerTag), null, 0, 0, 0, 0, false);
    String brokerInstanceId = "Broker_1.2.3.4_1234";
    String brokerInstanceUrl = _urlBuilder.forInstance(brokerInstanceId);
    sendPutRequest(brokerInstanceUrl, newBrokerInstance.toJsonString());
    String newServerTag = "new-server-tag";
    Instance newServerInstance = new Instance("1.2.3.4", 2345, InstanceType.SERVER, Collections.singletonList(newServerTag), null, 28090, 28091, 28092, 28093, true);
    String serverInstanceId = "Server_1.2.3.4_2345";
