    sendPutRequest(serverInstanceUrl, newServerInstance.toJsonString());
    checkInstanceInfo(brokerInstanceId, "1.2.3.4", 1234, new String[] { newBrokerTag }, null, -1, -1, -1, -1, false);
    checkInstanceInfo(serverInstanceId, "1.2.3.4", 2345, new String[] { newServerTag }, null, 28090, 28091, 28092, 28093, true);
    // Test Instance updateTags API
    String brokerInstanceUpdateTagsUrl = _urlBuilder.forInstanceUpdateTags(brokerInstanceId, Lists.newArrayList("tag_BROKER", "newTag_BROKER"));
    sendPutRequest(brokerInstanceUpdateTagsUrl);
    String serverInstanceUpdateTagsUrl = _urlBuilder.forInstanceUpdateTags(serverInstanceId, Lists.newArrayList("tag_REALTIME", "newTag_OFFLINE", "newTag_REALTIME"));
