    Map<String, InstanceAssignmentConfig> instanceAssignmentConfigMap = new HashMap<>();
    instanceAssignmentConfigMap.put(InstancePartitionsType.CONSUMING.name(), getInstanceAssignmentConfig("DefaultTenant_REALTIME", 4, 2));
    TableConfig realtimeTableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(tableName).setServerTenant("DefaultTenant").setTimeColumnName("timeColumn").setTimeType("DAYS").setRetentionTimeUnit("DAYS").setRetentionTimeValue("5").setStreamConfigs(FakeStreamConfigUtils.getDefaultLowLevelStreamConfigs().getStreamConfigsMap()).setInstanceAssignmentConfigMap(instanceAssignmentConfigMap).setNumReplicas(10).build();
    try {
        sendPostRequest(_createTableUrl, realtimeTableConfig.toJsonString());
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("Failed to calculate instance partitions for table: " + tableNameWithType));
    }
    // Create a new valid table and update it with invalid replica group config
    instanceAssignmentConfigMap.clear();
    instanceAssignmentConfigMap.put(InstancePartitionsType.CONSUMING.name(), getInstanceAssignmentConfig("DefaultTenant_REALTIME", 4, 1));
    realtimeTableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(tableName).setServerTenant("DefaultTenant").setTimeColumnName("timeColumn").setTimeType("DAYS").setRetentionTimeUnit("DAYS").setRetentionTimeValue("5").setStreamConfigs(FakeStreamConfigUtils.getDefaultLowLevelStreamConfigs().getStreamConfigsMap()).setInstanceAssignmentConfigMap(instanceAssignmentConfigMap).setNumReplicas(10).build();
    try {
        sendPostRequest(_createTableUrl, realtimeTableConfig.toJsonString());
    } catch (Exception e) {
        fail("Preconditions failure: Could not create a REALTIME table with a valid replica group config as a " + "precondition to testing config updates");
    }
    // Update it with an invalid RG config, the update should fail
    instanceAssignmentConfigMap.clear();
    instanceAssignmentConfigMap.put(InstancePartitionsType.CONSUMING.name(), getInstanceAssignmentConfig("DefaultTenant_REALTIME", 1, 8));
    try {
        sendPostRequest(_createTableUrl, realtimeTableConfig.toJsonString());
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("Failed to calculate instance partitions for table: " + tableNameWithType));
