@Test
public void testBrokerTenant() throws IOException {
    // Create broker tenants
    for (int i = 1; i <= NUM_BROKER_TAGS; i++) {
        String brokerTenant = BROKER_TAG_PREFIX + i;
        createBrokerTenant(brokerTenant, NUM_BROKERS_PER_TAG);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(getHelixClusterName(), TagNameUtils.getBrokerTagForTenant(brokerTenant)).size(), NUM_BROKERS_PER_TAG);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(getHelixClusterName(), CommonConstants.Helix.UNTAGGED_BROKER_INSTANCE).size(), NUM_INSTANCES - i * NUM_BROKERS_PER_TAG);
    }
    // Get broker tenants
    JsonNode response = JsonUtils.stringToJsonNode(sendGetRequest(_controllerRequestURLBuilder.forTenantGet()));
    Assert.assertEquals(response.get("BROKER_TENANTS").size(), NUM_BROKER_TAGS);
    for (int i = 1; i <= NUM_BROKER_TAGS; i++) {
        String brokerTag = BROKER_TAG_PREFIX + i;
        response = JsonUtils.stringToJsonNode(sendGetRequest(_controllerRequestURLBuilder.forBrokerTenantGet(brokerTag)));
        Assert.assertEquals(response.get("BrokerInstances").size(), NUM_BROKERS_PER_TAG);
        Assert.assertEquals(response.get("tenantName").asText(), brokerTag);
        response = JsonUtils.stringToJsonNode(sendGetRequest(_controllerRequestURLBuilder.forTenantGet(brokerTag)));
        Assert.assertEquals(response.get("BrokerInstances").size(), NUM_BROKERS_PER_TAG);
        Assert.assertEquals(response.get("ServerInstances").size(), 0);
        Assert.assertEquals(response.get("tenantName").asText(), brokerTag);
    }
    // Update broker tenants
    for (int i = 0; i <= NUM_INSTANCES - (NUM_BROKER_TAGS - 1) * NUM_BROKERS_PER_TAG; i++) {
        String brokerTenant = BROKER_TAG_PREFIX + 1;
        updateBrokerTenant(brokerTenant, i);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(getHelixClusterName(), TagNameUtils.getBrokerTagForTenant(brokerTenant)).size(), i);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(getHelixClusterName(), CommonConstants.Helix.UNTAGGED_BROKER_INSTANCE).size(), NUM_INSTANCES - (NUM_BROKER_TAGS - 1) * NUM_BROKERS_PER_TAG - i);
    }
    // Delete broker tenants
    for (int i = 1; i <= NUM_BROKER_TAGS; i++) {
        String brokerTenant = BROKER_TAG_PREFIX + i;
        sendDeleteRequest(_controllerRequestURLBuilder.forBrokerTenantDelete(brokerTenant));
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(getHelixClusterName(), TagNameUtils.getBrokerTagForTenant(brokerTenant)).size(), 0);
        Assert.assertEquals(_helixAdmin.getInstancesInClusterWithTag(getHelixClusterName(), CommonConstants.Helix.UNTAGGED_BROKER_INSTANCE).size(), NUM_INSTANCES - (NUM_BROKER_TAGS - i) * NUM_BROKERS_PER_TAG);
    }
}

