    int numInstancesPerReplicaGroup = numInstances / numReplicaGroups;
    instanceConfigs = new ArrayList<>(numInstances);
    for (int i = 0; i < numInstances; i++) {
        int pool = i % numPools;
        InstanceConfig instanceConfig = new InstanceConfig(SERVER_INSTANCE_ID_PREFIX + i + SERVER_INSTANCE_POOL_PREFIX + pool);
