//@formatter:on
@Test
public void testPoolsWhenOneMorePoolAddedAndOneMoreReplicaGroupsNeeded() throws JsonProcessingException {
    //@formatter:off
    String existingPartitionsJson = "{\n" + "  \"instancePartitionsName\": \"0f97dac8-4123-47c6-9a4d-b8ce039c5ea5_OFFLINE\",\n" + "  \"partitionToInstancesMap\": {\n" + "    \"0_0\": [\n" + "      \"Server_pinot-server-rg0-0.pinot-server-headless.pinot.svc.cluster.local_8098\",\n" + "      \"Server_pinot-server-rg0-1.pinot-server-headless.pinot.svc.cluster.local_8098\"\n" + "    ]\n" + "  }\n" + "}";
    //@formatter:on
    InstancePartitions existing = OBJECT_MAPPER.readValue(existingPartitionsJson, InstancePartitions.class);
    InstanceReplicaGroupPartitionConfig config = new InstanceReplicaGroupPartitionConfig(true, 0, 2, 2, 1, 2, true, null);
    InstanceReplicaGroupPartitionSelector selector = new InstanceReplicaGroupPartitionSelector(config, "tableNameBlah", existing, true);
    String[] serverNames = { "rg0-0", "rg0-1", "rg1-0", "rg1-1" };
    String[] poolNumbers = { "0", "0", "1", "1" };
    String[] poolNames = { "FirstHalfReplicationGroups", "FirstHalfReplicationGroups", "SecondHalfReplicationGroups", "SecondHalfReplicationGroups" };
    Map<Integer, List<InstanceConfig>> poolToInstanceConfigsMap = new HashMap<>();
    for (int i = 0; i < serverNames.length; i++) {
        Map<String, String> valuesMap = new HashMap<>();
        valuesMap.put("serverName", serverNames[i]);
        valuesMap.put("pool", poolNumbers[i]);
        valuesMap.put("poolName", poolNames[i]);
        StringSubstitutor substitutor = new StringSubstitutor(valuesMap);
        String resolvedString = substitutor.replace(INSTANCE_CONFIG_TEMPLATE);
        ZNRecord znRecord = OBJECT_MAPPER.readValue(resolvedString, ZNRecord.class);
        int poolNumber = Integer.parseInt(poolNumbers[i]);
        poolToInstanceConfigsMap.computeIfAbsent(poolNumber, k -> new ArrayList<>()).add(new InstanceConfig(znRecord));
    }
    InstancePartitions assignedPartitions = new InstancePartitions("0f97dac8-4123-47c6-9a4d-b8ce039c5ea5_OFFLINE");
    selector.selectInstances(poolToInstanceConfigsMap, assignedPartitions);
    // Now that 1 more pool is added and 1 more RG is needed, a new set called "0_1" is generated,
    // and the instances from Pool 1 are assigned to this new replica.
    //@formatter:off
    String expectedInstancePartitions = "{\n" + "  \"instancePartitionsName\": \"0f97dac8-4123-47c6-9a4d-b8ce039c5ea5_OFFLINE\",\n" + "  \"partitionToInstancesMap\": {\n" + "    \"0_0\": [\n" + "      \"Server_pinot-server-rg0-0.pinot-server-headless.pinot.svc.cluster.local_8098\",\n" + "      \"Server_pinot-server-rg0-1.pinot-server-headless.pinot.svc.cluster.local_8098\"\n" + "    ],\n" + "    \"0_1\": [\n" + "      \"Server_pinot-server-rg1-0.pinot-server-headless.pinot.svc.cluster.local_8098\",\n" + "      \"Server_pinot-server-rg1-1.pinot-server-headless.pinot.svc.cluster.local_8098\"\n" + "    ]\n" + "  }\n" + "}";
    //@formatter:on
    InstancePartitions expectedPartitions = OBJECT_MAPPER.readValue(expectedInstancePartitions, InstancePartitions.class);
    assertEquals(assignedPartitions, expectedPartitions);
}

