    //@formatter:on
    InstancePartitions existing = OBJECT_MAPPER.readValue(existingPartitionsJson, InstancePartitions.class);
    InstanceReplicaGroupPartitionConfig config = new InstanceReplicaGroupPartitionConfig(true, 0, 2, 2, 1, 2, true, null);
    InstanceReplicaGroupPartitionSelector selector = new InstanceReplicaGroupPartitionSelector(config, "tableNameBlah", existing, true);
    String[] serverNames = { "rg0-0", "rg0-1", "rg0-2", "rg1-0", "rg1-1", "rg1-2" };
    String[] poolNumbers = { "0", "0", "0", "1", "1", "1" };
    Map<Integer, List<InstanceConfig>> poolToInstanceConfigsMap = new HashMap<>();
    for (int i = 0; i < serverNames.length; i++) {
        Map<String, String> valuesMap = new HashMap<>();
        valuesMap.put("serverName", serverNames[i]);
        valuesMap.put("pool", poolNumbers[i]);
        StringSubstitutor substitutor = new StringSubstitutor(valuesMap);
        String resolvedString = substitutor.replace(INSTANCE_CONFIG_TEMPLATE);
        ZNRecord znRecord = OBJECT_MAPPER.readValue(resolvedString, ZNRecord.class);
        int poolNumber = Integer.parseInt(poolNumbers[i]);
        poolToInstanceConfigsMap.computeIfAbsent(poolNumber, k -> new ArrayList<>()).add(new InstanceConfig(znRecord));
    }
    InstancePartitions assignedPartitions = new InstancePartitions("0f97dac8-4123-47c6-9a4d-b8ce039c5ea5_OFFLINE");
    selector.selectInstances(poolToInstanceConfigsMap, assignedPartitions);
    // The "rg0-2" instance is replaced by "rg1-0" (which belongs to Pool 1), as "rg0-2" no longer belongs to Pool 1.
    // And "rg1-0" remains the same position as it's always under Pool 1.
    //@formatter:off
    String expectedInstancePartitions = "{\n" + "  \"instancePartitionsName\": \"0f97dac8-4123-47c6-9a4d-b8ce039c5ea5_OFFLINE\",\n" + "  \"partitionToInstancesMap\": {\n" + "    \"0_0\": [\n" + "      \"Server_pinot-server-rg0-0.pinot-server-headless.pinot.svc.cluster.local_8098\",\n" + "      \"Server_pinot-server-rg0-1.pinot-server-headless.pinot.svc.cluster.local_8098\"\n" + "    ],\n" + "    \"0_1\": [\n" + "      \"Server_pinot-server-rg1-1.pinot-server-headless.pinot.svc.cluster.local_8098\",\n" + "      \"Server_pinot-server-rg1-0.pinot-server-headless.pinot.svc.cluster.local_8098\"\n" + "    ]\n" + "  }\n" + "}";
    //@formatter:on
    InstancePartitions expectedPartitions = OBJECT_MAPPER.readValue(expectedInstancePartitions, InstancePartitions.class);
    assertEquals(assignedPartitions, expectedPartitions);
}

@Test
public void testTableBalanced() {
    Map<String, Map<String, String>> currentAssignment = new TreeMap<>();
    for (String segmentName : SEGMENTS) {
        List<String> instancesAssigned = _segmentAssignment.assignSegment(segmentName, currentAssignment, _instancePartitionsMap);
        currentAssignment.put(segmentName, SegmentAssignmentUtils.getInstanceStateMap(instancesAssigned, SegmentStateModel.ONLINE));
    }
    // There should be 100 segments assigned
    assertEquals(currentAssignment.size(), NUM_SEGMENTS);
    // Each segment should have 3 replicas
    for (Map<String, String> instanceStateMap : currentAssignment.values()) {
        assertEquals(instanceStateMap.size(), NUM_REPLICAS);
    }
    // Each instance should have 30 segments assigned
    int[] numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(currentAssignment, INSTANCES);
    int[] expectedNumSegmentsAssignedPerInstance = new int[NUM_INSTANCES];
    int numSegmentsPerInstance = NUM_SEGMENTS * NUM_REPLICAS / NUM_INSTANCES;
    Arrays.fill(expectedNumSegmentsAssignedPerInstance, numSegmentsPerInstance);
    assertEquals(numSegmentsAssignedPerInstance, expectedNumSegmentsAssignedPerInstance);
    // On rebalancing, segments move to tiers
    Map<String, Map<String, String>> newAssignment = _segmentAssignment.rebalanceTable(currentAssignment, _instancePartitionsMap, _sortedTiers, _tierInstancePartitionsMap, new RebalanceConfig());
    assertEquals(newAssignment.size(), NUM_SEGMENTS);
    // segments 0-49 remain unchanged
    for (int i = 0; i < 49; i++) {
        String segmentName = SEGMENT_NAME_PREFIX + i;
        assertEquals(newAssignment.get(segmentName), currentAssignment.get(segmentName));
    }
    // segments 50-69 go to tierA
    // segments 70-99 go to tierB
    int expectedOnTierA = 20;
    int expectedOnTierB = 30;
    for (int i = 50; i < 100; i++) {
        String segmentName = SEGMENT_NAME_PREFIX + i;
        if (i < 70) {
            Assert.assertTrue(INSTANCES_TIER_A.containsAll(newAssignment.get(segmentName).keySet()));
        } else {
            Assert.assertTrue(INSTANCES_TIER_B.containsAll(newAssignment.get(segmentName).keySet()));
        }
    }
    // TierA segments should be balanced
    numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(newAssignment, INSTANCES_TIER_A);
    assertEquals(numSegmentsAssignedPerInstance.length, NUM_INSTANCES_TIER_A);
    int expectedMinNumSegmentsPerInstance = expectedOnTierA / NUM_INSTANCES_TIER_A;
    for (int i = 0; i < NUM_INSTANCES_TIER_A; i++) {
        assertTrue(numSegmentsAssignedPerInstance[i] >= expectedMinNumSegmentsPerInstance);
    }
    // TierB segments should be balanced
    numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(newAssignment, INSTANCES_TIER_B);
    assertEquals(numSegmentsAssignedPerInstance.length, NUM_INSTANCES_TIER_B);
    expectedMinNumSegmentsPerInstance = expectedOnTierB / NUM_INSTANCES_TIER_B;
    for (int i = 0; i < NUM_INSTANCES_TIER_B; i++) {
        assertTrue(numSegmentsAssignedPerInstance[i] >= expectedMinNumSegmentsPerInstance);
    }
    // rebalance without tierInstancePartitions resets the assignment
    Map<String, Map<String, String>> resetAssignment = _segmentAssignment.rebalanceTable(newAssignment, _instancePartitionsMap, null, null, new RebalanceConfig());
    for (String segment : SEGMENTS) {
        Assert.assertTrue(INSTANCES.containsAll(resetAssignment.get(segment).keySet()));
    }
}

@Test
public void testBootstrapTable() {
    Map<String, Map<String, String>> currentAssignment = new TreeMap<>();
    // The list of segments are segment_0, segment_1, ... segment_10, ...; but TreeMap sorts segments as segment_0,
    // segment_1, segment_10, ... segment_2, ... So to make bootstrap generate same assignment as assigning each
    // segment separately, we need to process the segments in the same order.
    for (String segmentName : new TreeSet<>(SEGMENTS)) {
        List<String> instancesAssigned = _segmentAssignment.assignSegment(segmentName, currentAssignment, _instancePartitionsMap);
        currentAssignment.put(segmentName, SegmentAssignmentUtils.getInstanceStateMap(instancesAssigned, SegmentStateModel.ONLINE));
    }
    // Bootstrap table should reassign all segments
    RebalanceConfig rebalanceConfig = new RebalanceConfig();
    rebalanceConfig.setBootstrap(true);
    Map<String, Map<String, String>> newAssignment = _segmentAssignment.rebalanceTable(currentAssignment, _instancePartitionsMap, _sortedTiers, _tierInstancePartitionsMap, rebalanceConfig);
    assertEquals(newAssignment.size(), NUM_SEGMENTS);
    // segments 0-49 remain unchanged
    for (int i = 0; i < 49; i++) {
        String segmentName = SEGMENT_NAME_PREFIX + i;
        assertEquals(newAssignment.get(segmentName), currentAssignment.get(segmentName));
    }
    // segments 50-69 go to tierA
    // segments 70-99 go to tierB
    for (int i = 50; i < 100; i++) {
        String segmentName = SEGMENT_NAME_PREFIX + i;
        for (String instance : newAssignment.get(segmentName).keySet()) {
            if (i < 70) {
                Assert.assertTrue(instance.startsWith(TIER_A_INSTANCE_NAME_PREFIX));
            } else {
                Assert.assertTrue(instance.startsWith(TIER_B_INSTANCE_NAME_PREFIX));
            }
        }
    }
}

