@Test
public void testExplicitPartition() {
    // CONSUMING instances:
    // {
    //   0_0=[instance_0], 1_0=[instance_1], 2_0=[instance_2],
    //   0_1=[instance_3], 1_1=[instance_4], 2_1=[instance_5],
    //   0_2=[instance_6], 1_2=[instance_7], 2_2=[instance_8]
    // }
    //        p0                p1                p2
    //        p3
    InstancePartitions consumingInstancePartitions = new InstancePartitions(CONSUMING_INSTANCE_PARTITIONS_NAME);
    int numConsumingInstancesPerReplicaGroup = NUM_CONSUMING_INSTANCES / NUM_REPLICAS;
    int consumingInstanceIdToAdd = 0;
    for (int replicaGroupId = 0; replicaGroupId < NUM_REPLICAS; replicaGroupId++) {
        for (int partitionId = 0; partitionId < numConsumingInstancesPerReplicaGroup; partitionId++) {
            consumingInstancePartitions.setInstances(partitionId, replicaGroupId, Collections.singletonList(CONSUMING_INSTANCES.get(consumingInstanceIdToAdd++)));
        }
    }
    // COMPLETED instances:
    // {
    //   0_0=[instance_0], 1_0=[instance_1], 2_0=[instance_2], 3_0=[instance_3],
    //   0_1=[instance_4], 1_1=[instance_5], 2_1=[instance_6], 3_1=[instance_7],
    //   0_2=[instance_8], 1_2=[instance_9], 2_2=[instance_10], 3_2=[instance_11]
    // }
    InstancePartitions completedInstancePartitions = new InstancePartitions(COMPLETED_INSTANCE_PARTITIONS_NAME);
    int numCompletedInstancesPerReplicaGroup = NUM_COMPLETED_INSTANCES / NUM_REPLICAS;
    int completedInstanceIdToAdd = 0;
    for (int replicaGroupId = 0; replicaGroupId < NUM_REPLICAS; replicaGroupId++) {
        for (int partitionId = 0; partitionId < numCompletedInstancesPerReplicaGroup; partitionId++) {
            completedInstancePartitions.setInstances(partitionId, replicaGroupId, Collections.singletonList(COMPLETED_INSTANCES.get(completedInstanceIdToAdd++)));
        }
    }
    // Test assigning CONSUMING segment
    Map<InstancePartitionsType, InstancePartitions> onlyConsumingInstancePartitionMap = ImmutableMap.of(InstancePartitionsType.CONSUMING, consumingInstancePartitions);
    Map<String, Map<String, String>> consumingCurrentAssignment = new TreeMap<>();
    for (int segmentId = 0; segmentId < NUM_SEGMENTS; segmentId++) {
        String segmentName = _segments.get(segmentId);
        List<String> instancesAssigned = _segmentAssignment.assignSegment(segmentName, consumingCurrentAssignment, onlyConsumingInstancePartitionMap);
        assertEquals(instancesAssigned.size(), NUM_REPLICAS);
        // Segment 0 (partition 0) should be assigned to instance 0, 3, 6
        // Segment 1 (partition 1) should be assigned to instance 1, 4, 7
        // Segment 2 (partition 2) should be assigned to instance 2, 5, 8
        // Segment 3 (partition 3) should be assigned to instance 0, 3, 6
        // Segment 4 (partition 0) should be assigned to instance 0, 3, 6
        // Segment 5 (partition 1) should be assigned to instance 1, 4, 7
        // ...
        for (int replicaGroupId = 0; replicaGroupId < NUM_REPLICAS; replicaGroupId++) {
            int partitionId = segmentId % NUM_PARTITIONS;
            int expectedAssignedInstanceId = partitionId % numConsumingInstancesPerReplicaGroup + replicaGroupId * numConsumingInstancesPerReplicaGroup;
            assertEquals(instancesAssigned.get(replicaGroupId), CONSUMING_INSTANCES.get(expectedAssignedInstanceId));
        }
        addToAssignment(consumingCurrentAssignment, segmentId, instancesAssigned);
    }
    // Test assigning UPLOADED segment
    Map<InstancePartitionsType, InstancePartitions> onlyCompletedInstancePartitionMap = ImmutableMap.of(InstancePartitionsType.COMPLETED, completedInstancePartitions);
    Map<String, Map<String, String>> uploadedCurrentAssignment = new TreeMap<>();
    for (int segmentId = 0; segmentId < NUM_SEGMENTS; segmentId++) {
        String segmentName = _segments.get(segmentId);
        List<String> instancesAssigned = _segmentAssignment.assignSegment(segmentName, uploadedCurrentAssignment, onlyCompletedInstancePartitionMap);
        assertEquals(instancesAssigned.size(), NUM_REPLICAS);
        // Segment 0 (partition 0) should be assigned to instance 0, 4, 8
        // Segment 1 (partition 1) should be assigned to instance 1, 5, 9
        // Segment 2 (partition 2) should be assigned to instance 2, 6, 10
        // Segment 3 (partition 3) should be assigned to instance 3, 7, 11
        // Segment 4 (partition 0) should be assigned to instance 0, 4, 8
        // Segment 5 (partition 1) should be assigned to instance 1, 5, 9
        // ...
        for (int replicaGroupId = 0; replicaGroupId < NUM_REPLICAS; replicaGroupId++) {
            int partitionId = segmentId % NUM_PARTITIONS;
            int expectedAssignedInstanceId = partitionId + replicaGroupId * numCompletedInstancesPerReplicaGroup;
            assertEquals(instancesAssigned.get(replicaGroupId), COMPLETED_INSTANCES.get(expectedAssignedInstanceId));
        }
        addToAssignment(uploadedCurrentAssignment, segmentId, instancesAssigned);
    }
    // Test relocating COMPLETED segments
    Map<InstancePartitionsType, InstancePartitions> instancePartitionsMap = ImmutableMap.of(InstancePartitionsType.CONSUMING, consumingInstancePartitions, InstancePartitionsType.COMPLETED, completedInstancePartitions);
    RebalanceConfig rebalanceConfig = new RebalanceConfig();
    rebalanceConfig.setIncludeConsuming(true);
    Map<String, Map<String, String>> newAssignment = _segmentAssignment.rebalanceTable(uploadedCurrentAssignment, instancePartitionsMap, null, null, rebalanceConfig);
    // First 20 segments (COMPLETED) should have the same assignment as if they are uploaded
    // Last 4 segments (CONSUMING) should not move
    for (int segmentId = 0; segmentId < NUM_SEGMENTS; segmentId++) {
        String segmentName = _segments.get(segmentId);
        if (segmentId < NUM_SEGMENTS - NUM_PARTITIONS) {
            assertEquals(newAssignment.get(segmentName), uploadedCurrentAssignment.get(segmentName));
        } else {
            assertEquals(newAssignment.get(segmentName), consumingCurrentAssignment.get(segmentName));
        }
    }
}

@Test
public void testRebalanceTableWithHelixAutoRebalanceStrategy() {
    int numSegments = 100;
    List<String> segments = SegmentAssignmentTestUtils.getNameList(SEGMENT_NAME_PREFIX, numSegments);
    int numInstances = 10;
    List<String> instances = SegmentAssignmentTestUtils.getNameList(INSTANCE_NAME_PREFIX, numInstances);
    // Uniformly spray segments to the instances (i0 represents instance_0, s0 represents segment_0)
    // [    i0,    i1,    i2,    i3,    i4,    i5,    i6,    i7,    i8,    i9]
    //  s0(r0) s0(r1) s0(r2) s1(r0) s1(r1) s1(r2) s2(r0) s2(r1) s2(r2) s3(r0)
    //  s3(r1) s3(r2) s4(r0) s4(r1) s4(r2) s5(r0) s5(r1) s5(r2) s6(r0) s6(r1)
    //  ...
    Map<String, Map<String, String>> currentAssignment = new TreeMap<>();
    int assignedInstanceId = 0;
    for (String segmentName : segments) {
        List<String> instancesAssigned = new ArrayList<>(NUM_REPLICAS);
        for (int replicaId = 0; replicaId < NUM_REPLICAS; replicaId++) {
            instancesAssigned.add(instances.get(assignedInstanceId));
            assignedInstanceId = (assignedInstanceId + 1) % numInstances;
        }
        currentAssignment.put(segmentName, SegmentAssignmentUtils.getInstanceStateMap(instancesAssigned, SegmentStateModel.ONLINE));
    }
    // There should be 100 segments assigned
    assertEquals(currentAssignment.size(), numSegments);
    // Each segment should have 3 replicas
    for (Map<String, String> instanceStateMap : currentAssignment.values()) {
        assertEquals(instanceStateMap.size(), NUM_REPLICAS);
    }
    // Each instance should have 30 segments assigned
    int[] numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(currentAssignment, instances);
    int[] expectedNumSegmentsAssignedPerInstance = new int[numInstances];
    int numSegmentsPerInstance = numSegments * NUM_REPLICAS / numInstances;
    Arrays.fill(expectedNumSegmentsAssignedPerInstance, numSegmentsPerInstance);
    assertEquals(numSegmentsAssignedPerInstance, expectedNumSegmentsAssignedPerInstance);
    // Current assignment should already be balanced
    assertEquals(SegmentAssignmentUtils.rebalanceTableWithHelixAutoRebalanceStrategy(currentAssignment, instances, NUM_REPLICAS), currentAssignment);
    // Replace instance_0 with instance_10
    List<String> newInstances = new ArrayList<>(instances);
    String newInstanceName = INSTANCE_NAME_PREFIX + 10;
    newInstances.set(0, newInstanceName);
    Map<String, Map<String, String>> newAssignment = SegmentAssignmentUtils.rebalanceTableWithHelixAutoRebalanceStrategy(currentAssignment, newInstances, NUM_REPLICAS);
    // There should be 100 segments assigned
    assertEquals(currentAssignment.size(), numSegments);
    // Each segment should have 3 replicas
    for (Map<String, String> instanceStateMap : newAssignment.values()) {
        assertEquals(instanceStateMap.size(), NUM_REPLICAS);
    }
    // Each instance should have 30 segments assigned
    numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(newAssignment, newInstances);
    assertEquals(numSegmentsAssignedPerInstance, expectedNumSegmentsAssignedPerInstance);
    // All segments on instance_0 should be moved to instance_10
    Map<String, IntIntPair> numSegmentsToMovePerInstance = SegmentAssignmentUtils.getNumSegmentsToMovePerInstance(currentAssignment, newAssignment);
    assertEquals(numSegmentsToMovePerInstance.size(), 2);
    assertEquals(numSegmentsToMovePerInstance.get(newInstanceName), IntIntPair.of(30, 0));
    String oldInstanceName = INSTANCE_NAME_PREFIX + 0;
    assertEquals(numSegmentsToMovePerInstance.get(oldInstanceName), IntIntPair.of(0, 30));
    for (String segmentName : segments) {
        if (currentAssignment.get(segmentName).containsKey(oldInstanceName)) {
            assertTrue(newAssignment.get(segmentName).containsKey(newInstanceName));
        }
    }
    // Remove 5 instances
    // {
    //   0_0=[instance_0, instance_1, instance_2, instance_3, instance_4]
    // }
    int newNumInstances = numInstances - 5;
    newInstances = SegmentAssignmentTestUtils.getNameList(INSTANCE_NAME_PREFIX, newNumInstances);
    newAssignment = SegmentAssignmentUtils.rebalanceTableWithHelixAutoRebalanceStrategy(currentAssignment, newInstances, NUM_REPLICAS);
    // There should be 100 segments assigned
    assertEquals(newAssignment.size(), numSegments);
    // Each segment should have 3 replicas
    for (Map<String, String> instanceStateMap : newAssignment.values()) {
        assertEquals(instanceStateMap.size(), NUM_REPLICAS);
    }
    // The segments are not perfectly balanced, but should be deterministic
    numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(newAssignment, newInstances);
    assertEquals(numSegmentsAssignedPerInstance[0], 56);
    assertEquals(numSegmentsAssignedPerInstance[1], 60);
    assertEquals(numSegmentsAssignedPerInstance[2], 60);
    assertEquals(numSegmentsAssignedPerInstance[3], 60);
    assertEquals(numSegmentsAssignedPerInstance[4], 64);
    numSegmentsToMovePerInstance = SegmentAssignmentUtils.getNumSegmentsToMovePerInstance(currentAssignment, newAssignment);
    assertEquals(numSegmentsToMovePerInstance.size(), numInstances);
    assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + 0), IntIntPair.of(26, 0));
    assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + 1), IntIntPair.of(30, 0));
    assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + 2), IntIntPair.of(30, 0));
    assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + 3), IntIntPair.of(30, 0));
    assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + 4), IntIntPair.of(34, 0));
    for (int i = 5; i < 10; i++) {
        assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + i), IntIntPair.of(0, 30));
    }
    // Add 5 instances (i0 represents instance_0)
    // {
    //   0_0=[i0, i1, i2, i3, i4, i5, i6, i7, i8, i9, i10, i11, i12, i13, i14]
    // }
    newNumInstances = numInstances + 5;
    newInstances = SegmentAssignmentTestUtils.getNameList(INSTANCE_NAME_PREFIX, newNumInstances);
    newAssignment = SegmentAssignmentUtils.rebalanceTableWithHelixAutoRebalanceStrategy(currentAssignment, newInstances, NUM_REPLICAS);
    // There should be 100 segments assigned
    assertEquals(newAssignment.size(), numSegments);
    // Each segment should have 3 replicas
    for (Map<String, String> instanceStateMap : newAssignment.values()) {
        assertEquals(instanceStateMap.size(), NUM_REPLICAS);
    }
    // Each instance should have 20 segments assigned
    numSegmentsAssignedPerInstance = SegmentAssignmentUtils.getNumSegmentsAssignedPerInstance(newAssignment, newInstances);
    expectedNumSegmentsAssignedPerInstance = new int[newNumInstances];
    int newNumSegmentsPerInstance = numSegments * NUM_REPLICAS / newNumInstances;
    Arrays.fill(expectedNumSegmentsAssignedPerInstance, newNumSegmentsPerInstance);
    assertEquals(numSegmentsAssignedPerInstance, expectedNumSegmentsAssignedPerInstance);
    // Each new added instance should have 20 segments to be moved to it
    numSegmentsToMovePerInstance = SegmentAssignmentUtils.getNumSegmentsToMovePerInstance(currentAssignment, newAssignment);
    assertEquals(numSegmentsToMovePerInstance.size(), newNumInstances);
    for (int i = 0; i < numInstances; i++) {
        assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + i), IntIntPair.of(0, 10));
    }
    for (int i = numInstances; i < newNumInstances; i++) {
        assertEquals(numSegmentsToMovePerInstance.get(INSTANCE_NAME_PREFIX + i), IntIntPair.of(20, 0));
    }
    // Change all instances
    // {
