@Test
public void testSegmentReplacementWithCustomToSegments() throws Exception {
    // Create the table
    addDummySchema(RAW_TABLE_NAME);
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setBrokerTenant(BROKER_TENANT_NAME).setServerTenant(SERVER_TENANT_NAME).build();
    waitForEVToDisappear(tableConfig.getTableName());
    _helixResourceManager.addTable(tableConfig);
    List<String> segmentsFrom = Collections.emptyList();
    List<String> segmentsTo = Arrays.asList("s20", "s21");
    String lineageEntryId = _helixResourceManager.startReplaceSegments(OFFLINE_TABLE_NAME, segmentsFrom, segmentsTo, false, null);
    assertThrows(RuntimeException.class, () -> _helixResourceManager.endReplaceSegments(OFFLINE_TABLE_NAME, lineageEntryId, new EndReplaceSegmentsRequest(Arrays.asList("s9", "s6"), null)));
    // Try after new segments added to the table
    _helixResourceManager.addNewSegment(OFFLINE_TABLE_NAME, SegmentMetadataMockUtils.mockSegmentMetadata(OFFLINE_TABLE_NAME, "s20"), getDownloadURL(_controllerDataDir, RAW_TABLE_NAME, "s20"));
    _helixResourceManager.addNewSegment(OFFLINE_TABLE_NAME, SegmentMetadataMockUtils.mockSegmentMetadata(OFFLINE_TABLE_NAME, "s21"), getDownloadURL(_controllerDataDir, RAW_TABLE_NAME, "s21"));
    _helixResourceManager.endReplaceSegments(OFFLINE_TABLE_NAME, lineageEntryId, new EndReplaceSegmentsRequest(Arrays.asList("s21"), null));
    SegmentLineage segmentLineage = SegmentLineageAccessHelper.getSegmentLineage(_propertyStore, OFFLINE_TABLE_NAME);
    assertEquals(segmentLineage.getLineageEntryIds(), Collections.singleton(lineageEntryId));
    assertEquals(segmentLineage.getLineageEntry(lineageEntryId).getSegmentsFrom(), segmentsFrom);
    assertEquals(segmentLineage.getLineageEntry(lineageEntryId).getState(), LineageEntryState.COMPLETED);
    // Delete the table
    _helixResourceManager.deleteOfflineTable(RAW_TABLE_NAME);
    segmentLineage = SegmentLineageAccessHelper.getSegmentLineage(_propertyStore, OFFLINE_TABLE_NAME);
    assertNull(segmentLineage);
}

@Test
public void testSegmentReplacementRegular() throws Exception {
    // Create the table
    addDummySchema(RAW_TABLE_NAME);
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setBrokerTenant(BROKER_TENANT_NAME).setServerTenant(SERVER_TENANT_NAME).build();
