@Test
public void testSyncCommittingSegments() throws Exception {
    // Set up mocks for the resource management infrastructure
    PinotHelixResourceManager pinotHelixResourceManager = mock(PinotHelixResourceManager.class);
    HelixManager helixManager = mock(HelixManager.class);
    HelixAdmin helixAdmin = mock(HelixAdmin.class);
    ZkHelixPropertyStore<ZNRecord> zkHelixPropertyStore = (ZkHelixPropertyStore<ZNRecord>) mock(ZkHelixPropertyStore.class);
    // Configure basic mock behaviors
    when(pinotHelixResourceManager.getHelixZkManager()).thenReturn(helixManager);
    when(helixManager.getClusterManagmentTool()).thenReturn(helixAdmin);
    when(helixManager.getClusterName()).thenReturn(CLUSTER_NAME);
    when(pinotHelixResourceManager.getPropertyStore()).thenReturn(zkHelixPropertyStore);
    // Initialize the segment manager
    ControllerConf controllerConfig = new ControllerConf();
    FakePinotLLCRealtimeSegmentManager segmentManager = new FakePinotLLCRealtimeSegmentManager(pinotHelixResourceManager, controllerConfig);
    String realtimeTableName = "testTable_REALTIME";
    String committingSegmentsListPath = ZKMetadataProvider.constructPropertyStorePathForPauselessDebugMetadata(realtimeTableName);
    // Create test segments with different states
    String committingSegment1 = "testTable__0__0__20250210T1142Z";
    String committingSegment2 = "testTable__0__1__20250210T1142Z";
    String doneSegment = "testTable__0__2__20250210T1142Z";
    // Set up segment metadata mocks
    SegmentZKMetadata committingMetadata1 = mock(SegmentZKMetadata.class);
    when(committingMetadata1.getStatus()).thenReturn(Status.COMMITTING);
    SegmentZKMetadata committingMetadata2 = mock(SegmentZKMetadata.class);
    when(committingMetadata2.getStatus()).thenReturn(Status.COMMITTING);
    SegmentZKMetadata doneMetadata = mock(SegmentZKMetadata.class);
    when(doneMetadata.getStatus()).thenReturn(Status.DONE);
    when(pinotHelixResourceManager.getSegmentZKMetadata(realtimeTableName, committingSegment1)).thenReturn(committingMetadata1);
    when(pinotHelixResourceManager.getSegmentZKMetadata(realtimeTableName, committingSegment2)).thenReturn(committingMetadata2);
    when(pinotHelixResourceManager.getSegmentZKMetadata(realtimeTableName, doneSegment)).thenReturn(doneMetadata);
    // Test 1: Initial creation with mixed status segments
    List<String> newSegments = Arrays.asList(committingSegment1, committingSegment2);
    when(zkHelixPropertyStore.get(eq(committingSegmentsListPath), any(), eq(AccessOption.PERSISTENT))).thenReturn(null);
    when(zkHelixPropertyStore.create(eq(committingSegmentsListPath), any(), eq(AccessOption.PERSISTENT))).thenReturn(true);
    assertTrue(segmentManager.syncCommittingSegments(realtimeTableName, newSegments));
    // Test 2: Syncing with existing segments including DONE and missing metadata
    ZNRecord existingRecord = new ZNRecord(realtimeTableName);
    existingRecord.setListField(COMMITTING_SEGMENTS, Arrays.asList(committingSegment2, doneSegment));
    when(zkHelixPropertyStore.get(eq(committingSegmentsListPath), any(), eq(AccessOption.PERSISTENT))).thenReturn(existingRecord);
    when(zkHelixPropertyStore.set(eq(committingSegmentsListPath), any(), anyInt(), eq(AccessOption.PERSISTENT))).thenReturn(true);
    // There should not be any duplicates and the doneSegment should be removed from the list
    assertTrue(segmentManager.syncCommittingSegments(realtimeTableName, Arrays.asList(committingSegment1, committingSegment2)));
    assertEquals(new HashSet<>(existingRecord.getListField(COMMITTING_SEGMENTS)), new HashSet<>(List.of(committingSegment1, committingSegment2)));
    // Test 3: Error handling during ZooKeeper operations
    when(zkHelixPropertyStore.set(eq(committingSegmentsListPath), any(), anyInt(), eq(AccessOption.PERSISTENT))).thenThrow(new RuntimeException("ZooKeeper operation failed"));
    assertFalse(segmentManager.syncCommittingSegments(realtimeTableName, newSegments));
}

/**
 * Tests that the flush threshold update manager returns the right updater given various scenarios of flush threshold
 * setting in the stream config.
 */
@Test
public void testFlushThresholdUpdateManager() {
    FlushThresholdUpdateManager flushThresholdUpdateManager = new FlushThresholdUpdateManager();
    // None of the flush threshold set - DefaultFlushThresholdUpdater should be returned
    FlushThresholdUpdater flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(-1, -1, -1));
    assertTrue(flushThresholdUpdater instanceof DefaultFlushThresholdUpdater);
    assertEquals(((DefaultFlushThresholdUpdater) flushThresholdUpdater).getTableFlushSize(), StreamConfig.DEFAULT_FLUSH_THRESHOLD_ROWS);
    // Flush threshold rows larger than 0 - DefaultFlushThresholdUpdater should be returned
    flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(1234, -1, -1));
    assertTrue(flushThresholdUpdater instanceof DefaultFlushThresholdUpdater);
    assertEquals(((DefaultFlushThresholdUpdater) flushThresholdUpdater).getTableFlushSize(), 1234);
    // Flush threshold segment rows larger than 0 - FixedFlushThresholdUpdater should be returned
    flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(-1, 1234, -1));
    assertTrue(flushThresholdUpdater instanceof FixedFlushThresholdUpdater);
    // Flush threshold rows set to 0 - SegmentSizeBasedFlushThresholdUpdater should be returned
    FlushThresholdUpdater segmentBasedflushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(0, -1, -1));
    assertTrue(segmentBasedflushThresholdUpdater instanceof SegmentSizeBasedFlushThresholdUpdater);
    // Flush threshold segment size larger than 0 - SegmentSizeBasedFlushThresholdUpdater should be returned
    flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(0, -1, 1234));
    assertSame(flushThresholdUpdater, segmentBasedflushThresholdUpdater);
    // Flush threshold rows set larger than 0 - DefaultFlushThresholdUpdater should be returned
    flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(12345, -1, -1));
    assertTrue(flushThresholdUpdater instanceof DefaultFlushThresholdUpdater);
    assertEquals(((DefaultFlushThresholdUpdater) flushThresholdUpdater).getTableFlushSize(), 12345);
    // Call again with flush threshold rows set to 0 - a different Object should be returned
    flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(0, -1, -1));
    assertTrue(flushThresholdUpdater instanceof SegmentSizeBasedFlushThresholdUpdater);
    assertNotSame(flushThresholdUpdater, segmentBasedflushThresholdUpdater);
    segmentBasedflushThresholdUpdater = flushThresholdUpdater;
    // Clear the updater
    assertEquals(flushThresholdUpdateManager.getFlushThresholdUpdaterMapSize(), 1);
    flushThresholdUpdateManager.clearFlushThresholdUpdater(mockStreamConfig(0, -1, -1));
    assertEquals(flushThresholdUpdateManager.getFlushThresholdUpdaterMapSize(), 0);
    // Call again with flush threshold rows set to 0 - a different Object should be returned
    flushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(0, -1, -1));
    assertTrue(flushThresholdUpdater instanceof SegmentSizeBasedFlushThresholdUpdater);
    assertNotSame(flushThresholdUpdater, segmentBasedflushThresholdUpdater);
}

/**
 * Tests the segment size based flush threshold updater.
 * We have 3 types of dataset, each having a different segment size to num rows ratio (exponential growth, logarithmic
 * growth, steps). For each type of dataset, we let 500 segments pass through our algorithm, and always hit the rows
 * threshold. Towards the end, we should get the segment size stabilized around the desired segment size (200MB).
 */
@Test
public void testSegmentSizeBasedFlushThreshold() {
    StreamConfig streamConfig = mockDefaultAutotuneStreamConfig();
    long desiredSegmentSizeBytes = streamConfig.getFlushThresholdSegmentSizeBytes();
    long segmentSizeLowerLimit = (long) (desiredSegmentSizeBytes * 0.99);
    long segmentSizeHigherLimit = (long) (desiredSegmentSizeBytes * 1.01);
    for (long[] segmentSizesMB : Arrays.asList(EXPONENTIAL_GROWTH_SEGMENT_SIZES_MB, LOGARITHMIC_GROWTH_SEGMENT_SIZES_MB, STEPS_SEGMENT_SIZES_MB)) {
        SegmentSizeBasedFlushThresholdUpdater flushThresholdUpdater = new SegmentSizeBasedFlushThresholdUpdater(REALTIME_TABLE_NAME, streamConfig.getTopicName());
        // Start consumption
        SegmentZKMetadata newSegmentZKMetadata = getNewSegmentZKMetadata(0);
        flushThresholdUpdater.updateFlushThreshold(streamConfig, newSegmentZKMetadata, 1);
        assertEquals(newSegmentZKMetadata.getSizeThresholdToFlushSegment(), streamConfig.getFlushAutotuneInitialRows());
        int numRuns = 500;
        int checkRunsAfter = 400;
        for (int run = 0; run < numRuns; run++) {
            int numRowsConsumed = newSegmentZKMetadata.getSizeThresholdToFlushSegment();
            long segmentSizeBytes = getSegmentSizeBytes(numRowsConsumed, segmentSizesMB);
            CommittingSegmentDescriptor committingSegmentDescriptor = getCommittingSegmentDescriptor(segmentSizeBytes);
            SegmentZKMetadata committingSegmentZKMetadata = getCommittingSegmentZKMetadata(System.currentTimeMillis(), numRowsConsumed, numRowsConsumed);
            flushThresholdUpdater.onSegmentCommit(streamConfig, committingSegmentDescriptor, committingSegmentZKMetadata);
            flushThresholdUpdater.updateFlushThreshold(streamConfig, newSegmentZKMetadata, 1);
            // Assert that segment size is in limits
            if (run > checkRunsAfter) {
                assertTrue(segmentSizeBytes > segmentSizeLowerLimit && segmentSizeBytes < segmentSizeHigherLimit);
            }
        }
    }
}

