    // Fast forward to one second before commit time, and send a lease renewal request for 20s
    _segmentCompletionMgr._seconds = startTime + commitTimeSec - 1;
    params = new Request.Params().withInstanceId(S_2).withStreamPartitionMsgOffset(_s2Offset.toString()).withSegmentName(_segmentNameStr).withExtraTimeSec(20);
