    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + TIER_A_NAME)).getNumSegmentsUnchanged(), numSegments * NUM_REPLICAS - 13);
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + TIER_A_NAME)).getNumServerParticipants(), 6);
    assertNotNull(rebalanceResult.getInstanceAssignment());
    assertNotNull(rebalanceResult.getTierInstanceAssignment());
    assertNotNull(rebalanceResult.getSegmentAssignment());
    rebalanceResult = tableRebalancer.rebalance(tableConfig, new RebalanceConfig(), null);
    assertEquals(rebalanceResult.getStatus(), RebalanceResult.Status.DONE);
    assertTrue(rebalanceResult.getTierInstanceAssignment().containsKey(TIER_A_NAME));
    InstancePartitions instancePartitions = rebalanceResult.getTierInstanceAssignment().get(TIER_A_NAME);
    // Math.abs("testTable_OFFLINE".hashCode()) % 6 = 2
    // [i2, i3, i4, i5, i0, i1]
    //  r0  r1  r2  r0  r1  r2
    assertEquals(instancePartitions.getInstances(0, 0), Arrays.asList("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 2, "replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 5));
    assertEquals(instancePartitions.getInstances(0, 1), Arrays.asList("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 3, "replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 0));
    assertEquals(instancePartitions.getInstances(0, 2), Arrays.asList("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 4, "replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 1));
    // The assignment are based on replica-group 0 and mirrored to all the replica-groups, so server of index 0, 1, 5
    // should have the same segments assigned, and server of index 2, 3, 4 should have the same segments assigned, each
    // with 5 segments
    Map<String, Map<String, String>> newSegmentAssignment = rebalanceResult.getSegmentAssignment();
    int numSegmentsOnServer0 = 0;
    for (int i = 0; i < numSegments; i++) {
        String segmentName = SEGMENT_NAME_PREFIX + i;
        Map<String, String> instanceStateMap = newSegmentAssignment.get(segmentName);
        assertEquals(instanceStateMap.size(), NUM_REPLICAS);
        if (instanceStateMap.containsKey("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 0)) {
            numSegmentsOnServer0++;
            assertEquals(instanceStateMap.get("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 0), ONLINE);
            assertEquals(instanceStateMap.get("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 1), ONLINE);
            assertEquals(instanceStateMap.get("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 5), ONLINE);
        } else {
            assertEquals(instanceStateMap.get("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 2), ONLINE);
            assertEquals(instanceStateMap.get("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 3), ONLINE);
            assertEquals(instanceStateMap.get("replicaAssignment" + TIER_A_NAME + "_" + SERVER_INSTANCE_ID_PREFIX + 4), ONLINE);
        }
    }
    assertEquals(numSegmentsOnServer0, numSegments / 2);
    _helixResourceManager.deleteOfflineServerTenantFor("replicaAssignment" + TIER_A_NAME);
    rebalanceConfig = new RebalanceConfig();
    rebalanceConfig.setDryRun(true);
    rebalanceConfig.setReassignInstances(false);
    // if rebalance with reassignInstances=false, servers assigned would not have relevant tags
    rebalanceResult = tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    assertEquals(rebalanceResult.getStatus(), RebalanceResult.Status.NO_OP);
    rebalanceSummaryResult = rebalanceResult.getRebalanceSummaryResult();
    assertNotNull(rebalanceSummaryResult);
    assertNotNull(rebalanceSummaryResult.getServerInfo());
    assertNotNull(rebalanceSummaryResult.getSegmentInfo());
    assertEquals(rebalanceSummaryResult.getSegmentInfo().getTotalSegmentsToBeMoved(), 0);
    assertEquals(rebalanceSummaryResult.getServerInfo().getNumServers().getValueBeforeRebalance(), 6);
    assertEquals(rebalanceSummaryResult.getServerInfo().getNumServers().getExpectedValueAfterRebalance(), 6);
    assertNotNull(rebalanceSummaryResult.getTagsInfo());
    assertEquals(rebalanceSummaryResult.getTagsInfo().size(), 3);
    tenantInfoMap = rebalanceSummaryResult.getTagsInfo().stream().collect(Collectors.toMap(RebalanceSummaryResult.TagInfo::getTagName, info -> info));
    assertTrue(tenantInfoMap.containsKey(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + NO_TIER_NAME)));
    assertTrue(tenantInfoMap.containsKey(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + TIER_A_NAME)));
    assertTrue(tenantInfoMap.containsKey(RebalanceSummaryResult.TagInfo.TAG_FOR_OUTDATED_SERVERS));
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + NO_TIER_NAME)).getNumSegmentsToDownload(), 0);
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + NO_TIER_NAME)).getNumSegmentsUnchanged(), 0);
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + NO_TIER_NAME)).getNumServerParticipants(), 0);
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + TIER_A_NAME)).getNumSegmentsToDownload(), 0);
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + TIER_A_NAME)).getNumSegmentsUnchanged(), 0);
    assertEquals(tenantInfoMap.get(TagNameUtils.getOfflineTagForTenant("replicaAssignment" + TIER_A_NAME)).getNumServerParticipants(), 0);
    assertEquals(tenantInfoMap.get(RebalanceSummaryResult.TagInfo.TAG_FOR_OUTDATED_SERVERS).getNumSegmentsToDownload(), 0);
    assertEquals(tenantInfoMap.get(RebalanceSummaryResult.TagInfo.TAG_FOR_OUTDATED_SERVERS).getNumSegmentsUnchanged(), numSegments * NUM_REPLICAS);
    assertEquals(tenantInfoMap.get(RebalanceSummaryResult.TagInfo.TAG_FOR_OUTDATED_SERVERS).getNumServerParticipants(), 6);
    _helixResourceManager.deleteOfflineTable(TIERED_TABLE_NAME);
}

