    targetAssignment.put("segment4", SegmentAssignmentUtils.getInstanceStateMap(Arrays.asList("host1", "host3", "host4"), ONLINE));
    // Number of segments to offload:
    // {
    //   "host1": -2,
    //   "host2": 4,
    //   "host3": 0,
