    // Next assignment with 2 minimum available replicas without strict replica-group should finish in 2 steps:
    //
    // The first assignment will remove "segment1" and "segment3" from "host2", and remove "segment2" and "segment4"
    // from "host2":
    // {
    //   "segment1": {
    //     "host1": "ONLINE",
    //     "host3": "ONLINE"
    //   },
    //   "segment2": {
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   },
    //   "segment3": {
    //     "host1": "ONLINE",
    //     "host3": "ONLINE"
    //   },
    //   "segment4": {
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   }
    // }
    //
    // The second assignment should reach the target assignment
    Map<String, Map<String, String>> nextAssignment = TableRebalancer.getNextAssignment(currentAssignment, targetAssignment, 2, false, true);
    assertEquals(nextAssignment.get("segment1").keySet(), new TreeSet<>(Arrays.asList("host1", "host3")));
    assertEquals(nextAssignment.get("segment2").keySet(), new TreeSet<>(Arrays.asList("host3", "host4")));
    assertEquals(nextAssignment.get("segment3").keySet(), new TreeSet<>(Arrays.asList("host1", "host3")));
    assertEquals(nextAssignment.get("segment4").keySet(), new TreeSet<>(Arrays.asList("host3", "host4")));
    nextAssignment = TableRebalancer.getNextAssignment(nextAssignment, targetAssignment, 2, false, true);
    assertEquals(nextAssignment, targetAssignment);
    // Next assignment with 2 minimum available replicas with strict replica-group should finish in 3 steps:
    //
    // The first assignment will remove "segment1" and "segment3" from "host2", and remove "segment2" and "segment4"
    // from "host2":
    // {
    //   "segment1": {
    //     "host1": "ONLINE",
    //     "host3": "ONLINE"
    //   },
    //   "segment2": {
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   },
    //   "segment3": {
    //     "host1": "ONLINE",
    //     "host3": "ONLINE"
    //   },
    //   "segment4": {
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   }
    // }
    //
    // The second assignment will bring "segment1" and "segment3" to the target state. It cannot bring "segment2" and
    // "segment4" to the target state because "host1" and "host4" might be unavailable for strict replica-group routing,
    // which breaks the minimum available replicas requirement:
    // {
    //   "segment1": {
    //     "host1": "ONLINE",
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   },
    //   "segment2": {
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   },
    //   "segment3": {
    //     "host1": "ONLINE",
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   },
    //   "segment4": {
    //     "host3": "ONLINE",
    //     "host4": "ONLINE"
    //   }
    // }
    //
    // The third assignment should reach the target assignment
    nextAssignment = TableRebalancer.getNextAssignment(currentAssignment, targetAssignment, 2, true, true);
    assertEquals(nextAssignment.get("segment1").keySet(), new TreeSet<>(Arrays.asList("host1", "host3")));
    assertEquals(nextAssignment.get("segment2").keySet(), new TreeSet<>(Arrays.asList("host3", "host4")));
    assertEquals(nextAssignment.get("segment3").keySet(), new TreeSet<>(Arrays.asList("host1", "host3")));
    assertEquals(nextAssignment.get("segment4").keySet(), new TreeSet<>(Arrays.asList("host3", "host4")));
    nextAssignment = TableRebalancer.getNextAssignment(nextAssignment, targetAssignment, 2, true, true);
    assertEquals(nextAssignment.get("segment1").keySet(), new TreeSet<>(Arrays.asList("host1", "host3", "host4")));
    assertEquals(nextAssignment.get("segment2").keySet(), new TreeSet<>(Arrays.asList("host3", "host4")));
    assertEquals(nextAssignment.get("segment3").keySet(), new TreeSet<>(Arrays.asList("host1", "host3", "host4")));
    assertEquals(nextAssignment.get("segment4").keySet(), new TreeSet<>(Arrays.asList("host3", "host4")));
    nextAssignment = TableRebalancer.getNextAssignment(nextAssignment, targetAssignment, 2, true, true);
    assertEquals(nextAssignment, targetAssignment);
}

@Test
public void testIsExternalViewConverged() {
    String offlineTableName = "testTable_OFFLINE";
    Map<String, Map<String, String>> externalViewSegmentStates = new TreeMap<>();
    Map<String, Map<String, String>> idealStateSegmentStates = new TreeMap<>();
    boolean[] falseAndTrue = new boolean[] { false, true };
    // Empty segment states should match
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // Do not check segment that does not exist in IdealState
    Map<String, String> instanceStateMap = new TreeMap<>();
    instanceStateMap.put("instance1", ONLINE);
    externalViewSegmentStates.put("segment1", instanceStateMap);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // Do not check segment that is OFFLINE in IdealState
    instanceStateMap = new TreeMap<>();
    instanceStateMap.put("instance1", OFFLINE);
    idealStateSegmentStates.put("segment2", instanceStateMap);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // Should fail when a segment has CONSUMING instance in IdealState but does not exist in ExternalView
    instanceStateMap.put("instance2", CONSUMING);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertFalse(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // Should fail when instance state does not exist
    instanceStateMap = new TreeMap<>();
    externalViewSegmentStates.put("segment2", instanceStateMap);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertFalse(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // Should fail when instance state does not match
    instanceStateMap.put("instance2", OFFLINE);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertFalse(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // Should pass when instance state matches
    instanceStateMap.put("instance2", CONSUMING);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
        }
    }
    // When there are extra instances in ExternalView, should pass in regular mode but fail in low disk mode
    instanceStateMap.put("instance3", CONSUMING);
    for (boolean bestEfforts : falseAndTrue) {
        assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, false, bestEfforts, null));
        assertFalse(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, true, bestEfforts, null));
    }
    // When instance state is ERROR in ExternalView, should fail in regular mode but pass in best-efforts mode
    instanceStateMap.put("instance2", ERROR);
    instanceStateMap.remove("instance3");
    for (boolean lowDiskMode : falseAndTrue) {
        try {
            TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, false, null);
            fail();
        } catch (Exception e) {
            // Expected
        }
        assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, true, null));
    }
    // When the extra instance is in ERROR state, should throw exception in low disk mode when best-efforts is disabled
    instanceStateMap.put("instance2", CONSUMING);
    instanceStateMap.put("instance3", ERROR);
    for (boolean lowDiskMode : falseAndTrue) {
        for (boolean bestEfforts : falseAndTrue) {
            if (lowDiskMode && !bestEfforts) {
                try {
                    TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, true, false, null);
                    fail();
                } catch (Exception e) {
                    // Expected
                }
            } else {
                assertTrue(TableRebalancer.isExternalViewConverged(offlineTableName, externalViewSegmentStates, idealStateSegmentStates, lowDiskMode, bestEfforts, null));
            }
        }
    }
}

@Test
public void testRebalance() throws Exception {
    int numServers = 3;
    for (int i = 0; i < numServers; i++) {
        addFakeServerInstanceToAutoJoinHelixCluster(SERVER_INSTANCE_ID_PREFIX + i, true);
    }
    TenantRebalancer tenantRebalancer = new DefaultTenantRebalancer(_helixResourceManager, _executorService);
    // tag all servers and brokers to test tenant
    addTenantTagToInstances(TENANT_NAME);
    // create 2 schemas
    addDummySchema(RAW_TABLE_NAME_A);
    addDummySchema(RAW_TABLE_NAME_B);
    // create 2 tables, one on each of test tenant and default tenant
    createTableWithSegments(RAW_TABLE_NAME_A, DEFAULT_TENANT_NAME);
    createTableWithSegments(RAW_TABLE_NAME_B, TENANT_NAME);
    // Add 3 more servers which will be tagged to default tenant
    int numServersToAdd = 3;
    for (int i = 0; i < numServersToAdd; i++) {
        addFakeServerInstanceToAutoJoinHelixCluster(SERVER_INSTANCE_ID_PREFIX + (numServers + i), true);
    }
    Map<String, Map<String, String>> oldSegmentAssignment = _helixResourceManager.getTableIdealState(OFFLINE_TABLE_NAME_B).getRecord().getMapFields();
    // rebalance the tables on test tenant
    TenantRebalanceConfig config = new TenantRebalanceConfig();
    config.setTenantName(TENANT_NAME);
    config.setVerboseResult(true);
    TenantRebalanceResult result = tenantRebalancer.rebalance(config);
    RebalanceResult rebalanceResult = result.getRebalanceTableResults().get(OFFLINE_TABLE_NAME_B);
    Map<String, Map<String, String>> rebalancedAssignment = rebalanceResult.getSegmentAssignment();
    // assignment should not change, with a NO_OP status as no now server is added to test tenant
    assertEquals(rebalanceResult.getStatus(), RebalanceResult.Status.NO_OP);
    assertEquals(oldSegmentAssignment, rebalancedAssignment);
    // rebalance the tables on default tenant
    config.setTenantName(DEFAULT_TENANT_NAME);
    result = tenantRebalancer.rebalance(config);
    // rebalancing default tenant should distribute the segment of table A over 6 servers
    rebalanceResult = result.getRebalanceTableResults().get(OFFLINE_TABLE_NAME_A);
    InstancePartitions partitions = rebalanceResult.getInstanceAssignment().get(InstancePartitionsType.OFFLINE);
    assertEquals(partitions.getPartitionToInstancesMap().get("0_0").size(), 6);
    // ensure the ideal state and external view converges
    assertTrue(waitForCompletion(result.getJobId()));
    TenantRebalanceProgressStats progressStats = getProgress(result.getJobId());
    assertTrue(progressStats.getTableRebalanceJobIdMap().containsKey(OFFLINE_TABLE_NAME_A));
    assertEquals(progressStats.getTableStatusMap().get(OFFLINE_TABLE_NAME_A), TenantRebalanceProgressStats.TableStatus.PROCESSED.name());
    Map<String, Map<String, String>> idealState = _helixResourceManager.getTableIdealState(OFFLINE_TABLE_NAME_A).getRecord().getMapFields();
    Map<String, Map<String, String>> externalView = _helixResourceManager.getTableExternalView(OFFLINE_TABLE_NAME_A).getRecord().getMapFields();
    assertEquals(idealState, externalView);
}

// This is a test to verify if Zk stats are pushed out correctly
@Test
void testZkObserverTracking() {
    PinotHelixResourceManager pinotHelixResourceManager = mock(PinotHelixResourceManager.class);
    // Mocking this. We will verify using numZkUpdate stat
    when(pinotHelixResourceManager.addControllerJobToZK(any(), any(), any())).thenReturn(true);
    ControllerMetrics controllerMetrics = Mockito.mock(ControllerMetrics.class);
    TableRebalanceContext retryCtx = new TableRebalanceContext();
    retryCtx.setConfig(new RebalanceConfig());
    ZkBasedTableRebalanceObserver observer = new ZkBasedTableRebalanceObserver("dummy", "dummyId", retryCtx, pinotHelixResourceManager);
    Map<String, Map<String, String>> source = new TreeMap<>();
    Map<String, Map<String, String>> target = new TreeMap<>();
    target.put("segment1", SegmentAssignmentUtils.getInstanceStateMap(Arrays.asList("host1", "host2", "host3"), ONLINE));
    source.put("segment2", SegmentAssignmentUtils.getInstanceStateMap(Arrays.asList("host2", "host3", "host4"), ONLINE));
    Set<String> segmentSet = new HashSet<>(source.keySet());
    segmentSet.addAll(target.keySet());
    TableRebalanceObserver.RebalanceContext rebalanceContext = new TableRebalanceObserver.RebalanceContext(-1, segmentSet, segmentSet);
    observer.onTrigger(TableRebalanceObserver.Trigger.START_TRIGGER, source, target, rebalanceContext);
    assertEquals(observer.getNumUpdatesToZk(), 1);
    observer.onTrigger(TableRebalanceObserver.Trigger.IDEAL_STATE_CHANGE_TRIGGER, source, source, rebalanceContext);
    observer.onTrigger(TableRebalanceObserver.Trigger.EXTERNAL_VIEW_TO_IDEAL_STATE_CONVERGENCE_TRIGGER, source, source, rebalanceContext);
    // START_TRIGGER will set up the ZK progress stats to have the diff between source and target. When calling the
    // triggers for IS and EV-IS, since source and source are compared, the diff will change for the IS trigger
    // but not for the EV-IS trigger, so ZK must be updated 1 extra time
    assertEquals(observer.getNumUpdatesToZk(), 2);
    observer.onTrigger(TableRebalanceObserver.Trigger.IDEAL_STATE_CHANGE_TRIGGER, source, target, rebalanceContext);
    observer.onTrigger(TableRebalanceObserver.Trigger.EXTERNAL_VIEW_TO_IDEAL_STATE_CONVERGENCE_TRIGGER, source, target, rebalanceContext);
    // Both of the changes above will update ZK for progress stats
    assertEquals(observer.getNumUpdatesToZk(), 4);
    // Try a rollback and this should trigger a ZK update as well
    observer.onRollback();
    assertEquals(observer.getNumUpdatesToZk(), 5);
}

@Test
void testDifferenceBetweenTableRebalanceStates() {
    Map<String, Map<String, String>> target = new TreeMap<>();
    target.put("segment1", SegmentAssignmentUtils.getInstanceStateMap(Arrays.asList("host1", "host2", "host3"), ONLINE));
    target.put("segment2", SegmentAssignmentUtils.getInstanceStateMap(Arrays.asList("host2", "host3", "host4"), ONLINE));
    // Stats when there's nothing to rebalance
    TableRebalanceProgressStats.RebalanceStateStats stats = ZkBasedTableRebalanceObserver.getDifferenceBetweenTableRebalanceStates(target, target);
    assertEquals(stats._segmentsToRebalance, 0);
    assertEquals(stats._segmentsMissing, 0);
    assertEquals(stats._percentSegmentsToRebalance, 0.0);
    // Stats when there's something to converge
    Map<String, Map<String, String>> current = new TreeMap<>();
