@Test
public void testJsonDeserializationSegmentStatusInfo() throws Exception {
    // JSON string representing SchemaInfo
    String json = "[\n" + "  {\n" + "    \"segmentStatus\": \"GOOD\",\n" + "    \"segmentName\": \"airlineStats_OFFLINE_16071_16071_0\"\n" + "  },\n" + "  {\n" + "    \"segmentStatus\": \"BAD\",\n" + "    \"segmentName\": \"airlineStats_OFFLINE_16072_16072_0\"\n" + "  },\n" + "  {\n" + "    \"segmentStatus\": \"UPDATING\",\n" + "    \"segmentName\": \"airlineStats_OFFLINE_16073_16073_0\"\n" + "  }\n" + "]";
    JsonNode jsonNode = JsonUtils.stringToJsonNode(json);
    List<SegmentStatusInfo> segmentStatusInfos = JsonUtils.jsonNodeToObject(jsonNode, new TypeReference<List<SegmentStatusInfo>>() {
    });
