@Test
public void testWithinQuota() throws InvalidConfigException {
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(OFFLINE_TABLE_NAME).setNumReplicas(NUM_REPLICAS).build();
    _tableSizeReader = mock(TableSizeReader.class);
    ControllerMetrics controllerMetrics = new ControllerMetrics(PinotMetricUtils.getPinotMetricsRegistry());
    PinotHelixResourceManager pinotHelixResourceManager = mock(PinotHelixResourceManager.class);
    when(pinotHelixResourceManager.getNumReplicas(eq(tableConfig))).thenReturn(NUM_REPLICAS);
    _storageQuotaChecker = new StorageQuotaChecker(_tableSizeReader, controllerMetrics, mock(LeadControllerManager.class), pinotHelixResourceManager, _controllerConf);
    tableConfig.setQuotaConfig(new QuotaConfig("2.8K", null));
    // No response from server, should pass without updating metrics
    mockTableSizeResult(OFFLINE_TABLE_NAME, -1, 0);
    assertTrue(isSegmentWithinQuota(tableConfig));
    assertFalse(MetricValueUtils.tableGaugeExists(controllerMetrics, OFFLINE_TABLE_NAME, ControllerGauge.OFFLINE_TABLE_ESTIMATED_SIZE));
    // Within quota but with missing segments, should pass without updating metrics
    mockTableSizeResult(OFFLINE_TABLE_NAME, 4 * 1024, 1);
    assertTrue(isSegmentWithinQuota(tableConfig));
    assertFalse(MetricValueUtils.tableGaugeExists(controllerMetrics, OFFLINE_TABLE_NAME, ControllerGauge.OFFLINE_TABLE_ESTIMATED_SIZE));
    // Exceed quota and with missing segments, should fail without updating metrics
    mockTableSizeResult(OFFLINE_TABLE_NAME, 8 * 1024, 1);
    assertFalse(isSegmentWithinQuota(tableConfig));
    assertFalse(MetricValueUtils.tableGaugeExists(controllerMetrics, OFFLINE_TABLE_NAME, ControllerGauge.OFFLINE_TABLE_ESTIMATED_SIZE));
    // Within quota without missing segments, should pass and update metrics
    mockTableSizeResult(OFFLINE_TABLE_NAME, 3 * 1024, 0);
    assertTrue(isSegmentWithinQuota(tableConfig));
    assertEquals(MetricValueUtils.getTableGaugeValue(controllerMetrics, OFFLINE_TABLE_NAME, ControllerGauge.OFFLINE_TABLE_ESTIMATED_SIZE), 3 * 1024);
    // Exceed quota without missing segments, should fail and update metrics
    mockTableSizeResult(OFFLINE_TABLE_NAME, 4 * 1024, 0);
    assertFalse(isSegmentWithinQuota(tableConfig));
    assertEquals(MetricValueUtils.getTableGaugeValue(controllerMetrics, OFFLINE_TABLE_NAME, ControllerGauge.OFFLINE_TABLE_ESTIMATED_SIZE), 4 * 1024);
}

@Test
public void testRebuildBrokerResourceWhenBrokerAdded() throws Exception {
    // Check that the first table we added doesn't need to be rebuilt(case where ideal state brokers and brokers in
    // broker resource are the same.
    String partitionName = _offlineTableConfig.getTableName();
    HelixAdmin helixAdmin = _helixManager.getClusterManagmentTool();
    IdealState idealState = HelixHelper.getBrokerIdealStates(helixAdmin, getHelixClusterName());
    // Ensure that the broker resource is not rebuilt.
    Assert.assertTrue(idealState.getInstanceSet(partitionName).equals(_helixResourceManager.getAllInstancesForBrokerTenant(TagNameUtils.DEFAULT_TENANT_NAME)));
    _helixResourceManager.rebuildBrokerResourceFromHelixTags(partitionName);
    // Add another table that needs to be rebuilt
    addDummySchema(TEST_TABLE_TWO);
    TableConfig offlineTableConfigTwo = new TableConfigBuilder(TableType.OFFLINE).setTableName(TEST_TABLE_TWO).build();
    _helixResourceManager.addTable(offlineTableConfigTwo);
    String partitionNameTwo = offlineTableConfigTwo.getTableName();
    // Add a new broker manually such that the ideal state is not updated and ensure that rebuild broker resource is
    // called
    final String brokerId = "Broker_localhost_2";
    InstanceConfig instanceConfig = new InstanceConfig(brokerId);
    instanceConfig.setInstanceEnabled(true);
    instanceConfig.setHostName("Broker_localhost");
    instanceConfig.setPort("2");
    helixAdmin.addInstance(getHelixClusterName(), instanceConfig);
    helixAdmin.addInstanceTag(getHelixClusterName(), instanceConfig.getInstanceName(), TagNameUtils.getBrokerTagForTenant(TagNameUtils.DEFAULT_TENANT_NAME));
    idealState = HelixHelper.getBrokerIdealStates(helixAdmin, getHelixClusterName());
    // Assert that the two don't equal before the call to rebuild the broker resource.
    Assert.assertTrue(!idealState.getInstanceSet(partitionNameTwo).equals(_helixResourceManager.getAllInstancesForBrokerTenant(TagNameUtils.DEFAULT_TENANT_NAME)));
    _helixResourceManager.rebuildBrokerResourceFromHelixTags(partitionNameTwo);
    idealState = HelixHelper.getBrokerIdealStates(helixAdmin, getHelixClusterName());
    // Assert that the two do equal after being rebuilt.
    Assert.assertTrue(idealState.getInstanceSet(partitionNameTwo).equals(_helixResourceManager.getAllInstancesForBrokerTenant(TagNameUtils.DEFAULT_TENANT_NAME)));
}

@Test
public void testPushTimePersistence() {
    SegmentMetadata segmentMetadata = SegmentMetadataMockUtils.mockSegmentMetadata(TEST_TABLE_NAME, TEST_SEGMENT_NAME);
    TEST_INSTANCE.getHelixResourceManager().addNewSegment(OFFLINE_TEST_TABLE_NAME, segmentMetadata, "downloadUrl");
    SegmentZKMetadata segmentZKMetadata = TEST_INSTANCE.getHelixResourceManager().getSegmentZKMetadata(OFFLINE_TEST_TABLE_NAME, TEST_SEGMENT_NAME);
    assertNotNull(segmentZKMetadata);
    long pushTime = segmentZKMetadata.getPushTime();
    // Check that the segment has been pushed in the last 30 seconds
    assertTrue(System.currentTimeMillis() - pushTime < 30_000);
    // Check that there is no refresh time
    assertEquals(segmentZKMetadata.getRefreshTime(), Long.MIN_VALUE);
    // Refresh the segment
    // NOTE: In order to send the refresh message, the segment need to be in the ExternalView
    String offlineTableName = TableNameBuilder.OFFLINE.tableNameWithType(TEST_TABLE_NAME);
    TestUtils.waitForCondition(aVoid -> {
        ExternalView externalView = TEST_INSTANCE.getHelixAdmin().getResourceExternalView(TEST_INSTANCE.getHelixClusterName(), offlineTableName);
        return externalView != null && externalView.getPartitionSet().contains(TEST_SEGMENT_NAME);
    }, 30_000L, "Failed to find the segment in the ExternalView");
    Mockito.when(segmentMetadata.getCrc()).thenReturn(Long.toString(System.nanoTime()));
    TEST_INSTANCE.getHelixResourceManager().refreshSegment(offlineTableName, segmentMetadata, segmentZKMetadata, EXPECTED_VERSION, "downloadUrl");
    segmentZKMetadata = TEST_INSTANCE.getHelixResourceManager().getSegmentZKMetadata(OFFLINE_TEST_TABLE_NAME, TEST_SEGMENT_NAME);
    assertNotNull(segmentZKMetadata);
    // Check that the segment still has the same push time
    assertEquals(segmentZKMetadata.getPushTime(), pushTime);
    // Check that the refresh time is in the last 30 seconds
    assertTrue(System.currentTimeMillis() - segmentZKMetadata.getRefreshTime() < 30_000L);
}

