@Test
public void testFunnelStepEventAccumulator() {
    for (int i = 0; i < NUM_ITERATIONS; i++) {
        int size = RANDOM.nextInt(1000);
        PriorityQueue<FunnelStepEvent> expected = new PriorityQueue<>();
        for (int j = 0; j < size; j++) {
            expected.add(new FunnelStepEvent(RANDOM.nextLong(), RANDOM.nextInt()));
        }
        byte[] bytes = ObjectSerDeUtils.serialize(expected);
        PriorityQueue<FunnelStepEvent> actual = ObjectSerDeUtils.deserialize(bytes, ObjectSerDeUtils.ObjectType.FunnelStepEventAccumulator);
        while (!actual.isEmpty()) {
            assertEquals(actual.poll(), expected.poll(), ERROR_MESSAGE);
        }
    }
    // Test empty queue
    PriorityQueue<FunnelStepEvent> empty = new PriorityQueue<>();
    PriorityQueue<FunnelStepEvent> deserialized = ObjectSerDeUtils.deserialize(ObjectSerDeUtils.serialize(empty), ObjectSerDeUtils.ObjectType.FunnelStepEventAccumulator);
    assertTrue(deserialized.isEmpty());
}

