public void testDateTimeConvert() {
    // EPOCH to EPOCH
    // Test bucketing to 15 minutes
    testDateTimeConvert(1505898960000L, /* 20170920T02:16:00 */
    "1:MILLISECONDS:EPOCH", "1:MILLISECONDS:EPOCH", "15:MINUTES", 1505898900000L);
    // Test input which should create no change
    testDateTimeConvert(1505898960000L, /* 20170920T02:16:00 */
    "1:MILLISECONDS:EPOCH", "1:MILLISECONDS:EPOCH", "1:MILLISECONDS", 1505898960000L);
    // Test conversion from millis to hours
    testDateTimeConvert(1505902560000L, /* 20170920T03:16:00 */
    "1:MILLISECONDS:EPOCH", "1:HOURS:EPOCH", "1:HOURS", 418306L);
    // Test conversion from 5 minutes to hours
    testDateTimeConvert(5019675L, /* 20170920T03:15:00 */
    "5:MINUTES:EPOCH", "1:HOURS:EPOCH", "1:HOURS", 418306L);
    // Test conversion from 5 minutes to millis and bucketing to hours
    testDateTimeConvert(5019675L, /* 20170920T03:15:00 */
    "5:MINUTES:EPOCH", "1:MILLISECONDS:EPOCH", "1:HOURS", 1505901600000L);
    testDateTimeConvert(null, "5:MINUTES:EPOCH", "1:MILLISECONDS:EPOCH", "1:HOURS", null);
    // test custom bucketing time zone
    testDateTimeConvert(5019675L, /* 20170920T03:15:00 */
    "5:MINUTES:EPOCH", "1:MILLISECONDS:EPOCH", "1:HOURS", "UTC", 1505901600000L);
    // test with custom bucketing time zone
    testDateTimeConvert(5019675L, /* 20170920T03:15:00 */
    "5:MINUTES:EPOCH", "1:MILLISECONDS:EPOCH", "4:HOURS", 1505894400000L);
