@Test
void testPartition() throws Exception {
    TableConfig partitionedTableConfig = getTableConfigBuilder().setSegmentPartitionConfig(new SegmentPartitionConfig(Map.of(PARTITIONED_COLUMN_NAME, new ColumnPartitionConfig(PARTITION_FUNCTION_NAME, NUM_PARTITIONS)))).build();
    IndexLoadingConfig indexLoadingConfig = new IndexLoadingConfig(partitionedTableConfig, SCHEMA);
    ImmutableSegmentDataManager segmentWithPartition = createImmutableSegmentDataManager(indexLoadingConfig, "partitionWithModulo", generateRows());
    // when segment has no partition AND tableConfig has partitions then needRefresh = true
    StaleSegment response = BASE_TABLE_DATA_MANAGER.isSegmentStale(indexLoadingConfig, IMMUTABLE_SEGMENT_DATA_MANAGER);
    assertTrue(response.isStale());
    assertEquals(response.getReason(), "partition function added: partitionedColumn");
    // when segment has partitions AND tableConfig has no partitions, then needRefresh = false
    assertFalse(BASE_TABLE_DATA_MANAGER.isSegmentStale(INDEX_LOADING_CONFIG, segmentWithPartition).isStale());
    // when # of partitions is different, then needRefresh = true
    TableConfig partitionedTableConfig40 = getTableConfigBuilder().setSegmentPartitionConfig(new SegmentPartitionConfig(Map.of(PARTITIONED_COLUMN_NAME, new ColumnPartitionConfig(PARTITION_FUNCTION_NAME, 40)))).build();
    response = BASE_TABLE_DATA_MANAGER.isSegmentStale(new IndexLoadingConfig(partitionedTableConfig40, SCHEMA), segmentWithPartition);
    assertTrue(response.isStale());
    assertEquals(response.getReason(), "num partitions changed: partitionedColumn");
    // when partition function is different, then needRefresh = true
    TableConfig partitionedTableConfigMurmur = getTableConfigBuilder().setSegmentPartitionConfig(new SegmentPartitionConfig(Map.of(PARTITIONED_COLUMN_NAME, new ColumnPartitionConfig("murmur", NUM_PARTITIONS)))).build();
    response = BASE_TABLE_DATA_MANAGER.isSegmentStale(new IndexLoadingConfig(partitionedTableConfigMurmur, SCHEMA), segmentWithPartition);
    assertTrue(response.isStale());
    assertEquals(response.getReason(), "partition function name changed: partitionedColumn");
}

