@Test
public void testShouldNotSkipUnfilteredMessagesIfNotIndexedAndTimeThresholdIsReached() throws Exception {
    final int segmentTimeThresholdMins = 10;
    TimeSupplier timeSupplier = new TimeSupplier() {

        @Override
        public Long get() {
            long now = System.currentTimeMillis();
            // now() is called once in the run() method, then once on setting consumeStartTime, once before each batch
            // reading and once for every row indexation
            if (_timeCheckCounter.incrementAndGet() <= FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS + 5) {
                return now;
            }
            // Exceed segment time threshold
            return now + TimeUnit.MINUTES.toMillis(segmentTimeThresholdMins + 1);
        }
    };
    try (FakeRealtimeSegmentDataManager segmentDataManager = createFakeSegmentManager(true, timeSupplier, String.valueOf(FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS * 2), segmentTimeThresholdMins + "m", null)) {
        segmentDataManager._stubConsumeLoop = false;
        segmentDataManager._state.set(segmentDataManager, RealtimeSegmentDataManager.State.INITIAL_CONSUMING);
        RealtimeSegmentDataManager.PartitionConsumer consumer = segmentDataManager.createPartitionConsumer();
        final LongMsgOffset endOffset = new LongMsgOffset(START_OFFSET_VALUE + FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS);
        segmentDataManager._consumeOffsets.add(endOffset);
        final SegmentCompletionProtocol.Response response = new SegmentCompletionProtocol.Response(new SegmentCompletionProtocol.Response.Params().withStatus(SegmentCompletionProtocol.ControllerResponseStatus.COMMIT).withStreamPartitionMsgOffset(endOffset.toString()));
        segmentDataManager._responses.add(response);
        consumer.run();
        // millis() is called first in run before consumption, then once on setting consumeStartTime, then once for
        // each batch and once for each message in the batch, then once more when metrics are updated after each batch
        // is processed and then 4 more times in run() after consume loop
        Assert.assertEquals(timeSupplier._timeCheckCounter.get(), FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS + 9);
        Assert.assertEquals(((LongMsgOffset) segmentDataManager.getCurrentOffset()).getOffset(), START_OFFSET_VALUE + FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS);
        Assert.assertEquals(segmentDataManager.getSegment().getNumDocsIndexed(), FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS);
        Assert.assertEquals(segmentDataManager.getSegment().getSegmentMetadata().getTotalDocs(), FakeStreamConfigUtils.SEGMENT_FLUSH_THRESHOLD_ROWS);
    }
}

