@Test(dataProvider = "fieldsAndIndexTypes")
public void testAddIndex(TestCase testCase) {
    try {
        // create schema copy to avoid side effects between test cases
        // e.g. timestamp index creates additional virtual columns
        Schema schema = Schema.fromString(_schemas.get(testCase._schemaIndex).toPrettyJsonString());
        String indexType = testCase._indexType;
        String schemaName = schema.getSchemaName();
        FieldSpec field = schema.getFieldSpecFor(COLUMN_NAME);
        TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(schema.getSchemaName()).setFieldConfigList(new ArrayList<>()).build();
        IndexingConfig idxCfg = tableConfig.getIndexingConfig();
        FieldConfig.EncodingType encoding = schemaName.startsWith("raw") ? FieldConfig.EncodingType.RAW : FieldConfig.EncodingType.DICTIONARY;
        List<FieldConfig.IndexType> indexTypes = new ArrayList<>();
        Map<String, String> properties = new HashMap<>();
        ObjectNode indexes = new ObjectNode(JsonNodeFactory.instance);
        TimestampConfig tstmpConfig = null;
        // table will be created from scratch for each run;
        FieldConfig config = null;
        switch(indexType) {
            case "bloom_filter":
                /* bloom filter. Maybe we should call it bloom filter index to be consistent ?
            {
              "tableName": "somePinotTable",
              "fieldConfigList": [
                {
                  "name": "playerID",
                  "indexes": {
                    "bloom": {}
                  }
                },
                ...
              ],
              ...
            } */
                // no params
                indexes.put("bloom", JsonUtils.newObjectNode());
                break;
            case "fst_index":
                /* fst index / text index
              "fieldConfigList":[
              {
                "name":"text_col_1",
                "encodingType":"DICTIONARY",
                "indexType":"FST"
                }
                ]
             */
                indexTypes.add(FieldConfig.IndexType.FST);
                break;
            case "h3_index":
                /* geospatial - requires dictionary be disabled
              {
              "fieldConfigList": [
                {
                  "name": "location_st_point",
                  "encodingType":"RAW", // this actually disables the dictionary
                  "indexes": {
                    "h3": {
                      "resolutions": [13, 5, 6]
                    }
                  }
                }
              ],
              ...
            }
             */
                JsonNode resolutions = JsonUtils.stringToJsonNode("{\"resolutions\": [13, 5, 6]}");
                indexes.put("h3", resolutions);
                break;
            case "inverted_index":
                /* inverted index (bitmap or sorted). requires dictionary
               -> new:
                       {
                      "fieldConfigList": [
                        {
                          "name": "theColumnName",
                          "indexes": {
                            "inverted": {}
                          }
                        }
                      ],
                    }
                 old:
               -> "tableIndexConfig": {  "invertedIndexColumns": ["uuid"], */
                // no params, has to be dictionary
                indexes.put("inverted", new ObjectNode(JsonNodeFactory.instance));
                break;
            case "json_index":
                /* json index (string or json column), should be no-dictionary
               {
              "fieldConfigList": [
                {
                  "name": "person",
                  "indexes": {
                    "json": {}
                  }
                }
              ],
              ...
              } */
                // no params, should be no dictionary, only string or json
                indexes.put("json", new ObjectNode(JsonNodeFactory.instance));
                break;
            case "native_text_index":
                /* native text index
            "fieldConfigList":[
              {
                 "name":"text_col_1",
                 "encodingType":"RAW",
                 "indexTypes": ["TEXT"],
                 "properties":{"fstType":"native"}
              }
            ] */
                indexTypes.add(FieldConfig.IndexType.TEXT);
                properties.put("fstType", "native");
                break;
            case "text_index":
                /* text index
            "fieldConfigList":[
              {
                 "name":"text_col_1",
                 "encodingType":"RAW",
                 "indexTypes":["TEXT"]
              }
            ] */
                indexTypes.add(FieldConfig.IndexType.TEXT);
                break;
            case "range_index":
                /* range index (supported for dictionary encoded columns of any type as well as raw encoded columns
            of a numeric type)
                {
                  "tableIndexConfig": {
                      "rangeIndexColumns": [
                          "column_name",
                          ...
                      ],
                      ...
                  }
              }
             */
                if (idxCfg.getRangeIndexColumns() == null) {
                    idxCfg.setRangeIndexColumns(new ArrayList<>());
                }
                idxCfg.getRangeIndexColumns().add(field.getName());
                break;
            case "startree_index":
                /* star tree
              "tableIndexConfig": {
                "starTreeIndexConfigs": [{
                  "dimensionsSplitOrder": [
                    "Country",
                    "Browser",
                    "Locale"
                  ],
                  "skipStarNodeCreationForDimensions": [
                  ],
                  "functionColumnPairs": [
                    "SUM__Impressions"
                  ],
                  "maxLeafRecords": 1
                }],
                ...
              }
             */
                if (idxCfg.getStarTreeIndexConfigs() == null) {
                    idxCfg.setStarTreeIndexConfigs(new ArrayList<>());
                }
                StarTreeIndexConfig stIdxCfg = new StarTreeIndexConfig(List.of(COLUMN_NAME), Collections.emptyList(), List.of("SUM__col"), Collections.emptyList(), 1);
                idxCfg.getStarTreeIndexConfigs().add(stIdxCfg);
                break;
            case "timestamp_index":
                /* timestamp index
            {
            "fieldConfigList": [
              {
                "name": "ts",
                "timestampConfig": {
                  "granularities": [
                    "DAY",
                    "WEEK",
                    "MONTH"
                  ]
                }
              } */
                tstmpConfig = new TimestampConfig(List.of(TimestampIndexGranularity.DAY, TimestampIndexGranularity.WEEK, TimestampIndexGranularity.MONTH));
                break;
            case "vector_index":
                /* vector
            "fieldConfigList": [
            {
              "encodingType": "RAW",
              "indexType": "VECTOR",
              "name": "embedding",
              "properties": {
                "vectorIndexType": "HNSW",
                "vectorDimension": 1536,
                "vectorDistanceFunction": "COSINE",
                "version": 1
              }
            } */
                indexTypes.add(FieldConfig.IndexType.VECTOR);
                properties.put("vectorIndexType", "HNSW");
                properties.put("vectorDimension", "1536");
                properties.put("vectorDistanceFunction", "COSINE");
                properties.put("version", "1");
                break;
            default:
                throw new IllegalArgumentException("Unexpected index type " + indexType);
        }
        config = new FieldConfig(field.getName(), encoding, null, indexTypes, null, tstmpConfig, indexes, properties, null);
        tableConfig.getFieldConfigList().add(config);
        //ImmutableSegmentDataManager segmentDataManager =
        Map<String, Map<String, Integer>> indexStats = createImmutableSegment(tableConfig, schema, indexType, generateRows(schema));
        if ("timestamp_index".equals(indexType)) {
            // this index is built on virtual columns, not on the timestamp one
            Assert.assertEquals(indexStats.get(COLUMN_DAY_NAME).get("range_index"), 1);
            Assert.assertEquals(indexStats.get(COLUMN_WEEK_NAME).get("range_index"), 1);
            Assert.assertEquals(indexStats.get(COLUMN_MONTH_NAME).get("range_index"), 1);
        } else {
            String expectedType;
            if ("native_text_index".equals(indexType)) {
                expectedType = "text_index";
            } else {
                expectedType = indexType;
            }
            Assert.assertEquals(indexStats.get(COLUMN_NAME).get(expectedType), 1);
        }
    } catch (Throwable t) {
        testCase._error = t;
        //throw t;
    } finally {
        _allResults.add(testCase);
    }
    if (testCase._expectedSuccess == null) {
        Assert.fail("No expected status found for test case: " + testCase);
    } else if (testCase._expectedSuccess && testCase._error != null) {
        Assert.fail("Expected success for test case: " + testCase + " but got error: " + testCase._error);
    } else if (!testCase._expectedSuccess && !testCase.getErrorMessage().equals(testCase._expectedMessage)) {
        Assert.fail("Expected error: \"" + testCase._expectedMessage + "\" for test case: " + testCase + " but got: \"" + testCase.getErrorMessage() + "\"");
    }
}

@Test
public void testConcurrentIndexedTable() throws InterruptedException, TimeoutException, ExecutionException {
    QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT SUM(m1), MAX(m2) FROM testTable GROUP BY d1, d2, d3 ORDER BY SUM(m1)");
    DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "d3", "sum(m1)", "max(m2)" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    IndexedTable indexedTable = new ConcurrentIndexedTable(dataSchema, false, queryContext, 5, TRIM_SIZE, TRIM_THRESHOLD, INITIAL_CAPACITY, Executors.newCachedThreadPool());
    // 3 threads upsert together
    // a inserted 6 times (60), b inserted 5 times (50), d inserted 2 times (20)
    // inserting 14 unique records
    // c (10000) and f (20000) should be trimmed out no matter what
    // a (60) and i (500) trimmed out after size()
    ExecutorService executorService = Executors.newFixedThreadPool(10);
    try {
        Callable<Void> c1 = () -> {
            indexedTable.upsert(getKey(new Object[] { "a", 1, 10d }), getRecord(new Object[] { "a", 1, 10d, 10d, 100d }));
            indexedTable.upsert(getKey(new Object[] { "b", 2, 20d }), getRecord(new Object[] { "b", 2, 20d, 10d, 200d }));
            indexedTable.upsert(getKey(new Object[] { "c", 3, 30d }), // eviction candidate
            getRecord(new Object[] { "c", 3, 30d, 10000d, 300d }));
            indexedTable.upsert(getKey(new Object[] { "d", 4, 40d }), getRecord(new Object[] { "d", 4, 40d, 10d, 400d }));
            indexedTable.upsert(getKey(new Object[] { "d", 4, 40d }), getRecord(new Object[] { "d", 4, 40d, 10d, 400d }));
            indexedTable.upsert(getKey(new Object[] { "e", 5, 50d }), getRecord(new Object[] { "e", 5, 50d, 10d, 500d }));
            return null;
        };
        Callable<Void> c2 = () -> {
            indexedTable.upsert(getKey(new Object[] { "a", 1, 10d }), getRecord(new Object[] { "a", 1, 10d, 10d, 100d }));
            indexedTable.upsert(getKey(new Object[] { "f", 6, 60d }), // eviction candidate
            getRecord(new Object[] { "f", 6, 60d, 20000d, 600d }));
            indexedTable.upsert(getKey(new Object[] { "g", 7, 70d }), getRecord(new Object[] { "g", 7, 70d, 10d, 700d }));
            indexedTable.upsert(getKey(new Object[] { "b", 2, 20d }), getRecord(new Object[] { "b", 2, 20d, 10d, 200d }));
            indexedTable.upsert(getKey(new Object[] { "b", 2, 20d }), getRecord(new Object[] { "b", 2, 20d, 10d, 200d }));
            indexedTable.upsert(getKey(new Object[] { "h", 8, 80d }), getRecord(new Object[] { "h", 8, 80d, 10d, 800d }));
            indexedTable.upsert(getKey(new Object[] { "a", 1, 10d }), getRecord(new Object[] { "a", 1, 10d, 10d, 100d }));
            indexedTable.upsert(getKey(new Object[] { "i", 9, 90d }), getRecord(new Object[] { "i", 9, 90d, 500d, 900d }));
            return null;
        };
        Callable<Void> c3 = () -> {
            indexedTable.upsert(getKey(new Object[] { "a", 1, 10d }), getRecord(new Object[] { "a", 1, 10d, 10d, 100d }));
            indexedTable.upsert(getKey(new Object[] { "j", 10, 100d }), getRecord(new Object[] { "j", 10, 100d, 10d, 1000d }));
            indexedTable.upsert(getKey(new Object[] { "b", 2, 20d }), getRecord(new Object[] { "b", 2, 20d, 10d, 200d }));
            indexedTable.upsert(getKey(new Object[] { "k", 11, 110d }), getRecord(new Object[] { "k", 11, 110d, 10d, 1100d }));
            indexedTable.upsert(getKey(new Object[] { "a", 1, 10d }), getRecord(new Object[] { "a", 1, 10d, 10d, 100d }));
            indexedTable.upsert(getKey(new Object[] { "l", 12, 120d }), getRecord(new Object[] { "l", 12, 120d, 10d, 1200d }));
            indexedTable.upsert(getKey(new Object[] { "a", 1, 10d }), // trimming candidate
            getRecord(new Object[] { "a", 1, 10d, 10d, 100d }));
            indexedTable.upsert(getKey(new Object[] { "b", 2, 20d }), getRecord(new Object[] { "b", 2, 20d, 10d, 200d }));
            indexedTable.upsert(getKey(new Object[] { "m", 13, 130d }), getRecord(new Object[] { "m", 13, 130d, 10d, 1300d }));
            indexedTable.upsert(getKey(new Object[] { "n", 14, 140d }), getRecord(new Object[] { "n", 14, 140d, 10d, 1400d }));
            return null;
        };
        List<Future<Void>> futures = executorService.invokeAll(Arrays.asList(c1, c2, c3));
        for (Future future : futures) {
            future.get(10, TimeUnit.SECONDS);
        }
        indexedTable.finish(false);
        Assert.assertEquals(indexedTable.size(), 5);
        checkEvicted(indexedTable, "c", "f");
    } finally {
        executorService.shutdown();
    }
}

@Test(dataProvider = "initDataProvider")
public void testNonConcurrentIndexedTable(String orderBy, List<String> survivors) {
    QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT SUM(m1), MAX(m2) FROM testTable GROUP BY d1, d2, d3, d4 ORDER BY " + orderBy);
    DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "d3", "d4", "sum(m1)", "max(m2)" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    // Test SimpleIndexedTable
    IndexedTable indexedTable = new SimpleIndexedTable(dataSchema, false, queryContext, 5, TRIM_SIZE, TRIM_THRESHOLD, INITIAL_CAPACITY, Executors.newCachedThreadPool());
    IndexedTable mergeTable = new SimpleIndexedTable(dataSchema, false, queryContext, 10, TRIM_SIZE, TRIM_THRESHOLD, INITIAL_CAPACITY, Executors.newCachedThreadPool());
    testNonConcurrent(indexedTable, mergeTable);
    indexedTable.finish(true);
    checkSurvivors(indexedTable, survivors);
    // Test ConcurrentIndexedTable
    indexedTable = new ConcurrentIndexedTable(dataSchema, false, queryContext, 5, TRIM_SIZE, TRIM_THRESHOLD, INITIAL_CAPACITY, Executors.newCachedThreadPool());
    mergeTable = new SimpleIndexedTable(dataSchema, false, queryContext, 10, TRIM_SIZE, TRIM_THRESHOLD, INITIAL_CAPACITY, Executors.newCachedThreadPool());
    testNonConcurrent(indexedTable, mergeTable);
    indexedTable.finish(true);
    checkSurvivors(indexedTable, survivors);
}

