@Test
public void testGridDistance() throws IOException {
    H3CoreV3 h3CoreV3 = H3CoreV3.newInstance();
    // Test points in San Francisco
    double lat1 = 37.7749;
    double lon1 = -122.4194;
    double lat2 = 37.7833;
    double lon2 = -122.4167;
    int resolution = 9;
    // Convert points to H3 indexes
    long h3Index1 = h3CoreV3.geoToH3(lat1, lon1, resolution);
    long h3Index2 = h3CoreV3.geoToH3(lat2, lon2, resolution);
    // Calculate expected grid distance
    long expectedDistance = 0;
    for (int k = 1; k <= 100; k++) {
        java.util.List<java.util.List<Long>> ringsWithDistances = h3CoreV3.kRingDistances(h3Index1, k);
        boolean found = false;
        for (int distance = 0; distance < ringsWithDistances.size(); distance++) {
            if (ringsWithDistances.get(distance).contains(h3Index2)) {
                expectedDistance = distance;
                found = true;
                break;
            }
        }
        if (found) {
            break;
        }
    }
    // Create an array of expected values with size NUM_ROWS
    long[] expectedValues = new long[NUM_ROWS];
    Arrays.fill(expectedValues, expectedDistance);
    // Test the function
    ExpressionContext expression = ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.TRANSFORM, "gridDistance", Arrays.asList(ExpressionContext.forLiteral(FieldSpec.DataType.LONG, h3Index1), ExpressionContext.forLiteral(FieldSpec.DataType.LONG, h3Index2))));
    TransformFunction transformFunction = TransformFunctionFactory.get(expression, _dataSourceMap);
    testTransformFunction(transformFunction, expectedValues);
    // Test with same point (distance should be 0)
    Arrays.fill(expectedValues, 0);
    expression = ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.TRANSFORM, "gridDistance", Arrays.asList(ExpressionContext.forLiteral(FieldSpec.DataType.LONG, h3Index1), ExpressionContext.forLiteral(FieldSpec.DataType.LONG, h3Index1))));
    transformFunction = TransformFunctionFactory.get(expression, _dataSourceMap);
    testTransformFunction(transformFunction, expectedValues);
}

