@Test
void canBeVisited() {
    // Given a visitor
    MultiValueVisitor<Integer> valueLengthVisitor = Mockito.spy(createValueLengthVisitor());
    // When int predicate is used
    InPredicate predicate = new InPredicate(ExpressionContext.forIdentifier("ident"), Lists.newArrayList("1", "2"));
    InPredicateEvaluatorFactory.InRawPredicateEvaluator intEvaluator = InPredicateEvaluatorFactory.newRawValueBasedEvaluator(predicate, FieldSpec.DataType.INT);
    // Only the int[] method is called
    int length = intEvaluator.accept(valueLengthVisitor);
    Assert.assertEquals(length, 2);
    Mockito.verify(valueLengthVisitor).visitInt(new int[] { 2, 1 });
    Mockito.verifyNoMoreInteractions(valueLengthVisitor);
    // And given a string predicate
    InPredicateEvaluatorFactory.InRawPredicateEvaluator strEvaluator = InPredicateEvaluatorFactory.newRawValueBasedEvaluator(predicate, FieldSpec.DataType.STRING);
    // Only the string[] method is called
    length = strEvaluator.accept(valueLengthVisitor);
    Assert.assertEquals(length, 2);
    Mockito.verify(valueLengthVisitor).visitString(new String[] { "2", "1" });
    Mockito.verifyNoMoreInteractions(valueLengthVisitor);
}

@Test
public void testIntPredicateEvaluators() {
    int intValue = _random.nextInt();
    String stringValue = Integer.toString(intValue);
    EqPredicate eqPredicate = new EqPredicate(COLUMN_EXPRESSION, stringValue);
    PredicateEvaluator eqPredicateEvaluator = EqualsPredicateEvaluatorFactory.newRawValueBasedEvaluator(eqPredicate, FieldSpec.DataType.INT);
    NotEqPredicate notEqPredicate = new NotEqPredicate(COLUMN_EXPRESSION, stringValue);
    PredicateEvaluator neqPredicateEvaluator = NotEqualsPredicateEvaluatorFactory.newRawValueBasedEvaluator(notEqPredicate, FieldSpec.DataType.INT);
    Assert.assertTrue(eqPredicateEvaluator.applySV(intValue));
    Assert.assertFalse(neqPredicateEvaluator.applySV(intValue));
    int[] randomInts = new int[NUM_MULTI_VALUES];
    PredicateEvaluatorTestUtils.fillRandom(randomInts);
    randomInts[_random.nextInt(NUM_MULTI_VALUES)] = intValue;
    Assert.assertTrue(eqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES));
    Assert.assertFalse(neqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES));
    for (int i = 0; i < 100; i++) {
        int random = _random.nextInt();
        Assert.assertEquals(eqPredicateEvaluator.applySV(random), (random == intValue));
        Assert.assertEquals(neqPredicateEvaluator.applySV(random), (random != intValue));
        PredicateEvaluatorTestUtils.fillRandom(randomInts);
        Assert.assertEquals(eqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES), ArrayUtils.contains(randomInts, intValue));
        Assert.assertEquals(neqPredicateEvaluator.applyMV(randomInts, NUM_MULTI_VALUES), !ArrayUtils.contains(randomInts, intValue));
    }
}

