public void testAdditionTransformFunction() {
    ExpressionContext expression = RequestContextUtils.getExpression(String.format("add(%s,%s,%s,%s,%s)", INT_SV_COLUMN, LONG_SV_COLUMN, FLOAT_SV_COLUMN, DOUBLE_SV_COLUMN, STRING_SV_COLUMN));
