    Assert.assertTrue(transformFunction instanceof ModuloTransformFunction);
    for (int i = 0; i < NUM_ROWS; i++) {
        expectedValues[i] = (((((12d % Double.parseDouble(_stringSVValues[i])) % _doubleSVValues[i]) % (((double) _floatSVValues[i] % (double) _longSVValues[i]) % 0.34)) % (double) _intSVValues[i]) % _doubleSVValues[i]);
    }
    testTransformFunction(transformFunction, expectedValues);
}

