@Test
public void testCancelPlanNode() {
    CountDownLatch ready = new CountDownLatch(20);
    List<PlanNode> planNodes = new ArrayList<>();
    for (int i = 0; i < 20; i++) {
        planNodes.add(() -> {
            ready.countDown();
            return null;
        });
    }
    // This planNode will keep the planning running and wait to be cancelled.
    CountDownLatch hold = new CountDownLatch(1);
    planNodes.add(() -> {
        try {
            hold.await();
            return null;
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    });
    _queryContext.setEndTimeMs(System.currentTimeMillis() + Server.DEFAULT_QUERY_EXECUTOR_TIMEOUT_MS);
    CombinePlanNode combinePlanNode = new CombinePlanNode(planNodes, _queryContext, _executorService, null);
    AtomicReference<Exception> exp = new AtomicReference<>();
    // Avoid early finalization by not using Executors.newSingleThreadExecutor (java <= 20, JDK-8145304)
    ExecutorService combineExecutor = Executors.newFixedThreadPool(1);
    try {
        Future<?> future = combineExecutor.submit(() -> {
            try {
                return combinePlanNode.run();
            } catch (Exception e) {
                exp.set(e);
                throw e;
            }
        });
        ready.await();
        // At this point, the combinePlanNode is or will be waiting on future.get() for all sub planNodes, and the
        // waiting can be cancelled as below.
        future.cancel(true);
    } catch (Exception e) {
        Assert.fail();
    } finally {
        combineExecutor.shutdownNow();
    }
    TestUtils.waitForCondition((aVoid) -> exp.get() instanceof QueryCancelledException, 10_000, "Should have been cancelled");
}

@Test
public void testConsistentSnapshot() throws Exception {
    IndexSegment segment = mock(IndexSegment.class);
    SegmentMetadata meta = mock(SegmentMetadata.class);
    when(segment.getSegmentMetadata()).thenReturn(meta);
    ThreadSafeMutableRoaringBitmap bitmap = new ThreadSafeMutableRoaringBitmap();
    when(segment.getValidDocIds()).thenReturn(bitmap);
    AtomicInteger numDocs = new AtomicInteger(0);
    when(meta.getTotalDocs()).then((Answer<Integer>) invocationOnMock -> numDocs.get());
    QueryContext queryContext = mock(QueryContext.class);
    when(queryContext.getFilter()).thenReturn(null);
    numDocs.set(3);
    bitmap.add(0);
    bitmap.add(1);
    bitmap.add(2);
    // Continuously update the last value by moving it one doc id forward
    // Follow the order of MutableIndexSegmentImpl: first add the row, update the doc count and then change the
    // validDocId bitmap
    Thread updater = new Thread(() -> {
        for (int i = 3; i < 10_000_000; i++) {
            numDocs.incrementAndGet();
            bitmap.replace(i - 2, i);
        }
    });
    updater.start();
    // Result should be invariant - always exactly 3 docs
    for (int i = 0; i < 10_000; i++) {
        SegmentContext segmentContext = new SegmentContext(segment);
        segmentContext.setQueryableDocIdsSnapshot(UpsertUtils.getQueryableDocIdsSnapshotFromSegment(segment));
        assertEquals(getNumberOfFilteredDocs(segmentContext, queryContext), 3);
    }
    updater.join();
}

