@Test
void aggregationAllNullsWithNullHandlingDisabled() {
    new DataTypeScenario(FieldSpec.DataType.INT).getDeclaringTable(false).onFirstInstance("myField", "null", "null", "null").andOnSecondInstance("myField", "null", "null").whenQuery("select arrayagg(myField, 'INT') from testTable").thenResultIs(new Object[] { new int[] { Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE } });
}

@Test
void aggregationAllNullsWithNullHandlingEnabled() {
    new DataTypeScenario(FieldSpec.DataType.LONG).getDeclaringTable(true).onFirstInstance("myField", "null", "null", "null").andOnSecondInstance("myField", "null", "null").whenQuery("select arrayagg(myField, 'LONG') from testTable").thenResultIs(new Object[] { new long[0] });
}

@Test
void aggregationGroupBySVAllNullsWithNullHandlingDisabled() {
    new DataTypeScenario(FieldSpec.DataType.FLOAT).getDeclaringTable(false).onFirstInstance("myField", "null", "null", "null").andOnSecondInstance("myField", "null", "null").whenQuery("select 'literal', arrayagg(myField, 'FLOAT') from testTable group by 'literal'").thenResultIs(new Object[] { "literal", new float[] { Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY } });
}

@Test
void aggregationGroupBySVAllNullsWithNullHandlingEnabled() {
    new DataTypeScenario(FieldSpec.DataType.DOUBLE).getDeclaringTable(true).onFirstInstance("myField", "null", "null", "null").andOnSecondInstance("myField", "null", "null").whenQuery("select 'literal', arrayagg(myField, 'DOUBLE') from testTable group by 'literal'").thenResultIs(new Object[] { "literal", new double[0] });
}

@Test
void aggregationIntWithNullHandlingDisabled() {
    // Use repeated segment values because order of processing across segments isn't deterministic and not relevant
    // to this test
    new DataTypeScenario(FieldSpec.DataType.INT).getDeclaringTable(false).onFirstInstance("myField", "1", "null", "2").andOnSecondInstance("myField", "1", "null", "2").whenQuery("select arrayagg(myField, 'INT') from testTable").thenResultIs(new Object[] { new int[] { 1, Integer.MIN_VALUE, 2, 1, Integer.MIN_VALUE, 2 } });
}

@Test
void aggregationIntWithNullHandlingEnabled() {
    new DataTypeScenario(FieldSpec.DataType.INT).getDeclaringTable(true).onFirstInstance("myField", "1", "null", "2").andOnSecondInstance("myField", "1", "null", "2").whenQuery("select arrayagg(myField, 'INT') from testTable").thenResultIs(new Object[] { new int[] { 1, 2, 1, 2 } });
}

@Test
void aggregationDistinctIntWithNullHandlingDisabled() {
    // Use a single value in the segment because ordering is currently not deterministic due to the use of a hashset in
    // distinct array agg
    new DataTypeScenario(FieldSpec.DataType.INT).getDeclaringTable(false).onFirstInstance("myField", "null", "null").whenQuery("select arrayagg(myField, 'INT', true) from testTable").thenResultIs(new Object[] { new int[] { Integer.MIN_VALUE } });
}

@Test
void aggregationDistinctIntWithNullHandlingEnabled() {
    new DataTypeScenario(FieldSpec.DataType.INT).getDeclaringTable(true).onFirstInstance("myField", "1", "null", "1").whenQuery("select arrayagg(myField, 'INT', true) from testTable").thenResultIs(new Object[] { new int[] { 1 } });
}

@Test
void aggregationGroupBySVIntWithNullHandlingDisabled() {
    new DataTypeScenario(FieldSpec.DataType.INT).getDeclaringTable(false).onFirstInstance("myField", "1", "2", "null").andOnSecondInstance("myField", "1", "2", "null").whenQuery("select myField, arrayagg(myField, 'INT') from testTable group by myField order by myField").thenResultIs(new Object[] { Integer.MIN_VALUE, new int[] { Integer.MIN_VALUE, Integer.MIN_VALUE } }, new Object[] { 1, new int[] { 1, 1 } }, new Object[] { 2, new int[] { 2, 2 } });
