@Test
public void testDoubleArrayAggMultipleBlocks() {
    ArrayAggDistinctDoubleFunction arrayAggDistinctDoubleFunction = new ArrayAggDistinctDoubleFunction(ExpressionContext.forIdentifier("myField"), false);
    AggregationResultHolder aggregationResultHolder = arrayAggDistinctDoubleFunction.createAggregationResultHolder();
    arrayAggDistinctDoubleFunction.aggregate(2, aggregationResultHolder, Map.of(ExpressionContext.forIdentifier("myField"), SyntheticBlockValSets.Double.create(null, new double[] { 1.0, 2.0 })));
    arrayAggDistinctDoubleFunction.aggregate(2, aggregationResultHolder, Map.of(ExpressionContext.forIdentifier("myField"), SyntheticBlockValSets.Double.create(null, new double[] { 2.0, 3.0 })));
    DoubleOpenHashSet distinctResult = aggregationResultHolder.getResult();
    assertEquals(distinctResult.size(), 3);
    ArrayAggDoubleFunction arrayAggDoubleFunction = new ArrayAggDoubleFunction(ExpressionContext.forIdentifier("myField"), false);
    aggregationResultHolder = arrayAggDoubleFunction.createAggregationResultHolder();
    arrayAggDoubleFunction.aggregate(2, aggregationResultHolder, Map.of(ExpressionContext.forIdentifier("myField"), SyntheticBlockValSets.Double.create(null, new double[] { 1.0, 2.0 })));
    arrayAggDoubleFunction.aggregate(2, aggregationResultHolder, Map.of(ExpressionContext.forIdentifier("myField"), SyntheticBlockValSets.Double.create(null, new double[] { 2.0, 3.0 })));
    DoubleArrayList result = aggregationResultHolder.getResult();
    assertEquals(result.size(), 4);
}

