@Test
public void testEqualsRewrites() {
    // Test int column equals valid decimal value. "intColumn = 5.0" should have been rewritten to "intColumn = 5"
    // since 5.0 converts to integer value without any loss of information.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn = 5.0"), "Expression(type:FUNCTION, functionCall:Function(operator:EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:intColumn)), Expression(type:LITERAL, literal:<Literal longValue:5>)]))");
    // Test a query containing NOT operator
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE NOT intColumn = 5.0"), "Expression(type:FUNCTION, functionCall:Function(operator:NOT, operands:[Expression(type:FUNCTION, " + "functionCall:Function(operator:EQUALS, operands:[Expression(type:IDENTIFIER, identifier:Identifier" + "(name:intColumn)), Expression(type:LITERAL, literal:<Literal longValue:5>)]))]))");
    // Test int column equals invalid decimal value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn = 5.5"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test int column not equals valid decimal value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn != 5.0"), "Expression(type:FUNCTION, functionCall:Function(operator:NOT_EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:intColumn)), Expression(type:LITERAL, literal:<Literal longValue:5>)]))");
    // Test int column not equals invalid decimal value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn != 5.5"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test int column equals out of domain value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn = 5000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test int column not equals out of domain value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn != 5000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test long column equals valid decimal value. "longColumn = 5.0" should be rewritten to "longColumn = 5" since 5.0
    // converts to long value without any loss of information.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE longColumn = 5.0"), "Expression(type:FUNCTION, functionCall:Function(operator:EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:longColumn)), Expression(type:LITERAL, literal:<Literal longValue:5>)]))");
    // Test long column equals invalid decimal value. "longColumn = 5.5" should have been rewritten to "false" literal
    // since an LONG column can never have a decimal value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE longColumn = 5.5"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test long column with valid decimal value. "longColumn = 5.5" should have been rewritten to "false" literal since
    // LONG column can never have a decimal value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE longColumn != 5.0"), "Expression(type:FUNCTION, functionCall:Function(operator:NOT_EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:longColumn)), Expression(type:LITERAL, literal:<Literal longValue:5>)]))");
    // Test long column not equals invalid decimal value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE longColumn != 5.5"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test float column equals valid int value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn = 5"), "Expression(type:FUNCTION, functionCall:Function(operator:EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:floatColumn)), Expression(type:LITERAL, literal:<Literal intValue:5>)" + "]))");
    // Test float column not equals valid int value
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn != 5"), "Expression(type:FUNCTION, functionCall:Function(operator:NOT_EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:floatColumn)), Expression(type:LITERAL, literal:<Literal intValue:5>)" + "]))");
    // Test float column equals invalid long value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn = " + Long.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test float column not equals invalid long value
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn != " + Long.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // test double column equals valid int value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE doubleColumn = 5"), "Expression(type:FUNCTION, functionCall:Function(operator:EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:doubleColumn)), Expression(type:LITERAL, literal:<Literal intValue:5>)" + "]))");
    // Test double column not equals valid int value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE doubleColumn != 5"), "Expression(type:FUNCTION, functionCall:Function(operator:NOT_EQUALS, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:doubleColumn)), Expression(type:LITERAL, literal:<Literal intValue:5>)" + "]))");
    // Test double column equals invalid long value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE doubleColumn = " + Long.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test double column not equals invalid long value
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE doubleColumn != " + Long.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
}

@Test
public void testRangeRewrites() {
    // Test INT column with DOUBLE value greater than Integer.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn > 3000000000.0"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test INT column with DOUBLE value greater than Integer.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn < 3000000000.0"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test INT column with DOUBLE value greater than Integer.MIN_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn > -3000000000.0"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test INT column with LONG value less than Integer.MIN_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn < -3000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test INT column with LONG value greater than Integer.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn > 3000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test INT column with LONG value greater than Integer.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn < 3000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test INT column with LONG value greater than Integer.MIN_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn > -3000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test INT column with LONG value less than Integer.MIN_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn < -3000000000"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test INT column with DOUBLE value that falls within INT bounds.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn < -2100000000.5"), "Expression(type:FUNCTION, functionCall:Function(operator:LESS_THAN, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:intColumn)), Expression(type:LITERAL, literal:<Literal " + "longValue:-2100000000>)]))");
    // Test INT column with DOUBLE value that falls within INT bounds.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn < 2100000000.5"), "Expression(type:FUNCTION, functionCall:Function(operator:LESS_THAN_OR_EQUAL, operands:[Expression" + "(type:IDENTIFIER, identifier:Identifier(name:intColumn)), Expression(type:LITERAL, literal:<Literal " + "longValue:2100000000>)]))");
    // Test FLOAT column greater than Double.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn > " + Double.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test FLOAT column less than Double.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn < " + Double.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
