@Test
public void testAndRewrites() {
    // Test and with all true operands
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn != 5.5 AND longColumn != 6.4"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test and with all false operands
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn = 5.5 AND longColumn = 6.4"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test and with one false operand
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn = 5.5 AND longColumn != 6.4"), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test or with all true operands
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn != 5.5 OR longColumn != 6.4"), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test int column with exclusive valid double value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn > 5.0 AND intColumn < 10.0"), "Expression(type:FUNCTION, functionCall:Function(operator:RANGE, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:intColumn)), Expression(type:LITERAL, literal:<Literal stringValue:" + "(5\u000010)>)]))");
    // Test int column with inclusive valid double value.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE intColumn >= 5.0 AND intColumn <= 10.0"), "Expression(type:FUNCTION, functionCall:Function(operator:RANGE, operands:[Expression(type:IDENTIFIER, " + "identifier:Identifier(name:intColumn)), Expression(type:LITERAL, literal:<Literal " + "stringValue:[5\u000010]>)]))");
}

