@Test
public void testPostAggregationFunction() {
    // Plus
    PostAggregationFunction function = new PostAggregationFunction("plus", new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG });
    assertEquals(function.getResultType(), ColumnDataType.LONG);
    assertEquals(function.invoke(new Object[] { 1, 2L }), 3L);
    // Minus
    function = new PostAggregationFunction("MINUS", new ColumnDataType[] { ColumnDataType.FLOAT, ColumnDataType.DOUBLE });
    assertEquals(function.getResultType(), ColumnDataType.DOUBLE);
    assertEquals(function.invoke(new Object[] { 3f, 4.0 }), -1.0);
    // Times
    function = new PostAggregationFunction("tImEs", new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.INT });
    assertEquals(function.getResultType(), ColumnDataType.DOUBLE);
    assertEquals(function.invoke(new Object[] { "5", 6 }), 30.0);
    // Reverse
    function = new PostAggregationFunction("reverse", new ColumnDataType[] { ColumnDataType.LONG });
    assertEquals(function.getResultType(), ColumnDataType.STRING);
    assertEquals(function.invoke(new Object[] { "1234567890" }), "0987654321");
    // ST_AsText
    function = new PostAggregationFunction("ST_AsText", new ColumnDataType[] { ColumnDataType.BYTES });
    assertEquals(function.getResultType(), ColumnDataType.STRING);
    assertEquals(function.invoke(new Object[] { GeometrySerializer.serialize(GeometryUtils.GEOMETRY_FACTORY.createPoint(new Coordinate(10, 20))) }), "POINT (10 20)");
    // Cast
    function = new PostAggregationFunction("cast", new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING });
    assertEquals(function.getResultType(), ColumnDataType.OBJECT);
    assertEquals(function.invoke(new Object[] { 1, "LONG" }), 1L);
    // NOT
    function = new PostAggregationFunction("not", new ColumnDataType[] { ColumnDataType.BOOLEAN });
    assertEquals(function.getResultType(), ColumnDataType.BOOLEAN);
    assertFalse((Boolean) function.invoke(new Object[] { true }));
    assertTrue((Boolean) function.invoke(new Object[] { false }));
    // isDistinctFrom
    function = new PostAggregationFunction("isDistinctFrom", new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING });
    assertEquals(function.getResultType(), ColumnDataType.BOOLEAN);
    assertFalse((Boolean) function.invoke(new Object[] { null, null }));
    assertFalse((Boolean) function.invoke(new Object[] { "a", "a" }));
    assertTrue((Boolean) function.invoke(new Object[] { null, "a" }));
    assertTrue((Boolean) function.invoke(new Object[] { "a", null }));
    assertTrue((Boolean) function.invoke(new Object[] { "a", "b" }));
    // isNotDistinctFrom
    function = new PostAggregationFunction("isNotDistinctFrom", new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING });
    assertEquals(function.getResultType(), ColumnDataType.BOOLEAN);
    assertTrue((Boolean) function.invoke(new Object[] { null, null }));
    assertTrue((Boolean) function.invoke(new Object[] { "a", "a" }));
    assertFalse((Boolean) function.invoke(new Object[] { null, "a" }));
    assertFalse((Boolean) function.invoke(new Object[] { "a", null }));
    assertFalse((Boolean) function.invoke(new Object[] { "a", "b" }));
    // Coalesce
    function = new PostAggregationFunction("coalesce", new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.BOOLEAN });
    assertEquals(function.getResultType(), ColumnDataType.OBJECT);
    assertNull(function.invoke(new Object[] { null, null, null }));
    assertEquals(function.invoke(new Object[] { null, "1", null }), "1");
    assertEquals(function.invoke(new Object[] { 1, "2", false }), 1);
    assertEquals(function.invoke(new Object[] { null, null, true }), true);
    // Case with a large number of when then clauses
    function = new PostAggregationFunction("case", new ColumnDataType[] { ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.BOOLEAN, ColumnDataType.INT, ColumnDataType.INT });
    assertEquals(function.getResultType(), ColumnDataType.OBJECT);
    assertEquals(function.invoke(new Object[] { false, 1, false, 2, false, 3, false, 4, false, 5, false, 6, false, 7, false, 8, false, 9, false, 10, false, 11, false, 12, false, 13, false, 14, false, 15, false, 16, false, 17, false, 18, false, 19, 20 }), 20);
    // Coalesce with a large number of arguments
    function = new PostAggregationFunction("coalesce", new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT, ColumnDataType.INT });
    assertEquals(function.getResultType(), ColumnDataType.OBJECT);
    assertNull(function.invoke(new Object[] { null, null, null, null, null, null, null, null, null, null }));
    assertEquals(function.invoke(new Object[] { null, null, null, null, null, null, null, null, null, 10 }), 10);
}

