@Test
public void testReduceTimeout() throws IOException {
    BrokerReduceService brokerReduceService = new BrokerReduceService(new PinotConfiguration(Map.of(Broker.CONFIG_OF_MAX_REDUCE_THREADS_PER_QUERY, 2)));
    BrokerRequest brokerRequest = CalciteSqlCompiler.compileToBrokerRequest("SELECT COUNT(*) FROM testTable GROUP BY col1");
    DataSchema dataSchema = new DataSchema(new String[] { "col1", "count(*)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG });
    DataTableBuilder dataTableBuilder = DataTableBuilderFactory.getDataTableBuilder(dataSchema);
    int numGroups = 5000;
    for (int i = 0; i < numGroups; i++) {
        dataTableBuilder.startRow();
        dataTableBuilder.setColumn(0, i);
        dataTableBuilder.setColumn(1, 1L);
        dataTableBuilder.finishRow();
    }
    DataTable dataTable = dataTableBuilder.build();
    Map<ServerRoutingInstance, DataTable> dataTableMap = new HashMap<>();
    int numInstances = 1000;
    for (int i = 0; i < numInstances; i++) {
        ServerRoutingInstance instance = new ServerRoutingInstance("localhost", i, TableType.OFFLINE);
        dataTableMap.put(instance, dataTable);
    }
    long reduceTimeoutMs = 1;
    BrokerResponseNative brokerResponse = brokerReduceService.reduceOnDataTable(brokerRequest, brokerRequest, dataTableMap, reduceTimeoutMs, mock(BrokerMetrics.class));
    brokerReduceService.shutDown();
    List<QueryProcessingException> exceptions = brokerResponse.getExceptions();
    assertEquals(exceptions.size(), 1);
    assertEquals(exceptions.get(0).getErrorCode(), QueryErrorCode.BROKER_TIMEOUT.getId());
}

