@Test
public void testHavingFilter() {
    // Simple having
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT COUNT(*) FROM testTable GROUP BY d1 HAVING COUNT(*) > 5");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "count(*)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler, false);
        assertFalse(havingFilterHandler.isMatch(new Object[] { 1, 5L }));
        assertTrue(havingFilterHandler.isMatch(new Object[] { 2, 10L }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 3, 3L }));
    }
    // Nested having
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT MAX(m1), MIN(m1) FROM testTable GROUP BY d1 HAVING MAX(m1) IN (15, 20, 25) AND (MIN(m1) > 10 OR MIN" + "(m1) <= 3)");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "max(m1)", "min(m1)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler, false);
        assertFalse(havingFilterHandler.isMatch(new Object[] { 1, 15.5, 13.0 }));
        assertTrue(havingFilterHandler.isMatch(new Object[] { 2, 15.0, 3.0 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 3, 20.0, 7.5 }));
    }
    // Having with post-aggregation
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT MAX(m1), MIN(m2) FROM testTable GROUP BY d1 HAVING MAX(m1) > MIN(m2) * 2");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "max(m1)", "min(m2)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler, false);
        assertFalse(havingFilterHandler.isMatch(new Object[] { 1, 15.5, 13.0 }));
        assertTrue(havingFilterHandler.isMatch(new Object[] { 2, 15.0, 3.0 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 3, 20.0, 10.0 }));
    }
    // Having with all data types
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT COUNT(*) FROM testTable GROUP BY d1, d2, d3, d4, d5, d6 HAVING d1 > 10 AND d2 > 10 AND d3 > 10 AND " + "d4 > 10 AND d5 > 10 AND d6 > 10");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "d3", "d4", "d5", "d6", "count(*)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.FLOAT, ColumnDataType.DOUBLE, ColumnDataType.STRING, ColumnDataType.BYTES, ColumnDataType.LONG });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler, false);
        assertTrue(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.5, "11", new byte[] { 17 }, 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 10, 11L, 10.5f, 10.5, "11", new byte[] { 17 }, 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 10L, 10.5f, 10.5, "11", new byte[] { 17 }, 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.0f, 10.5, "11", new byte[] { 17 }, 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.0, "11", new byte[] { 17 }, 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.5, "10", new byte[] { 17 }, 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.5, "11", new byte[] { 16 }, 5 }));
    }
}

