    dataSchema = new DataSchema(new String[] { "col3", "col4", "sum(col1+1)", "min(col2+2)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    canonicalDataSchema = ReducerDataSchemaUtils.canonicalizeDataSchemaForGroupBy(queryContext, dataSchema);
    assertEquals(canonicalDataSchema, new DataSchema(new String[] { "col3", "col4", "sum(plus(col1,'1'))", "min(plus(col2,'2'))" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE }));
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT col3 + col4, MAX(col1 + 1) FILTER(WHERE col3 > 0) - MIN(col2 + 2) FILTER(WHERE col4 > 0) FROM " + "testTable GROUP BY col3 + col4");
