    dataSchema = new DataSchema(new String[] { "add(col3+col4)", "max(col1+1)", "min(col2+2)" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    canonicalDataSchema = ReducerDataSchemaUtils.canonicalizeDataSchemaForGroupBy(queryContext, dataSchema);
    assertEquals(canonicalDataSchema, new DataSchema(new String[] { "plus(col3,col4)", "max(plus(col1,'1')) FILTER(WHERE col3 > '0')", "min(plus(col2,'2')) FILTER" + "(WHERE col4 > '0')" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE }));
}

