@Test
public void testThreadExceptionTransfer() {
    // simulate a thread exception in gRPC call and verify that the thread can transfer the exception
    Iterator<Server.ServerResponse> mockedResponse = (Iterator<Server.ServerResponse>) mock(Iterator.class);
    when(mockedResponse.hasNext()).thenReturn(true);
    String exceptionMessage = "Some exception";
    RuntimeException innerException = new RuntimeException(exceptionMessage);
    when(mockedResponse.next()).thenThrow(innerException);
    ExecutorService threadPoolService = Executors.newFixedThreadPool(1);
    ServerRoutingInstance routingInstance = new ServerRoutingInstance("localhost", 9527, TableType.OFFLINE);
    // supposedly we can use TestNG's annotation like @Test(expectedExceptions = { IOException.class }) to verify
    // here we hope to verify deeper to make sure the thrown exception is nested inside the exception
    assertTrue(verifyException(() -> {
        StreamingReduceService.processIterativeServerResponse(mock(StreamingReducer.class), threadPoolService, ImmutableMap.of(routingInstance, mockedResponse), 1000, mock(ExecutionStatsAggregator.class));
        return null;
    }, cause -> cause.getMessage().contains(exceptionMessage)));
}

@Test
public void testExecutionTimeout() throws Exception {
    // simulate a thread timeout in gRPC call and verify that the thread can transfer the exception
    Iterator<Server.ServerResponse> mockedResponse = (Iterator<Server.ServerResponse>) mock(Iterator.class);
    when(mockedResponse.hasNext()).thenReturn(true);
    when(mockedResponse.next()).then(new Answer<Void>() {

        @Override
        public Void answer(InvocationOnMock invocationOnMock) throws Throwable {
            Thread.sleep(1000);
            return null;
        }
    });
    final ExecutorService threadPoolService = Executors.newFixedThreadPool(1);
    final ServerRoutingInstance routingInstance = new ServerRoutingInstance("localhost", 9527, TableType.OFFLINE);
    //We cannot use TestNG's annotation like @Test(expectedExceptions = { IOException.class }) to verify
    // because the Exception we hope to verify is nested inside the final exception.
    assertTrue(verifyException(() -> {
        StreamingReduceService.processIterativeServerResponse(mock(StreamingReducer.class), threadPoolService, ImmutableMap.of(routingInstance, mockedResponse), 10, mock(ExecutionStatsAggregator.class));
        return null;
    }, (cause) -> cause instanceof TimeoutException));
}

@Test
public void testSerDe() {
    // EqPredicate
    assertEquals(testSerDe("foo\t= 123"), "foo = '123'");
    assertEquals(testSerDe("foo='123'"), "foo = '123'");
    // NotEqPredicate
    assertEquals(testSerDe("foo !=123"), "foo != '123'");
    assertEquals(testSerDe("foo <>\t123"), "foo != '123'");
    assertEquals(testSerDe("foo\t\t!= '123'"), "foo != '123'");
    assertEquals(testSerDe("foo<> '123'"), "foo != '123'");
    // InPredicate
    assertEquals(testSerDe("foo in (123, \t456,789)"), "foo IN ('123','456','789')");
    assertEquals(testSerDe("foo In (\t '123', '456',  '789')"), "foo IN ('123','456','789')");
    // NotInPredicate
    assertEquals(testSerDe("foo NOT in (123, \t456,789)"), "foo NOT IN ('123','456','789')");
    assertEquals(testSerDe("foo NoT In (\t '123', '456',  '789')"), "foo NOT IN ('123','456','789')");
    // RangePredicate
    assertEquals(testSerDe("foo >123"), "foo > '123'");
    assertEquals(testSerDe("foo >=\t'123'"), "foo >= '123'");
    assertEquals(testSerDe("foo< 123"), "foo < '123'");
    assertEquals(testSerDe("foo\t<= '123'"), "foo <= '123'");
    assertEquals(testSerDe("foo bEtWeEn 123 AnD 456"), "foo BETWEEN '123' AND '456'");
    // RegexpLikePredicate
    assertEquals(testSerDe("ReGexP_lIKe(foo,\t\t'bar')"), "regexp_like(foo,'bar')");
    // TextMatchPredicate
    assertEquals(testSerDe("TEXT_MATCH(foo\t ,\t'bar')"), "text_match(foo,'bar')");
    // IsNullPredicate
    assertEquals(testSerDe("foo\tis\tnull"), "foo IS NULL");
    // IsNotNullPredicate
    assertEquals(testSerDe("foo\tIS not\tNulL"), "foo IS NOT NULL");
    // Non-standard RangePredicate (merged ranges)
    RangePredicate rangePredicate = new RangePredicate(ExpressionContext.forIdentifier("foo"), true, "123", false, "456", FieldSpec.DataType.STRING);
    String predicateExpression = rangePredicate.toString();
    assertEquals(predicateExpression, "(foo >= '123' AND foo < '456')");
    Expression thriftExpression = CalciteSqlParser.compileToExpression(predicateExpression);
    FilterContext filter = RequestContextUtils.getFilter(thriftExpression);
    assertEquals(filter.getType(), FilterContext.Type.AND);
    List<FilterContext> children = filter.getChildren();
    assertEquals(children.size(), 2);
    assertEquals(children.get(0).toString(), "foo >= '123'");
    assertEquals(children.get(1).toString(), "foo < '456'");
}

