        assertEquals(queryContext.getLimit(), 10);
        assertEquals(queryContext.getOffset(), 0);
        assertEquals(queryContext.getColumns(), new HashSet<>(Arrays.asList("foo", "bar")));
        assertFalse(QueryContextUtils.isSelectionQuery(queryContext));
        assertTrue(QueryContextUtils.isAggregationQuery(queryContext));
        assertFalse(QueryContextUtils.isDistinctQuery(queryContext));
    }
    // Post-aggregation
    {
        String query = "SELECT SUM(col1) * MAX(col2) FROM testTable GROUP BY col3 HAVING SUM(col1) > MIN(col2) AND " + "SUM(col4) + col3 < MAX(col4) ORDER BY MAX(col1) + MAX(col2) - SUM(col4), col3 DESC";
        QueryContext queryContext = QueryContextConverterUtils.getQueryContext(query);
        assertEquals(queryContext.getTableName(), "testTable");
        // SELECT clause
        List<ExpressionContext> selectExpressions = queryContext.getSelectExpressions();
        assertEquals(selectExpressions.size(), 1);
        FunctionContext function = selectExpressions.get(0).getFunction();
        assertEquals(function.getType(), FunctionContext.Type.TRANSFORM);
        assertEquals(function.getFunctionName(), "times");
        List<ExpressionContext> arguments = function.getArguments();
        assertEquals(arguments.size(), 2);
        assertEquals(arguments.get(0), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "sum", Collections.singletonList(ExpressionContext.forIdentifier("col1")))));
        assertEquals(arguments.get(1), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "max", Collections.singletonList(ExpressionContext.forIdentifier("col2")))));
        // HAVING clause
        FilterContext havingFilter = queryContext.getHavingFilter();
        assertNotNull(havingFilter);
        assertEquals(havingFilter.getType(), FilterContext.Type.AND);
        List<FilterContext> children = havingFilter.getChildren();
        assertEquals(children.size(), 2);
        FilterContext firstChild = children.get(0);
        assertEquals(firstChild.getType(), FilterContext.Type.PREDICATE);
        Predicate predicate = firstChild.getPredicate();
        assertEquals(predicate.getType(), Predicate.Type.RANGE);
        RangePredicate rangePredicate = (RangePredicate) predicate;
        assertEquals(rangePredicate.getLowerBound(), "0");
        assertFalse(rangePredicate.isLowerInclusive());
        assertEquals(rangePredicate.getUpperBound(), RangePredicate.UNBOUNDED);
        assertFalse(rangePredicate.isUpperInclusive());
        function = rangePredicate.getLhs().getFunction();
        assertEquals(function.getFunctionName(), "minus");
        arguments = function.getArguments();
        assertEquals(arguments.size(), 2);
        assertEquals(arguments.get(0), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "sum", Collections.singletonList(ExpressionContext.forIdentifier("col1")))));
        assertEquals(arguments.get(1), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "min", Collections.singletonList(ExpressionContext.forIdentifier("col2")))));
        // Skip checking the second child of the AND filter
        // ORDER-BY clause
        List<OrderByExpressionContext> orderByExpressions = queryContext.getOrderByExpressions();
        assertNotNull(orderByExpressions);
        assertEquals(orderByExpressions.size(), 2);
        OrderByExpressionContext firstOrderByExpression = orderByExpressions.get(0);
        assertTrue(firstOrderByExpression.isAsc());
        function = firstOrderByExpression.getExpression().getFunction();
        assertEquals(function.getFunctionName(), "minus");
        arguments = function.getArguments();
        assertEquals(arguments.size(), 2);
        assertEquals(arguments.get(0).getFunction().getFunctionName(), "plus");
        assertEquals(arguments.get(1), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "sum", Collections.singletonList(ExpressionContext.forIdentifier("col4")))));
        assertEquals(queryContext.getColumns(), new HashSet<>(Arrays.asList("col1", "col2", "col3", "col4")));
        assertFalse(QueryContextUtils.isSelectionQuery(queryContext));
        assertTrue(QueryContextUtils.isAggregationQuery(queryContext));
        assertFalse(QueryContextUtils.isDistinctQuery(queryContext));
        // Expected: SUM(col1), MAX(col2), MIN(col2), SUM(col4), MAX(col4), MAX(col1)
        //noinspection rawtypes
        AggregationFunction[] aggregationFunctions = queryContext.getAggregationFunctions();
        assertNotNull(aggregationFunctions);
        assertEquals(aggregationFunctions.length, 6);
        assertEquals(aggregationFunctions[0].getResultColumnName(), "sum(col1)");
        assertEquals(aggregationFunctions[1].getResultColumnName(), "max(col2)");
        assertEquals(aggregationFunctions[2].getResultColumnName(), "min(col2)");
        assertEquals(aggregationFunctions[3].getResultColumnName(), "sum(col4)");
        assertEquals(aggregationFunctions[4].getResultColumnName(), "max(col4)");
        assertEquals(aggregationFunctions[5].getResultColumnName(), "max(col1)");
        Map<Pair<FunctionContext, FilterContext>, Integer> indexMap = queryContext.getFilteredAggregationsIndexMap();
        assertNotNull(indexMap);
        assertEquals(indexMap.size(), 6);
        assertEquals((int) indexMap.get(Pair.of(new FunctionContext(FunctionContext.Type.AGGREGATION, "sum", Collections.singletonList(ExpressionContext.forIdentifier("col1"))), null)), 0);
        assertEquals((int) indexMap.get(Pair.of(new FunctionContext(FunctionContext.Type.AGGREGATION, "max", Collections.singletonList(ExpressionContext.forIdentifier("col2"))), null)), 1);
        assertEquals((int) indexMap.get(Pair.of(new FunctionContext(FunctionContext.Type.AGGREGATION, "min", Collections.singletonList(ExpressionContext.forIdentifier("col2"))), null)), 2);
        assertEquals((int) indexMap.get(Pair.of(new FunctionContext(FunctionContext.Type.AGGREGATION, "sum", Collections.singletonList(ExpressionContext.forIdentifier("col4"))), null)), 3);
        assertEquals((int) indexMap.get(Pair.of(new FunctionContext(FunctionContext.Type.AGGREGATION, "max", Collections.singletonList(ExpressionContext.forIdentifier("col4"))), null)), 4);
        assertEquals((int) indexMap.get(Pair.of(new FunctionContext(FunctionContext.Type.AGGREGATION, "max", Collections.singletonList(ExpressionContext.forIdentifier("col1"))), null)), 5);
    }
    // DistinctCountThetaSketch (string literal and escape quote)
    {
        String query = "SELECT DISTINCTCOUNTTHETASKETCH(foo, 'nominalEntries=1000', 'bar=''a''', 'bar=''b''', " + "'SET_INTERSECT($1, $2)') FROM testTable WHERE bar IN ('a', 'b')";
        QueryContext queryContext = QueryContextConverterUtils.getQueryContext(query);
        FunctionContext function = queryContext.getSelectExpressions().get(0).getFunction();
        assertEquals(function.getType(), FunctionContext.Type.AGGREGATION);
        assertEquals(function.getFunctionName(), "distinctcountthetasketch");
        List<ExpressionContext> arguments = function.getArguments();
        assertEquals(arguments.get(0), ExpressionContext.forIdentifier("foo"));
        assertEquals(arguments.get(1), ExpressionContext.forLiteral(FieldSpec.DataType.STRING, "nominalEntries=1000"));
        assertEquals(arguments.get(2), ExpressionContext.forLiteral(FieldSpec.DataType.STRING, "bar='a'"));
        assertEquals(arguments.get(3), ExpressionContext.forLiteral(FieldSpec.DataType.STRING, "bar='b'"));
        assertEquals(arguments.get(4), ExpressionContext.forLiteral(FieldSpec.DataType.STRING, "SET_INTERSECT($1, $2)"));
        assertEquals(queryContext.getColumns(), new HashSet<>(Arrays.asList("foo", "bar")));
        assertFalse(QueryContextUtils.isSelectionQuery(queryContext));
        assertTrue(QueryContextUtils.isAggregationQuery(queryContext));
