    selectionColumns = SelectionOperatorUtils.getSelectionColumns(QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable ORDER BY add(foo, 1), sub(bar, 2), foo"), dataSchema);
    assertEquals(selectionColumns, Arrays.asList("bar", "foo", "foobar"));
    // Test data schema from DataTableBuilder.buildEmptyDataTable()
    when(dataSchema.getColumnNames()).thenReturn(new String[] { "*" });
    selectionColumns = SelectionOperatorUtils.getSelectionColumns(QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable"), dataSchema);
    assertEquals(selectionColumns, new ArrayList<>(Collections.singletonList("*")));
}

