@Test
public void testGetResultTableColumnIndices() {
    // Select * without order-by
    QueryContext queryContext = QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable");
    DataSchema dataSchema = new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE });
    Pair<DataSchema, int[]> pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 0, 1, 2 });
    // Select * without order-by, all the segments are pruned on the server side
    dataSchema = new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING }));
    // Select * with order-by but LIMIT 0
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable ORDER BY col1 LIMIT 0");
    dataSchema = new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 0, 1, 2 });
    // Select * with order-by but LIMIT 0, all the segments are pruned on the server side
    dataSchema = new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING }));
    // Select columns without order-by
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT col1 + 1, col2 + 2 FROM testTable");
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+1)", "add(col2+2)" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "plus(col2,'2')" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 0, 1 });
    // Select columns without order-by, all the segments are pruned on the server side
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+1)", "add(col2+2)" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "plus(col2,'2')" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING }));
    // Select duplicate columns without order-by
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT col1 + 1, col2 + 2, col1 + 1 FROM testTable");
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+1)", "add(col2+2)" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "plus(col2,'2')", "plus(col1,'1')" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 0, 1, 0 });
    // Select duplicate columns without order-by, all the segments are pruned on the server side
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+1)", "add(col2+2)", "add(col1+1)" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "plus(col2,'2')", "plus(col1,'1')" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.STRING }));
    // Select * with order-by
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable ORDER BY col3");
    dataSchema = new DataSchema(new String[] { "col3", "col1", "col2" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.INT, ColumnDataType.LONG });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 1, 2, 0 });
    // Select * with order-by, all the segments are pruned on the server side
    dataSchema = new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING }));
    // Select * ordering on function
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable ORDER BY col1 + col2");
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+col2)", "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 1, 2, 3 });
    // Select * ordering on function, all the segments are pruned on the server side
    dataSchema = new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING }));
    // Select * ordering on both column and function
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT * FROM testTable ORDER BY col1 + col2, col2");
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+col2)", "col2", "col1", "col3" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.LONG, ColumnDataType.INT, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "col1", "col2", "col3" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 2, 1, 3 });
    // Select * ordering on both column and function, all the segments are pruned on the server side
    dataSchema = new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "*" }, new ColumnDataType[] { ColumnDataType.STRING }));
    // Select columns with order-by
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT col1 + 1, col3, col2 + 2 FROM testTable ORDER BY col2 + 2, col4");
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col2+2)", "col4", "add(col1+1)", "col3" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.STRING, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "col3", "plus(col2,'2')" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 2, 3, 0 });
    // Select columns with order-by, all the segments are pruned on the server side
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+1)", "col3", "add(col2+2)" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "col3", "plus(col2,'2')" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.STRING }));
    // Select duplicate columns with order-by
    queryContext = QueryContextConverterUtils.getQueryContext("SELECT col1 + 1, col2 + 2, col1 + 1 FROM testTable ORDER BY col2 + 2, col4");
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col2+2)", "col4", "add(col1+1)" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.STRING, ColumnDataType.DOUBLE });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "plus(col2,'2')", "plus(col1,'1')" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE }));
    assertEquals(pair.getRight(), new int[] { 2, 0, 2 });
    // Select duplicate columns with order-by, all the segments are pruned on the server side
    // Intentionally make data schema not matching the string representation of the expression
    dataSchema = new DataSchema(new String[] { "add(col1+1)", "add(col2+2)", "add(col1+1)" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.STRING });
    pair = SelectionOperatorUtils.getResultTableDataSchemaAndColumnIndices(queryContext, dataSchema);
    assertEquals(pair.getLeft(), new DataSchema(new String[] { "plus(col1,'1')", "plus(col2,'2')", "plus(col1,'1')" }, new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.STRING }));
}

