@Test
public void testOffsetCriteria() {
    // Build smallest offset criteria
    OffsetCriteria offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetSmallest();
    Assert.assertTrue(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    Assert.assertEquals(offsetCriteria.getOffsetString(), "smallest");
    // Build largest offset criteria
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetLargest();
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertTrue(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    Assert.assertEquals(offsetCriteria.getOffsetString(), "largest");
    // Build period offset criteria
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetAsPeriod("5d");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertTrue(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    Assert.assertEquals(offsetCriteria.getOffsetString(), "5d");
    // Build timestamp offset criteria
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetAsTimestamp("2022-08-09T12:31:38.222Z");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertTrue(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    Assert.assertEquals(offsetCriteria.getOffsetString(), "2022-08-09T12:31:38.222Z");
    // Build custom offset criteria
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetCustom("custom criteria");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertTrue(offsetCriteria.isCustom());
    Assert.assertEquals(offsetCriteria.getOffsetString(), "custom criteria");
    // Build smallest offset criteria with offset string
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetString("smallest");
    Assert.assertTrue(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    // Build largest offset criteria with offset string
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetString("LARGEST");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertTrue(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    // Build period offset criteria with offset string
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetString("6h");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertTrue(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    // Build timestamp offset criteria with offset string
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetString("2022-08-09T12:31:38.222Z");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertTrue(offsetCriteria.isTimestamp());
    Assert.assertFalse(offsetCriteria.isCustom());
    // Build incorrect period offset criteria with offset string
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetString("-6h");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertTrue(offsetCriteria.isCustom());
    // Build custom offset criteria with offset string
    offsetCriteria = new OffsetCriteria.OffsetCriteriaBuilder().withOffsetString("myCriteria");
    Assert.assertFalse(offsetCriteria.isSmallest());
    Assert.assertFalse(offsetCriteria.isLargest());
    Assert.assertFalse(offsetCriteria.isPeriod());
    Assert.assertFalse(offsetCriteria.isTimestamp());
    Assert.assertTrue(offsetCriteria.isCustom());
}

/**
 * Checks that we fail if any of the mandatory properties are missing
 */
@Test
public void testStreamConfig() {
    String streamType = "fakeStream";
    String topic = "fakeTopic";
    String tableName = "fakeTable_REALTIME";
    String consumerFactoryClass = FakeStreamConsumerFactory.class.getName();
    String decoderClass = FakeStreamMessageDecoder.class.getName();
    // test with empty map
    try {
        Map<String, String> streamConfigMap = new HashMap<>();
        new StreamConfig(tableName, streamConfigMap);
        fail();
    } catch (NullPointerException e) {
        // Expected
    }
    // All mandatory properties set
    Map<String, String> streamConfigMap = new HashMap<>();
    streamConfigMap.put(StreamConfigProperties.STREAM_TYPE, streamType);
    streamConfigMap.put(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_TOPIC_NAME), topic);
    streamConfigMap.put(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_CONSUMER_FACTORY_CLASS), consumerFactoryClass);
    streamConfigMap.put(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_DECODER_CLASS), decoderClass);
    StreamConfig streamConfig = new StreamConfig(tableName, streamConfigMap);
    assertEquals(streamConfig.getType(), streamType);
    assertEquals(streamConfig.getTopicName(), topic);
    assertEquals(streamConfig.getConsumerFactoryClassName(), consumerFactoryClass);
    assertEquals(streamConfig.getDecoderClass(), decoderClass);
    // Missing streamType
    streamConfigMap.remove(StreamConfigProperties.STREAM_TYPE);
    try {
        new StreamConfig(tableName, streamConfigMap);
        fail();
    } catch (NullPointerException e) {
        // Expected
    }
    // Missing stream topic
    streamConfigMap.put(StreamConfigProperties.STREAM_TYPE, streamType);
    streamConfigMap.remove(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_TOPIC_NAME));
    try {
        new StreamConfig(tableName, streamConfigMap);
        fail();
    } catch (NullPointerException e) {
        // Expected
    }
    // Missing consumer factory - allowed
    streamConfigMap.put(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_TOPIC_NAME), topic);
    streamConfigMap.remove(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_CONSUMER_FACTORY_CLASS));
    streamConfig = new StreamConfig(tableName, streamConfigMap);
    assertEquals(streamConfig.getConsumerFactoryClassName(), StreamConfig.DEFAULT_CONSUMER_FACTORY_CLASS_NAME_STRING);
    // Missing decoder class
    streamConfigMap.put(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_CONSUMER_FACTORY_CLASS), consumerFactoryClass);
    streamConfigMap.remove(StreamConfigProperties.constructStreamProperty(streamType, StreamConfigProperties.STREAM_DECODER_CLASS));
    try {
        new StreamConfig(tableName, streamConfigMap);
        fail();
    } catch (NullPointerException e) {
        // Expected
    }
}

