    for (int i = 0; i < numRecords; i++) {
        row.clear();
        int d = RANDOM.nextInt(10);
        row.putValue("d", d);
        if (RANDOM.nextBoolean()) {
            row.putDefaultNullValue("m", 1);
            // Put 0 as the expected value because null value should be skipped
