@Test
public void testCancelQuery() {
    PinotConfiguration config = new PinotConfiguration();
    config.setProperty("pinot.server.enable.query.cancellation", "true");
    QueryScheduler qs = createQueryScheduler(config);
    InstanceRequestHandler handler = new InstanceRequestHandler("server01", config, qs, mock(ServerMetrics.class), mock(AccessControl.class));
    Set<String> queryIds = new HashSet<>();
    queryIds.add("foo");
