    assertEquals(CrcUtils.forAllFilesInFolder(indexDir).computeCrc(), 2102337593L);
    new SegmentV1V2ToV3FormatConverter().convert(indexDir);
    assertEquals(CrcUtils.forAllFilesInFolder(indexDir).computeCrc(), 3362640853L);
}

