@Test
public void testCrcWithLuceneTextIndex() throws Exception {
    URL resource = getClass().getClassLoader().getResource(AVRO_DATA);
    assertNotNull(resource);
    File avroFile = new File(TestUtils.getFileFromResourceUrl(resource));
    List<FieldConfig> fieldConfigs = List.of(new FieldConfig("column5", FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.TEXT), null, null));
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTimeColumnName("daysSinceEpoch").setInvertedIndexColumns(List.of("column1", "column5", "column6")).setCreateInvertedIndexDuringSegmentGeneration(true).setFieldConfigList(fieldConfigs).setIngestionConfig(SegmentTestUtils.getSkipTimeCheckIngestionConfig()).build();
    SegmentGeneratorConfig config = new SegmentGeneratorConfig(tableConfig, SCHEMA);
    config.setInputFilePath(avroFile.getAbsolutePath());
    config.setSegmentVersion(SegmentVersion.v1);
    config.setOutDir(INDEX_DIR.getAbsolutePath());
    SegmentIndexCreationDriver driver = new SegmentIndexCreationDriverImpl();
    driver.init(config);
    driver.build();
    // Lucene text index data is not deterministic, thus leading to different segment crc across each test runs.
    // When using text index in RealTime table, different crc values can cause servers to have to download segments
    // from deep store to make segment replicas in sync.
    File indexDir = driver.getOutputDirectory();
    System.out.println(CrcUtils.forAllFilesInFolder(indexDir).computeCrc());
    new SegmentV1V2ToV3FormatConverter().convert(indexDir);
    System.out.println(CrcUtils.forAllFilesInFolder(indexDir).computeCrc());
}

