    // SEGMENT_1 has only 2 online replicas.
    List<URI> httpServerURIs = PeerServerSegmentFinder.getPeerServerURIs(_helixManager, REALTIME_TABLE_NAME, SEGMENT_1, CommonConstants.HTTP_PROTOCOL);
