@Test
public void testComplexFieldSpec() throws Exception {
    Schema pinotSchema;
    // valid schema
    pinotSchema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("name", DataType.STRING).addComplex("intMap", DataType.MAP, Map.of("key", new DimensionFieldSpec("key", DataType.STRING, true), "value", new DimensionFieldSpec("value", DataType.INT, true))).addComplex("stringMap", DataType.MAP, Map.of("key", new DimensionFieldSpec("key", DataType.STRING, true), "value", new DimensionFieldSpec("value", DataType.STRING, true))).build();
    SchemaUtils.validate(pinotSchema);
    String schemaStr = pinotSchema.toString();
    Schema deserSchema = Schema.fromString(schemaStr);
    Assert.assertEquals(pinotSchema.getSchemaName(), deserSchema.getSchemaName());
    Assert.assertEquals(pinotSchema.getDimensionNames(), deserSchema.getDimensionNames());
    Assert.assertEquals(pinotSchema.getMetricNames(), deserSchema.getMetricNames());
    Assert.assertEquals(pinotSchema.getTimeFieldSpec(), deserSchema.getTimeFieldSpec());
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().size(), deserSchema.getComplexFieldSpecs().size());
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().get(0).getChildFieldSpecs().size(), deserSchema.getComplexFieldSpecs().get(0).getChildFieldSpecs().size());
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().get(0).getChildFieldSpec(ComplexFieldSpec.KEY_FIELD), deserSchema.getComplexFieldSpecs().get(0).getChildFieldSpec(ComplexFieldSpec.KEY_FIELD));
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().get(0).getChildFieldSpec(ComplexFieldSpec.VALUE_FIELD), deserSchema.getComplexFieldSpecs().get(0).getChildFieldSpec(ComplexFieldSpec.VALUE_FIELD));
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().get(1).getChildFieldSpecs().size(), deserSchema.getComplexFieldSpecs().get(1).getChildFieldSpecs().size());
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().get(1).getChildFieldSpec(ComplexFieldSpec.KEY_FIELD), deserSchema.getComplexFieldSpecs().get(1).getChildFieldSpec(ComplexFieldSpec.KEY_FIELD));
    Assert.assertEquals(pinotSchema.getComplexFieldSpecs().get(1).getChildFieldSpec(ComplexFieldSpec.VALUE_FIELD), deserSchema.getComplexFieldSpecs().get(1).getChildFieldSpec(ComplexFieldSpec.VALUE_FIELD));
}

