    assertEquals(((HyperLogLog) aggregationGroupByResult.getResultForGroupId(1, firstGroupKey._groupId)).cardinality(), 691L);
    // Test inter segments base query
    QueriesTestUtils.testInterSegmentsResult(getBrokerResponse(BASE_QUERY), 120000L, 0L, 240000L, 120000L, new Object[] { 21L, 1762L });
    // Test inter segments query with filter
    QueriesTestUtils.testInterSegmentsResult(getBrokerResponseWithFilter(BASE_QUERY), 24516L, 336536L, 49032L, 120000L, new Object[] { 17L, 1197L });
    // Test inter segments query with group-by
    List<Object[]> expectedRows = Arrays.asList(new Object[] { 21L, 691L }, new Object[] { 21L, 1762L }, new Object[] { 11L, 27L }, new Object[] { 21L, 1397L }, new Object[] { 21L, 1532L });
