@Test
public void testInvalidInput() {
    String query;
    try {
        query = "SELECT HISTOGRAM(intColumn,1000,1000,10) FROM testTable";
        Operator operator = getOperator(query);
        assertTrue(operator instanceof AggregationOperator);
        operator.nextBlock();
    } catch (Exception e) {
        assertEquals(e.getMessage(), "Invalid aggregation function: histogram(intColumn,'1000','1000','10'); Reason: The right most edge must" + " be greater than left most edge, given 1000.0 and 1000.0");
    }
    try {
        query = "SELECT HISTOGRAM(intColumn,0,1000,-1) FROM testTable";
        Operator operator = getOperator(query);
        assertTrue(operator instanceof AggregationOperator);
        operator.nextBlock();
    } catch (Exception e) {
        assertEquals(e.getMessage(), "Invalid aggregation function: histogram(intColumn,'0','1000','-1'); Reason: The number of bins must be " + "greater than zero, given -1");
    }
    try {
        query = "SELECT HISTOGRAM(intColumn,ARRAY[0]) FROM testTable";
        Operator operator = getOperator(query);
        assertTrue(operator instanceof AggregationOperator);
        operator.nextBlock();
    } catch (Exception e) {
        assertEquals(e.getMessage(), "Invalid aggregation function: histogram(intColumn,'[0]'); Reason: The number of " + "bin edges must be greater than 1");
    }
    try {
        query = "SELECT HISTOGRAM(intColumn,FUNCTION[0, 10, 20]) FROM testTable";
        Operator operator = getOperator(query);
        assertTrue(operator instanceof AggregationOperator);
        operator.nextBlock();
    } catch (Exception e) {
        assertEquals(e.getMessage(), "Caught exception while parsing query: SELECT HISTOGRAM(intColumn,FUNCTION[0, 10, 20]) FROM testTable");
    }
    try {
        query = "SELECT HISTOGRAM(intColumn,ARRAY[0, 0, 1, 2]) FROM testTable";
        Operator operator = getOperator(query);
        assertTrue(operator instanceof AggregationOperator);
        operator.nextBlock();
    } catch (Exception e) {
        assertEquals(e.getMessage(), "Invalid aggregation function: histogram(intColumn,'[0, 0, 1, 2]'); Reason: The " + "bin edges must be strictly increasing");
    }
    try {
        query = "SELECT HISTOGRAM(intColumn) FROM testTable";
        Operator operator = getOperator(query);
        assertTrue(operator instanceof AggregationOperator);
        operator.nextBlock();
    } catch (Exception e) {
        assertEquals(e.getMessage(), "Invalid aggregation function: histogram(intColumn); Reason: Histogram expects 2 or 4 arguments, got: 1;" + " usage example: `Histogram(columnName, ARRAY[0,1,10,100])` to specify bins [0,1), [1,10), [10,1000] " + "or `Histogram(columnName, 0, 1000, 10)` to specify 10 equal-length bins [0,100), [100,200), ..., " + "[900,1000]");
    }
}

