@Test
public void testIsSubnetOf() {
    // called in select
    String query = String.format("select isSubnetOf(%s, %s) as IPv4Result, isSubnetOf(%s, %s) as IPv6Result, %s, %s from %s limit 100", IPv4_PREFIX_COLUMN_STRING, IPv4_ADDRESS_COLUMN, IPv6_PREFIX_COLUMN_STRING, IPv6_ADDRESS_COLUMN, IPv4_CONTAINS_COLUMN, IPv6_CONTAINS_COLUMN, RAW_TABLE_NAME);
    BrokerResponseNative brokerResponse = getBrokerResponse(query);
    ResultTable resultTable = brokerResponse.getResultTable();
    DataSchema dataSchema = resultTable.getDataSchema();
    assertEquals(dataSchema.getColumnDataTypes(), new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.BOOLEAN, DataSchema.ColumnDataType.BOOLEAN, DataSchema.ColumnDataType.BOOLEAN, DataSchema.ColumnDataType.BOOLEAN });
    List<Object[]> rows = resultTable.getRows();
    for (int i = 0; i < rows.size(); i++) {
        Object[] row = rows.get(i);
        boolean iPv4Result = (boolean) row[0];
        boolean iPv6Result = (boolean) row[1];
        boolean expectedIPv4Result = (boolean) row[2];
        boolean expectedIPv6Result = (boolean) row[3];
        assertEquals(iPv4Result, expectedIPv4Result);
        assertEquals(iPv6Result, expectedIPv6Result);
    }
    // called in filter
    query = String.format("select count(*) from %s where isSubnetOf(%s, %s)", RAW_TABLE_NAME, IPv4_PREFIX_COLUMN_STRING, IPv4_ADDRESS_COLUMN);
    brokerResponse = getBrokerResponse(query);
    resultTable = brokerResponse.getResultTable();
    rows = resultTable.getRows();
    assertEquals(rows.size(), 1);
    assertEquals(rows.get(0)[0], _expectedNumberIpv4Contains * 4);
    query = String.format("select count(*) from %s where isSubnetOf(%s, %s)", RAW_TABLE_NAME, IPv6_PREFIX_COLUMN_STRING, IPv6_ADDRESS_COLUMN);
    brokerResponse = getBrokerResponse(query);
    resultTable = brokerResponse.getResultTable();
    rows = resultTable.getRows();
    assertEquals(rows.size(), 1);
    assertEquals(rows.get(0)[0], _expectedNumberIpv6Contains * 4);
    // called in CASE statement
    query = String.format("select (case when isSubnetOf('105.25.245.115/27', %s) then 'case1' when " + "isSubnetOf('2001:db8:85a3::8a2e:370:7334/62', %s) then 'case2' else 'case3' " + "end) as col1 from %s order by col1 limit 100", IPv4_ADDRESS_COLUMN, IPv6_ADDRESS_COLUMN, RAW_TABLE_NAME);
    brokerResponse = getBrokerResponse(query);
    resultTable = brokerResponse.getResultTable();
    dataSchema = resultTable.getDataSchema();
    assertEquals(dataSchema.getColumnDataTypes(), new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.STRING });
    rows = resultTable.getRows();
    for (int i = 0; i < rows.size(); i++) {
        Object[] row = rows.get(i);
        if (i < 4) {
            // case 1
            assertEquals("case1", row[0]);
        } else if (i < 8) {
            // case 2
            assertEquals("case2", row[0]);
        } else {
            assertEquals("case3", row[0]);
        }
    }
}

