/**
 * Test an aggregation function over json path expression in SELECT clause.
 */
@Test(enabled = false)
public void testTransformFunctionOverJsonPathSelectExpression() {
    // Apply string transform function on json path expression.
    Object[][] expecteds1 = { { "DAFFY" } };
    checkResult("SELECT UPPER(jsonColumn.name.first) FROM testTable LIMIT 1", expecteds1);
    checkResult("SELECT UPPER(jsonColumnWithoutIndex.name.first) FROM testTable LIMIT 1", expecteds1);
    // Apply date transform function on json path expression and check for IS NULL
    Object[][] expecteds2 = { { Long.MIN_VALUE } };
    checkResult("SELECT FROMEPOCHDAYS(jsonColumn.days) FROM testTable WHERE jsonColumn.days IS NULL LIMIT 1", expecteds2);
    try {
        checkResult("SELECT FROMEPOCHDAYS(jsonColumnWithoutIndex.days) FROM testTable WHERE jsonColumnWithoutIndex.days IS NULL" + " LIMIT 1", expecteds2);
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getMessage(), "java.lang.UnsupportedOperationException: Unsupported predicate type: IS_NULL");
    }
    // Apply date transform function on json path expression and check for IS NOT NULL
    Object[][] expecteds3 = { { 9590400000L } };
    checkResult("SELECT FROMEPOCHDAYS(jsonColumn.days) FROM testTable WHERE jsonColumn.days IS NOT NULL LIMIT 1", expecteds3);
    try {
        checkResult("SELECT FROMEPOCHDAYS(jsonColumnWithoutIndex.days) FROM testTable WHERE jsonColumnWithoutIndex.days IS NOT " + "NULL LIMIT 1", expecteds3);
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getMessage(), "java.lang.UnsupportedOperationException: Unsupported predicate type: IS_NOT_NULL");
    }
}

