    try {
        FluentQueryTest.withBaseDir(_baseDir).givenTable(new Schema.SchemaBuilder().setSchemaName("testTable").addMetricField("id", FieldSpec.DataType.INT).addSingleValueDimension("skills", FieldSpec.DataType.STRING).build(), TABLE_CONFIG).onFirstInstance(new Object[] { 1, "swimming" }).whenQuery("select TEXT_MATCH(id, 'sewing') as match from testTable");
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getCause().getMessage(), "Cannot apply TEXT_MATCH on column: id without text index");
    }
    try {
        FluentQueryTest.withBaseDir(_baseDir).givenTable(new Schema.SchemaBuilder().setSchemaName("testTable").addMetricField("id", FieldSpec.DataType.INT).addSingleValueDimension("skills", FieldSpec.DataType.STRING).build(), new TableConfigBuilder(TableType.OFFLINE).setTableName("testTable").addFieldConfig(new FieldConfig("skills", FieldConfig.EncodingType.RAW, List.of(FieldConfig.IndexType.TEXT), null, Map.of(FieldConfig.TEXT_FST_TYPE, FieldConfig.TEXT_NATIVE_FST_LITERAL))).build()).onFirstInstance(new Object[] { 1, "swimming" }).whenQuery("select TEXT_MATCH(skills, 'sewing') as match from testTable");
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getCause().getMessage(), "TEXT_MATCH is not supported on column: skills with native text index");
    }
    try {
        FluentQueryTest.withBaseDir(_baseDir).givenTable(new Schema.SchemaBuilder().setSchemaName("testTable").addMetricField("id", FieldSpec.DataType.INT).addSingleValueDimension("skills", FieldSpec.DataType.STRING).build(), TABLE_CONFIG).onFirstInstance(new Object[] { 1, "sewing, cooking" }).whenQuery("select TEXT_MATCH('id', 'sewing') as match from testTable");
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getCause().getMessage(), "The first argument of TEXT_MATCH transform function must be a single-valued column");
    }
    try {
        FluentQueryTest.withBaseDir(_baseDir).givenTable(new Schema.SchemaBuilder().setSchemaName("testTable").addMultiValueDimension("id", FieldSpec.DataType.STRING).addSingleValueDimension("skills", FieldSpec.DataType.STRING).build(), TABLE_CONFIG).onFirstInstance(new Object[] { 1, "sewing, cooking" }).whenQuery("select TEXT_MATCH(id, 'sewing') as match from testTable");
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getCause().getMessage(), "The first argument of TEXT_MATCH transform function must be a single-valued column");
    }
    try {
        FluentQueryTest.withBaseDir(_baseDir).givenTable(new Schema.SchemaBuilder().setSchemaName("testTable").addMultiValueDimension("id", FieldSpec.DataType.STRING).addSingleValueDimension("skills", FieldSpec.DataType.STRING).build(), TABLE_CONFIG).onFirstInstance(new Object[] { 1, "sewing, cooking" }).whenQuery("select TEXT_MATCH(skills, id) as match from testTable");
        Assert.fail();
    } catch (BadQueryRequestException e) {
        Assert.assertEquals(e.getCause().getMessage(), "The second argument of TEXT_MATCH transform function must be a single-valued string literal");
    }
}

