@Test
public void testQueries() {
    {
        String query = "SELECT * FROM testTable";
        BrokerResponseNative brokerResponse = getBrokerResponse(query);
        ResultTable resultTable = brokerResponse.getResultTable();
        DataSchema dataSchema = resultTable.getDataSchema();
        assertEquals(dataSchema, new DataSchema(new String[] { "timestampColumn" }, new ColumnDataType[] { ColumnDataType.TIMESTAMP }));
        List<Object[]> rows = resultTable.getRows();
        assertEquals(rows.size(), 10);
        for (int i = 0; i < 10; i++) {
            Object[] row = rows.get(i);
            assertEquals(row.length, 1);
            assertEquals(row[0], new Timestamp(BASE_TIMESTAMP + i).toString());
        }
    }
    {
        String query = "SELECT * FROM testTable ORDER BY timestampColumn DESC LIMIT 40";
        BrokerResponseNative brokerResponse = getBrokerResponse(query);
        ResultTable resultTable = brokerResponse.getResultTable();
        DataSchema dataSchema = resultTable.getDataSchema();
        assertEquals(dataSchema, new DataSchema(new String[] { "timestampColumn" }, new ColumnDataType[] { ColumnDataType.TIMESTAMP }));
        List<Object[]> rows = resultTable.getRows();
        assertEquals(rows.size(), 40);
        for (int i = 0; i < 10; i++) {
            String expectedResult = new Timestamp(BASE_TIMESTAMP + NUM_RECORDS - 1 - i).toString();
            for (int j = 0; j < 4; j++) {
                Object[] row = rows.get(i * 4 + j);
                assertEquals(row.length, 1);
                assertEquals(row[0], expectedResult);
            }
        }
    }
    {
        String query = "SELECT FROM_TIMESTAMP(timestampColumn) AS longTimestamp FROM testTable WHERE timestampColumn > '2021-01-01" + " 00:00:00.123' AND timestampColumn >= " + (BASE_TIMESTAMP + 234);
        BrokerResponseNative brokerResponse = getBrokerResponse(query);
        ResultTable resultTable = brokerResponse.getResultTable();
        DataSchema dataSchema = resultTable.getDataSchema();
        assertEquals(dataSchema, new DataSchema(new String[] { "longTimestamp" }, new ColumnDataType[] { ColumnDataType.LONG }));
        List<Object[]> rows = resultTable.getRows();
        assertEquals(rows.size(), 10);
        for (int i = 0; i < 10; i++) {
            Object[] row = rows.get(i);
            assertEquals(row.length, 1);
            assertEquals(row[0], BASE_TIMESTAMP + 234 + i);
        }
    }
    {
        String query = "SELECT DISTINCT timestampColumn FROM testTable ORDER BY timestampColumn";
        BrokerResponseNative brokerResponse = getBrokerResponse(query);
        ResultTable resultTable = brokerResponse.getResultTable();
        DataSchema dataSchema = resultTable.getDataSchema();
        assertEquals(dataSchema, new DataSchema(new String[] { "timestampColumn" }, new ColumnDataType[] { ColumnDataType.TIMESTAMP }));
        List<Object[]> rows = resultTable.getRows();
        assertEquals(rows.size(), 10);
        for (int i = 0; i < 10; i++) {
            Object[] row = rows.get(i);
            assertEquals(row.length, 1);
            assertEquals(row[0], new Timestamp(BASE_TIMESTAMP + i).toString());
        }
    }
    {
        String query = "SELECT COUNT(*) AS count, timestampColumn FROM testTable GROUP BY timestampColumn ORDER BY timestampColumn" + " DESC";
        BrokerResponseNative brokerResponse = getBrokerResponse(query);
        ResultTable resultTable = brokerResponse.getResultTable();
        DataSchema dataSchema = resultTable.getDataSchema();
        assertEquals(dataSchema, new DataSchema(new String[] { "count", "timestampColumn" }, new ColumnDataType[] { ColumnDataType.LONG, ColumnDataType.TIMESTAMP }));
        List<Object[]> rows = resultTable.getRows();
        assertEquals(rows.size(), 10);
        for (int i = 0; i < 10; i++) {
            Object[] row = rows.get(i);
            assertEquals(row.length, 2);
            assertEquals(row[0], 4L);
            assertEquals(row[1], new Timestamp(BASE_TIMESTAMP + NUM_RECORDS - i - 1).toString());
        }
    }
    {
        String query = "SELECT TO_TIMESTAMP(MAX(timestampColumn)) AS maxTimestamp FROM testTable GROUP BY timestampColumn HAVING " + "maxTimestamp < '2021-01-01 00:00:00.005' ORDER BY maxTimestamp";
        BrokerResponseNative brokerResponse = getBrokerResponse(query);
        ResultTable resultTable = brokerResponse.getResultTable();
        DataSchema dataSchema = resultTable.getDataSchema();
        assertEquals(dataSchema, new DataSchema(new String[] { "maxTimestamp" }, new ColumnDataType[] { ColumnDataType.TIMESTAMP }));
        List<Object[]> rows = resultTable.getRows();
        assertEquals(rows.size(), 5);
        for (int i = 0; i < 5; i++) {
            Object[] row = rows.get(i);
            assertEquals(row.length, 1);
            assertEquals(row[0], new Timestamp(BASE_TIMESTAMP + i).toString());
        }
    }
}

