    Assert.assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(0).asText(), "count(*)", "must return column name 'count(*)");
    Assert.assertEquals(response.get("resultTable").get("rows").get(0).get(0).asInt(), 97889, "must return row count 97889");
    Assert.assertTrue(response.get("exceptions").isEmpty(), "must not return exception");
    // user with valid auth but no table access - must return 403
    try {
        sendPostRequest("http://localhost:" + getRandomBrokerPort() + "/query/sql", "{\"sql\":\"SELECT count(*) FROM baseballStats\"}", AUTH_HEADER_USER);
    } catch (IOException e) {
