@Test
public void testResponseStoreCleaner() throws Exception {
    List<CursorResponseNative> requestIds = JsonUtils.stringToObject(ClusterTest.sendGetRequest(getBrokerGetAllResponseStoresApiUrl(getBrokerBaseApiUrl()), getHeaders()), new TypeReference<>() {
    });
    int numQueryResults = requestIds.size();
    _resultSize = 100000;
    this.testQuery(TEST_QUERY_ONE);
    // Sleep so that both the queries do not have the same submission time.
    Thread.sleep(50);
    this.testQuery(TEST_QUERY_TWO);
    requestIds = JsonUtils.stringToObject(ClusterTest.sendGetRequest(getBrokerGetAllResponseStoresApiUrl(getBrokerBaseApiUrl()), getHeaders()), new TypeReference<>() {
    });
    int numQueryResultsAfter = requestIds.size();
    Assert.assertEquals(requestIds.size() - numQueryResults, 2);
    CursorResponseNative cursorResponse0 = JsonUtils.stringToObject(ClusterTest.sendGetRequest(getBrokerResponseApiUrl(getBrokerBaseApiUrl(), requestIds.get(0).getRequestId()), getHeaders()), new TypeReference<>() {
    });
    CursorResponseNative cursorResponse1 = JsonUtils.stringToObject(ClusterTest.sendGetRequest(getBrokerResponseApiUrl(getBrokerBaseApiUrl(), requestIds.get(1).getRequestId()), getHeaders()), new TypeReference<>() {
    });
    // Get the lower submission time.
    long expirationTime0 = cursorResponse0.getExpirationTimeMs();
    long expirationTime1 = cursorResponse1.getExpirationTimeMs();
    Properties perodicTaskProperties = new Properties();
    perodicTaskProperties.setProperty("requestId", "CursorIntegrationTest");
    perodicTaskProperties.setProperty(ResponseStoreCleaner.CLEAN_AT_TIME, Long.toString(Math.min(expirationTime0, expirationTime1)));
    _controllerStarter.getPeriodicTaskScheduler().scheduleNow("ResponseStoreCleaner", perodicTaskProperties);
    // The periodic task is run in an executor thread. Give the thread some time to run the cleaner.
    TestUtils.waitForCondition(aVoid -> {
        try {
            List<CursorResponse> getNumQueryResults = JsonUtils.stringToObject(ClusterTest.sendGetRequest(getBrokerGetAllResponseStoresApiUrl(getBrokerBaseApiUrl()), getHeaders()), List.class);
            return getNumQueryResults.size() < numQueryResultsAfter;
        } catch (Exception e) {
            LOGGER.error(e.getMessage());
            return false;
        }
    }, 500L, 100_000L, "Failed to load delete query results", true);
}

