@Test(dataProvider = "useV2QueryEngine")
public void testCpcUnionQueries(boolean useMultiStageQueryEngine) throws Exception {
    setUseMultiStageQueryEngine(useMultiStageQueryEngine);
    for (int i = 0; i < 10; i++) {
        String query = "SELECT " + "DISTINCT_COUNT_CPC_SKETCH(metCpcSketchBytes), " + "GET_CPC_SKETCH_ESTIMATE(DISTINCT_COUNT_RAW_CPC_SKETCH(metCpcSketchBytes)) " + "FROM " + getTableName() + " WHERE id=" + i;
        JsonNode jsonNode = postQuery(query);
        long distinctCount = jsonNode.get("resultTable").get("rows").get(0).get(0).asLong();
        assertEquals(jsonNode.get("resultTable").get("rows").get(0).get(1).asLong(), distinctCount);
        query = "SELECT " + "GET_CPC_SKETCH_ESTIMATE(DISTINCT_COUNT_RAW_CPC_SKETCH(metCpcSketchBytes) " + "FILTER (WHERE id = " + i + ")) " + "FROM " + getTableName();
        jsonNode = postQuery(query);
        assertEquals(jsonNode.get("resultTable").get("rows").get(0).get(0).asLong(), distinctCount);
    }
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
