@Test(dataProvider = "useV2QueryEngine")
public void testTupleIntersectionQueries(boolean useMultiStageQueryEngine) throws Exception {
    setUseMultiStageQueryEngine(useMultiStageQueryEngine);
    for (int i = 1; i < 9; i++) {
        // Query with Intersection
        String query = "SELECT " + "GET_INT_TUPLE_SKETCH_ESTIMATE(INT_SUM_TUPLE_SKETCH_INTERSECT( " + "DISTINCT_COUNT_RAW_INTEGER_SUM_TUPLE_SKETCH(metTupleSketchBytes) " + "FILTER (WHERE id = " + (i - 1) + " OR id = " + i + ")," + "DISTINCT_COUNT_RAW_INTEGER_SUM_TUPLE_SKETCH(metTupleSketchBytes) " + "FILTER (WHERE id = " + i + " OR id = " + (i + 1) + ")))," + "DISTINCT_COUNT_RAW_INTEGER_SUM_TUPLE_SKETCH(metTupleSketchBytes) " + "FILTER (WHERE id = " + (i - 1) + " OR id = " + i + ")," + "DISTINCT_COUNT_RAW_INTEGER_SUM_TUPLE_SKETCH(metTupleSketchBytes) " + "FILTER (WHERE id = " + (i + 1) + " OR id = " + i + ")" + " FROM " + getTableName();
        JsonNode jsonNode = postQuery(query);
        String sketch1 = jsonNode.get("resultTable").get("rows").get(0).get(1).asText();
        String sketch2 = jsonNode.get("resultTable").get("rows").get(0).get(2).asText();
        Sketch<IntegerSummary> deserializedSketch1 = ObjectSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.deserialize(Base64.getDecoder().decode(sketch1));
        Sketch<IntegerSummary> deserializedSketch2 = ObjectSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.deserialize(Base64.getDecoder().decode(sketch2));
        Intersection<IntegerSummary> intersection = new Intersection<>(new IntegerSummarySetOperations(IntegerSummary.Mode.Sum, IntegerSummary.Mode.Sum));
        intersection.intersect(deserializedSketch1);
        intersection.intersect(deserializedSketch2);
        long estimate = (long) intersection.getResult().getEstimate();
        assertEquals(jsonNode.get("resultTable").get("rows").get(0).get(0).asLong(), estimate);
    }
}

