@Test
public void testOrderByKeysIsPushedToFinalAggregationStageWithoutGroupTrimSize() throws Exception {
    // is_enable_group_trim enables V1-style trimming in leaf nodes,
    // with numGroupsLimit and minSegmentGroupTrimSize,
    // while group_trim_size - in final aggregation node
    // NOTE: `set numGroupsLimit=8` global query option applies to both:
    // - segment aggregation in leaf stage
    // - cross-segment aggregation in intermediate V2 stage
    // The latter can easily produce unstable result due to concurrent IndexedTable operation scheduling.
    // To stabilize result here, we override it with num_groups_limit hint.
    assertResultAndPlan(// group_trim_size should sort and limit v2 aggregate output if order by and limit is propagated
    " set numGroupsLimit=8; set minSegmentGroupTrimSize=7;", " select /*+  aggOptions(is_enable_group_trim='true',num_groups_limit='100') */ i, j, count(*) as cnt " + " from " + getTableName() + " group by i, j " + " order by i, j desc " + " limit 1", ""i"["INT"],	"j"["LONG"],	"cnt"["LONG"]
" + "0,	7,	2", "Execution Plan
" + "LogicalSort(sort0=[$0], sort1=[$1], dir0=[ASC], dir1=[DESC], offset=[0], fetch=[1])
" + "  PinotLogicalSortExchange(distribution=[hash], collation=[[0, 1 DESC]], isSortOnSender=[false], " + "isSortOnReceiver=[true])
" + "    LogicalSort(sort0=[$0], sort1=[$1], dir0=[ASC], dir1=[DESC], fetch=[1])
" + "      PinotLogicalAggregate(group=[{0, 1}], agg#0=[COUNT($2)], aggType=[FINAL], collations=[[0, 1 " + "DESC]], limit=[1])
" + "        PinotLogicalExchange(distribution=[hash[0, 1]])
" + "          LeafStageCombineOperator(table=[mytable])
" + "            StreamingInstanceResponse
" + "              CombineGroupBy
" + "                GroupBy(groupKeys=[[i, j]], aggregations=[[count(*)]])
" + "                  Project(columns=[[i, j]])
" + "                    DocIdSet(maxDocs=[40000])
" + "                      FilterMatchEntireSegment(numDocs=[80])
");
}

