@Test
public void testUpdateIdealState() {
    // In Helix 0.9.8, we get error logs like below:
    // 13:03:51.576 ERROR [ZkBaseDataAccessor] [main] Exception while setting path:
    // /HelixZNodeSizeLimitTest/IDEALSTATES/mytable_OFFLINE
    //  org.apache.helix.HelixException: Data size larger than 1M
    //  at org.apache.helix.manager.zk.zookeeper.ZkClient.checkDataSizeLimit(ZkClient.java:1513) ~[helix-core-0.9.8
    //  .jar:0.9.8]
    //  at org.apache.helix.manager.zk.zookeeper.ZkClient.writeDataReturnStat(ZkClient.java:1406) ~[helix-core-0.9.8
    //  .jar:0.9.8]
    String tableNameWithType = getTableName() + "_OFFLINE";
    System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES, "4000000");
    // The updated IdealState after compression is roughly 2MB
    try {
        HelixHelper.updateIdealState(_helixManager, tableNameWithType, idealState -> {
            Map<String, Map<String, String>> currentAssignment = idealState.getRecord().getMapFields();
            for (int i = 0; i < 500_000; i++) {
                currentAssignment.put("segment_" + i, ImmutableMap.of("Server_with_some_reasonable_long_prefix_" + (i % 10), "ONLINE"));
                currentAssignment.put("segment_" + i, ImmutableMap.of("Server_with_some_reasonable_long_prefix_" + (i % 9), "ONLINE"));
            }
            return idealState;
        });
    } catch (Exception e) {
        Assert.fail("Exception shouldn't be thrown even if the data size of the ideal state is larger than 1M");
    }
}

@Test
public void testUpdateBrokerResource() throws Exception {
    // Add a new broker to the cluster
    BaseBrokerStarter brokerStarter = startOneBroker(1);
    // Check if broker is added to all the tables in broker resource
    String clusterName = getHelixClusterName();
    String brokerId = brokerStarter.getInstanceId();
    IdealState brokerResourceIdealState = _helixAdmin.getResourceIdealState(clusterName, CommonConstants.Helix.BROKER_RESOURCE_INSTANCE);
    for (Map<String, String> brokerAssignment : brokerResourceIdealState.getRecord().getMapFields().values()) {
        assertEquals(brokerAssignment.get(brokerId), CommonConstants.Helix.StateModel.BrokerResourceStateModel.ONLINE);
    }
    TestUtils.waitForCondition(aVoid -> {
        ExternalView brokerResourceExternalView = _helixAdmin.getResourceExternalView(clusterName, CommonConstants.Helix.BROKER_RESOURCE_INSTANCE);
        for (Map<String, String> brokerAssignment : brokerResourceExternalView.getRecord().getMapFields().values()) {
            if (!brokerAssignment.containsKey(brokerId)) {
                return false;
            }
        }
        return true;
    }, 60_000L, "Failed to find broker in broker resource ExternalView");
    // Stop the broker
    brokerStarter.stop();
    _brokerPorts.remove(_brokerPorts.size() - 1);
    // Dropping the broker should fail because it is still in the broker resource
    try {
        sendDeleteRequest(_controllerRequestURLBuilder.forInstance(brokerId));
        fail("Dropping instance should fail because it is still in the broker resource");
    } catch (Exception e) {
        // Expected
    }
    // Untag the broker and update the broker resource so that it is removed from the broker resource
    sendPutRequest(_controllerRequestURLBuilder.forInstanceUpdateTags(brokerId, Collections.emptyList(), true));
    // Check if broker is removed from all the tables in broker resource
    brokerResourceIdealState = _helixAdmin.getResourceIdealState(clusterName, CommonConstants.Helix.BROKER_RESOURCE_INSTANCE);
    for (Map<String, String> brokerAssignment : brokerResourceIdealState.getRecord().getMapFields().values()) {
        assertFalse(brokerAssignment.containsKey(brokerId));
    }
    TestUtils.waitForCondition(aVoid -> {
        ExternalView brokerResourceExternalView = _helixAdmin.getResourceExternalView(clusterName, CommonConstants.Helix.BROKER_RESOURCE_INSTANCE);
        for (Map<String, String> brokerAssignment : brokerResourceExternalView.getRecord().getMapFields().values()) {
            if (brokerAssignment.containsKey(brokerId)) {
                return false;
            }
        }
        return true;
    }, 60_000L, "Failed to remove broker from broker resource ExternalView");
    // Dropping the broker should success now
    sendDeleteRequest(_controllerRequestURLBuilder.forInstance(brokerId));
    // Check if broker is dropped from the cluster
    assertFalse(_helixAdmin.getInstancesInCluster(clusterName).contains(brokerId));
}

