    String sqlQueryPrefix = "WITH data as (SELECT 1 as \"foo\" FROM mytable) " + "SELECT * FROM data WHERE \"foo\" ";
    JsonNode jsonNode = postQuery(sqlQueryPrefix + "= 'test'");
