public void testDirectFilteredAggregationWithNoValueMatchingAggregationFilterDefault() throws Exception {
    // Use a hint to ensure that the aggregation will not be pushed to the leaf stage, so that we can test the
    // MultistageGroupByExecutor. This will use a "DIRECT" aggregation.
    String sqlQuery = "SELECT /*+ aggOptions(is_skip_leaf_stage_group_by='true') */" + "AirlineID, COUNT(*) FILTER (WHERE Origin = 'garbage') FROM mytable WHERE AirlineID > 20000 GROUP BY " + "AirlineID";
