@Test
public void testRebalancePreChecks() throws Exception {
    // setup the rebalance config
    RebalanceConfig rebalanceConfig = new RebalanceConfig();
    rebalanceConfig.setDryRun(true);
    TableConfig tableConfig = getOfflineTableConfig();
    // Ensure pre-check status is null if not enabled
    RebalanceResult rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    assertNull(rebalanceResult.getPreChecksResult());
    // Enable pre-checks, nothing is set
    rebalanceConfig.setPreChecks(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "Instance assignment not allowed, no need for minimizeDataMovement", RebalancePreCheckerResult.PreCheckStatus.PASS, "No need to reload", RebalancePreCheckerResult.PreCheckStatus.PASS, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Enable minimizeDataMovement
    tableConfig.setInstanceAssignmentConfigMap(createInstanceAssignmentConfigMap(true));
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "minimizeDataMovement is enabled", RebalancePreCheckerResult.PreCheckStatus.PASS, "No need to reload", RebalancePreCheckerResult.PreCheckStatus.PASS, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Override minimizeDataMovement
    rebalanceConfig.setMinimizeDataMovement(RebalanceConfig.MinimizeDataMovementOptions.DISABLE);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "minimizeDataMovement is enabled in table config but it's overridden with disabled", RebalancePreCheckerResult.PreCheckStatus.WARN, "No need to reload", RebalancePreCheckerResult.PreCheckStatus.PASS, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Use default minimizeDataMovement and disable it in table config
    tableConfig.setInstanceAssignmentConfigMap(createInstanceAssignmentConfigMap(false));
    rebalanceConfig.setMinimizeDataMovement(RebalanceConfig.MinimizeDataMovementOptions.DEFAULT);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "minimizeDataMovement is not enabled but instance assignment is allowed", RebalancePreCheckerResult.PreCheckStatus.WARN, "No need to reload", RebalancePreCheckerResult.PreCheckStatus.PASS, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Undo minimizeDataMovement, update the table config to add a column to bloom filter
    rebalanceConfig.setMinimizeDataMovement(RebalanceConfig.MinimizeDataMovementOptions.ENABLE);
    tableConfig.getIndexingConfig().getBloomFilterColumns().add("Quarter");
    tableConfig.setInstanceAssignmentConfigMap(null);
    updateTableConfig(tableConfig);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "Instance assignment not allowed, no need for minimizeDataMovement", RebalancePreCheckerResult.PreCheckStatus.PASS, "Reload needed prior to running rebalance", RebalancePreCheckerResult.PreCheckStatus.WARN, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Undo tableConfig change
    tableConfig.getIndexingConfig().getBloomFilterColumns().remove("Quarter");
    updateTableConfig(tableConfig);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "Instance assignment not allowed, no need for minimizeDataMovement", RebalancePreCheckerResult.PreCheckStatus.PASS, "No need to reload", RebalancePreCheckerResult.PreCheckStatus.PASS, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Add a new server (to force change in instance assignment) and enable reassignInstances
    // Validate that the status for reload is still PASS (i.e. even though an extra server is tagged which has no
    // segments assigned for this table, we don't try to get needReload status from that extra server, otherwise
    // ERROR status would be returned)
    BaseServerStarter serverStarter0 = startOneServer(NUM_SERVERS);
    rebalanceConfig.setReassignInstances(true);
    tableConfig.setInstanceAssignmentConfigMap(null);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.DONE, "Instance assignment not allowed, no need for minimizeDataMovement", RebalancePreCheckerResult.PreCheckStatus.PASS, "No need to reload", RebalancePreCheckerResult.PreCheckStatus.PASS, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    rebalanceConfig.setReassignInstances(false);
    // Stop the added server
    serverStarter0.stop();
    TestUtils.waitForCondition(aVoid -> _resourceManager.dropInstance(serverStarter0.getInstanceId()).isSuccessful(), 60_000L, "Failed to drop added server");
    // Add a schema change
    Schema schema = createSchema();
    schema.addField(new MetricFieldSpec("NewAddedIntMetric", DataType.INT, 1));
    updateSchema(schema);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "Instance assignment not allowed, no need for minimizeDataMovement", RebalancePreCheckerResult.PreCheckStatus.PASS, "Reload needed prior to running rebalance", RebalancePreCheckerResult.PreCheckStatus.WARN, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Keep schema change and update table config to add minimizeDataMovement
    tableConfig.setInstanceAssignmentConfigMap(createInstanceAssignmentConfigMap(true));
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "minimizeDataMovement is enabled", RebalancePreCheckerResult.PreCheckStatus.PASS, "Reload needed prior to running rebalance", RebalancePreCheckerResult.PreCheckStatus.WARN, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Keep schema change and update table config to add instance config map with minimizeDataMovement = false
    tableConfig.setInstanceAssignmentConfigMap(createInstanceAssignmentConfigMap(false));
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.NO_OP, "minimizeDataMovement is enabled", RebalancePreCheckerResult.PreCheckStatus.PASS, "Reload needed prior to running rebalance", RebalancePreCheckerResult.PreCheckStatus.WARN, "All rebalance parameters look good", RebalancePreCheckerResult.PreCheckStatus.PASS);
    // Add a new server (to force change in instance assignment) and enable reassignInstances
    // Trigger rebalance config warning
    BaseServerStarter serverStarter1 = startOneServer(NUM_SERVERS + 1);
    rebalanceConfig.setReassignInstances(true);
    rebalanceConfig.setBestEfforts(true);
    rebalanceConfig.setBootstrap(true);
    rebalanceConfig.setMinAvailableReplicas(-1);
    tableConfig.setInstanceAssignmentConfigMap(null);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalancePreCheckStatus(rebalanceResult, RebalanceResult.Status.DONE, "Instance assignment not allowed, no need for minimizeDataMovement", RebalancePreCheckerResult.PreCheckStatus.PASS, "Reload needed prior to running rebalance", RebalancePreCheckerResult.PreCheckStatus.WARN, "bestEfforts is enabled, only enable it if you know what you are doing\n" + "bootstrap is enabled which can cause a large amount of data movement, double check if this is " + "intended", RebalancePreCheckerResult.PreCheckStatus.WARN);
    // Disable dry-run
    rebalanceConfig.setBootstrap(false);
    rebalanceConfig.setBestEfforts(false);
    rebalanceConfig.setDryRun(false);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    assertNull(rebalanceResult.getPreChecksResult());
    assertEquals(rebalanceResult.getStatus(), RebalanceResult.Status.FAILED);
    // Stop the added server
    serverStarter1.stop();
    TestUtils.waitForCondition(aVoid -> _resourceManager.dropInstance(serverStarter1.getInstanceId()).isSuccessful(), 60_000L, "Failed to drop added server");
}

@Test(dataProvider = "useBothQueryEngines")
public void testRegexpReplace(boolean useMultiStageQueryEngine) throws Exception {
    setUseMultiStageQueryEngine(useMultiStageQueryEngine);
    // Correctness tests of regexpReplace.
    // Test replace all.
    String sqlQuery = "SELECT regexpReplace('CA', 'C', 'TEST')";
    JsonNode response = postQuery(sqlQuery);
    String result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "TESTA");
    sqlQuery = "SELECT regexpReplace('foobarbaz', 'b', 'X')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "fooXarXaz");
    sqlQuery = "SELECT regexpReplace('foobarbaz', 'b', 'XY')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "fooXYarXYaz");
    sqlQuery = "SELECT regexpReplace('Argentina', '(.)', '$1 ')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "A r g e n t i n a ");
    sqlQuery = "SELECT regexpReplace('Pinot is  blazing  fast', '( ){2,}', ' ')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "Pinot is blazing fast");
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, and wise','\\w+thy', 'something')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "something, something, and wise");
    sqlQuery = "SELECT regexpReplace('11234567898','(\\d)(\\d{3})(\\d{3})(\\d{4})', '$1-($2) $3-$4')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "1-(123) 456-7898");
    // Test replace starting at index.
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+thy', 'something', 4)";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "healthy, something, something and wise");
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+thy', 'something', 1)";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "hsomething, something, something and wise");
    // Test occurence
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+thy', 'something', 0, 2)";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "healthy, wealthy, something and wise");
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+thy', 'something', 0, 0)";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "something, wealthy, stealthy and wise");
    // Test flags
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+tHy', 'something', 0, 0, 'i')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "something, wealthy, stealthy and wise");
    // Negative test. Pattern match not found.
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+tHy', 'something')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "healthy, wealthy, stealthy and wise");
    // Negative test. Pattern match not found.
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+tHy', 'something', 3, 21, 'i')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "healthy, wealthy, stealthy and wise");
    // Negative test - incorrect flag
    sqlQuery = "SELECT regexpReplace('healthy, wealthy, stealthy and wise','\\w+tHy', 'something', 3, 12, 'xyz')";
    response = postQuery(sqlQuery);
    result = response.get("resultTable").get("rows").get(0).get(0).asText();
    assertEquals(result, "healthy, wealthy, stealthy and wise");
    // Test in select clause with column values
    sqlQuery = "SELECT regexpReplace(DestCityName, ' ', '', 0, -1, 'i') from mytable where OriginState = 'CA'";
    response = postQuery(sqlQuery);
    JsonNode rows = response.get("resultTable").get("rows");
    for (int i = 0; i < rows.size(); i++) {
        JsonNode row = rows.get(i);
        assertFalse(row.get(0).asText().contains(" "));
    }
    // Test in where clause
    sqlQuery = "SELECT count(*) from mytable where regexpReplace(OriginState, '[VC]A', 'TEST') = 'TEST'";
    response = postQuery(sqlQuery);
    int count1 = response.get("resultTable").get("rows").get(0).get(0).asInt();
    sqlQuery = "SELECT count(*) from mytable where OriginState='CA' or OriginState='VA'";
    response = postQuery(sqlQuery);
    int count2 = response.get("resultTable").get("rows").get(0).get(0).asInt();
    assertEquals(count1, count2);
    // Test nested transform
    sqlQuery = "SELECT count(*) from mytable where contains(regexpReplace(OriginState, '(C)(A)', '$1TEST$2'), 'CTESTA')";
    response = postQuery(sqlQuery);
    count1 = response.get("resultTable").get("rows").get(0).get(0).asInt();
    sqlQuery = "SELECT count(*) from mytable where OriginState='CA'";
    response = postQuery(sqlQuery);
    count2 = response.get("resultTable").get("rows").get(0).get(0).asInt();
    assertEquals(count1, count2);
}

