@Test(dataProvider = "useBothQueryEngines")
public void testQueryWithAlias(boolean useMultiStageQueryEngine) throws Exception {
    setUseMultiStageQueryEngine(useMultiStageQueryEngine);
    {
        String pinotQuery = "SELECT count(*), DaysSinceEpoch as d FROM mytable WHERE d = 16138 GROUP BY d";
        assertQuery(pinotQuery).firstException().hasErrorCode(QueryErrorCode.UNKNOWN_COLUMN);
    }
    {
        //test same alias name with column name
        String query = "SELECT ArrTime AS ArrTime, Carrier AS Carrier, DaysSinceEpoch AS DaysSinceEpoch FROM mytable " + "ORDER BY DaysSinceEpoch DESC";
        testQuery(query);
        query = "SELECT ArrTime AS ArrTime, DaysSinceEpoch AS DaysSinceEpoch, Carrier AS Carrier FROM mytable " + "ORDER BY Carrier DESC";
        testQuery(query);
        query = "SELECT ArrTime AS ArrTime, DaysSinceEpoch AS DaysSinceEpoch, Carrier AS Carrier FROM mytable " + "ORDER BY Carrier DESC, ArrTime DESC";
        testQuery(query);
    }
    {
        //test single alias
        String query = "SELECT ArrTime, Carrier AS CarrierName, DaysSinceEpoch FROM mytable ORDER BY DaysSinceEpoch DESC";
        testQuery(query);
        query = "SELECT count(*) AS cnt, max(ArrTime) as maxArrTime FROM mytable";
        testQuery(query);
        query = "SELECT count(*) AS cnt, Carrier AS CarrierName FROM mytable GROUP BY CarrierName ORDER BY cnt";
        testQuery(query);
        // Test: 1. Alias should not be applied to filter; 2. Ordinal can be properly applied
        query = "SELECT DaysSinceEpoch + 100 AS DaysSinceEpoch, COUNT(*) AS cnt FROM mytable WHERE DaysSinceEpoch <= 16312 " + "GROUP BY 1 ORDER BY 1 DESC";
        // NOTE: H2 does not support ordinal in GROUP BY
        String h2Query = "SELECT DaysSinceEpoch + 100 AS DaysSinceEpoch, COUNT(*) AS cnt FROM mytable WHERE DaysSinceEpoch <= 16312 " + "GROUP BY DaysSinceEpoch ORDER BY 1 DESC";
        testQuery(query, h2Query);
    }
    {
        //test multiple alias
        String query = "SELECT ArrTime, Carrier, Carrier AS CarrierName1, Carrier AS CarrierName2, DaysSinceEpoch FROM mytable " + "ORDER BY DaysSinceEpoch DESC";
        testQuery(query);
        query = "SELECT count(*) AS cnt, max(ArrTime) as maxArrTime1, max(ArrTime) as maxArrTime2 FROM mytable";
        testQuery(query);
        query = "SELECT count(*), count(*) AS cnt1, count(*) AS cnt2, Carrier AS CarrierName FROM mytable " + "GROUP BY CarrierName ORDER BY cnt2";
        testQuery(query);
    }
    {
        //test alias with distinct
        String query = "SELECT DISTINCT ArrTime, Carrier, Carrier AS CarrierName1, Carrier AS CarrierName2, DaysSinceEpoch " + "FROM mytable ORDER BY DaysSinceEpoch DESC";
        testQuery(query);
        query = "SELECT ArrTime, Carrier, Carrier AS CarrierName1, Carrier AS CarrierName2, DaysSinceEpoch FROM mytable " + "GROUP BY ArrTime, Carrier, DaysSinceEpoch ORDER BY DaysSinceEpoch DESC";
        testQuery(query);
    }
}

