@Test
public void testExplainPlanQueryV2() throws Exception {
    setUseMultiStageQueryEngine(true);
    // language=sql
    //@formatter:off
    String query1 = "EXPLAIN PLAN WITHOUT IMPLEMENTATION FOR " + "SELECT count(*) AS count, Carrier AS name " + "FROM mytable " + "GROUP BY name " + "ORDER BY 1";
    //@formatter:on
    String response1 = postQuery(query1).get("resultTable").toString();
    // Replace string "docs:[0-9]+" with "docs:*" so that test doesn't fail when number of documents change. This is
    // needed because both OfflineClusterIntegrationTest and MultiNodesOfflineClusterIntegrationTest run this test
    // case with different number of documents in the segment.
    response1 = response1.replaceAll("docs:[0-9]+", "docs:*").replaceAll("Time: \\d+\\.\\d+", "Time:*");
    JsonNode response1Json = JsonUtils.stringToJsonNode(response1);
    assertEquals(response1Json.get("dataSchema").get("columnNames").get(0).asText(), "SQL");
    assertEquals(response1Json.get("dataSchema").get("columnNames").get(1).asText(), "PLAN");
    assertEquals(response1Json.get("dataSchema").get("columnNames").get(2).asText(), "RULE_TIMINGS");
    assertEquals(response1Json.get("dataSchema").get("columnDataTypes").get(0).asText(), "STRING");
    assertEquals(response1Json.get("dataSchema").get("columnDataTypes").get(1).asText(), "STRING");
    assertEquals(response1Json.get("dataSchema").get("columnDataTypes").get(2).asText(), "STRING");
    assertEquals(response1Json.get("rows").get(0).get(0).asText(), "EXPLAIN PLAN WITHOUT IMPLEMENTATION FOR SELECT count(*) AS count, Carrier AS name FROM mytable GROUP BY name" + " ORDER BY 1");
    assertEquals(response1Json.get("rows").get(0).get(1).asText(), "Execution Plan\n" + "LogicalSort(sort0=[$0], dir0=[ASC])\n" + "  PinotLogicalSortExchange(distribution=[hash], collation=[[0]], isSortOnSender=[false], " + "isSortOnReceiver=[true])\n" + "    LogicalProject(count=[$1], name=[$0])\n" + "      PinotLogicalAggregate(group=[{0}], agg#0=[COUNT($1)], aggType=[FINAL])\n" + "        PinotLogicalExchange(distribution=[hash[0]])\n" + "          PinotLogicalAggregate(group=[{17}], agg#0=[COUNT()], aggType=[LEAF])\n" + "            PinotLogicalTableScan(table=[[default, mytable]])\n");
    assertEquals(response1Json.get("rows").get(0).get(2).asText(), "Rule Execution Times\n" + "Rule: AggregateProjectMergeRule -> Time:*\n" + "Rule: Project -> Time:*\n" + "Rule: AggregateRemoveRule -> Time:*\n" + "Rule: SortRemoveRule -> Time:*\n");
    // In the query below, FlightNum column has an inverted index and there is no data satisfying the predicate
    // "FlightNum < 0". Hence, all segments are pruned out before query execution on the server side.
    // language=sql
    String query2 = "EXPLAIN PLAN WITHOUT IMPLEMENTATION FOR SELECT * FROM mytable WHERE FlightNum < 0";
    String response2 = postQuery(query2).get("resultTable").toString().replaceAll("Time: \\d+\\.\\d+", "Time: *");
    JsonNode response2Json = JsonUtils.stringToJsonNode(response2);
    assertEquals(response2Json.get("dataSchema").get("columnNames").get(0).asText(), "SQL");
    assertEquals(response2Json.get("dataSchema").get("columnNames").get(1).asText(), "PLAN");
    assertEquals(response2Json.get("dataSchema").get("columnNames").get(2).asText(), "RULE_TIMINGS");
    assertEquals(response2Json.get("dataSchema").get("columnDataTypes").get(0).asText(), "STRING");
    assertEquals(response2Json.get("dataSchema").get("columnDataTypes").get(1).asText(), "STRING");
    assertEquals(response2Json.get("dataSchema").get("columnDataTypes").get(2).asText(), "STRING");
    assertEquals(response2Json.get("rows").get(0).get(0).asText(), "EXPLAIN PLAN WITHOUT IMPLEMENTATION FOR SELECT * FROM mytable WHERE FlightNum < 0");
    assertTrue(Pattern.compile("Execution Plan\n" + "LogicalProject\\(.*\\)\n" + "  LogicalFilter\\(condition=\\[<\\(.*, 0\\)]\\)\n" + "    PinotLogicalTableScan\\(table=\\[\\[default, mytable]]\\)\n").matcher(response2Json.get("rows").get(0).get(1).asText()).find());
    assertEquals(response2Json.get("rows").get(0).get(2).asText(), "Rule Execution Times\n" + "Rule: Project -> Time: *\n" + "Rule: FilterProjectTransposeRule -> Time: *\n" + "Rule: Filter -> Time: *\n" + "Rule: ProjectFilterTransposeRule -> Time: *\n");
}

