@Test
public void testRebalanceDryRunSummary() throws Exception {
    // setup the rebalance config
    RebalanceConfig rebalanceConfig = new RebalanceConfig();
    rebalanceConfig.setDryRun(true);
    TableConfig tableConfig = getOfflineTableConfig();
    // Ensure summary status is non-null always
    RebalanceResult rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    assertNotNull(rebalanceResult.getRebalanceSummaryResult());
    checkRebalanceDryRunSummary(rebalanceResult, RebalanceResult.Status.NO_OP, false, getNumServers(), getNumServers(), tableConfig.getReplication());
    // Add a new server (to force change in instance assignment) and enable reassignInstances
    BaseServerStarter serverStarter1 = startOneServer(NUM_SERVERS);
    rebalanceConfig.setReassignInstances(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalanceDryRunSummary(rebalanceResult, RebalanceResult.Status.DONE, true, getNumServers(), getNumServers() + 1, tableConfig.getReplication());
    // Disable dry-run to do a real rebalance
    rebalanceConfig.setDryRun(false);
    rebalanceConfig.setDowntime(true);
    rebalanceConfig.setReassignInstances(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    assertNotNull(rebalanceResult.getRebalanceSummaryResult());
    assertEquals(rebalanceResult.getStatus(), RebalanceResult.Status.DONE);
    checkRebalanceDryRunSummary(rebalanceResult, RebalanceResult.Status.DONE, true, getNumServers(), getNumServers() + 1, tableConfig.getReplication());
    waitForRebalanceToComplete(rebalanceResult, 600_000L);
    // Untag the added server
    _resourceManager.updateInstanceTags(serverStarter1.getInstanceId(), "", false);
    // Re-enable dry-run
    rebalanceConfig.setDryRun(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalanceDryRunSummary(rebalanceResult, RebalanceResult.Status.DONE, true, getNumServers() + 1, getNumServers(), tableConfig.getReplication());
    // Disable dry-run to do a real rebalance
    rebalanceConfig.setDryRun(false);
    rebalanceConfig.setDowntime(true);
    rebalanceConfig.setReassignInstances(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    assertNotNull(rebalanceResult.getRebalanceSummaryResult());
    assertEquals(rebalanceResult.getStatus(), RebalanceResult.Status.DONE);
    waitForRebalanceToComplete(rebalanceResult, 600_000L);
    // Stop the server
    serverStarter1.stop();
    TestUtils.waitForCondition(aVoid -> _resourceManager.dropInstance(serverStarter1.getInstanceId()).isSuccessful(), 60_000L, "Failed to drop added server");
    // Try dry-run again
    rebalanceConfig.setDryRun(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalanceDryRunSummary(rebalanceResult, RebalanceResult.Status.NO_OP, false, getNumServers(), getNumServers(), tableConfig.getReplication());
    // Try dry-run with pre-checks
    rebalanceConfig.setPreChecks(true);
    rebalanceResult = _tableRebalancer.rebalance(tableConfig, rebalanceConfig, null);
    checkRebalanceDryRunSummary(rebalanceResult, RebalanceResult.Status.NO_OP, false, getNumServers(), getNumServers(), tableConfig.getReplication());
    assertNotNull(rebalanceResult.getPreChecksResult());
    assertTrue(rebalanceResult.getPreChecksResult().containsKey(DefaultRebalancePreChecker.NEEDS_RELOAD_STATUS));
    assertTrue(rebalanceResult.getPreChecksResult().containsKey(DefaultRebalancePreChecker.IS_MINIMIZE_DATA_MOVEMENT));
    assertEquals(rebalanceResult.getPreChecksResult().get(DefaultRebalancePreChecker.NEEDS_RELOAD_STATUS).getMessage(), "No need to reload");
    assertEquals(rebalanceResult.getPreChecksResult().get(DefaultRebalancePreChecker.NEEDS_RELOAD_STATUS).getPreCheckStatus(), RebalancePreCheckerResult.PreCheckStatus.PASS);
    assertEquals(rebalanceResult.getPreChecksResult().get(DefaultRebalancePreChecker.IS_MINIMIZE_DATA_MOVEMENT).getMessage(), "Instance assignment not allowed, no need for minimizeDataMovement");
    assertEquals(rebalanceResult.getPreChecksResult().get(DefaultRebalancePreChecker.IS_MINIMIZE_DATA_MOVEMENT).getPreCheckStatus(), RebalancePreCheckerResult.PreCheckStatus.PASS);
}

