            double currentRate1 = (currentCount1 - startCount1) / (double) (currentTimeMillis - startTime) * 1000;
            double currentRate2 = (currentCount2 - startCount2) / (double) (currentTimeMillis - startTime) * 1000;
            double currentServerRate = currentRate1 + currentRate2;
            LOGGER.info("Second = {}, serverRowConsumedMeter = {}, currentCount1 = {}, currentRate1 = {}, currentCount2 = {}, " + "currentRate2 = {}, currentServerCount = {}, currentServerRate = {}", i, serverRowConsumedMeter.oneMinuteRate(), currentCount1, currentRate1, currentCount2, currentRate2, currentServerCount, currentServerRate);
            Assert.assertTrue(serverRowConsumedMeter.oneMinuteRate() < SERVER_RATE_LIMIT, "Rate should be less than " + SERVER_RATE_LIMIT + ", serverOneMinuteRate = " + serverRowConsumedMeter.oneMinuteRate());
            Assert.assertTrue(currentServerRate < SERVER_RATE_LIMIT * 1.5, // Put some leeway for the rate calculation
            "Whole table ingestion rate should be less than " + SERVER_RATE_LIMIT + ", currentRate1 = " + currentRate1 + ", currentRate2 = " + currentRate2 + ", currentServerRate = " + currentServerRate);
        }
    } finally {
        dropRealtimeTable(tableName1);
        dropRealtimeTable(tableName2);
        waitForEVToDisappear(TableNameBuilder.REALTIME.tableNameWithType(tableName1));
        waitForEVToDisappear(TableNameBuilder.REALTIME.tableNameWithType(tableName2));
    }
}

