@Test
public void testRealtimeToOfflineSegmentsTask() throws Exception {
    List<SegmentZKMetadata> segmentsZKMetadata = _helixResourceManager.getSegmentsZKMetadata(_offlineTableName);
    assertTrue(segmentsZKMetadata.isEmpty());
    // The number of offline segments would be equal to the product of number of partitions for all the
    // partition columns if segment partitioning is configured.
    SegmentPartitionConfig segmentPartitionConfig = getOfflineTableConfig().getIndexingConfig().getSegmentPartitionConfig();
    int numOfflineSegmentsPerTask = segmentPartitionConfig != null ? segmentPartitionConfig.getColumnPartitionMap().values().stream().map(ColumnPartitionConfig::getNumPartitions).reduce((a, b) -> a * b).orElseThrow(() -> new RuntimeException("Expected accumulated result but not found.")) : 1;
    long expectedWatermark = _dataSmallestTimeMs + 86400000;
    for (int i = 0; i < 3; i++) {
        // Schedule task
        assertNotNull(_taskManager.scheduleTasks(new TaskSchedulingContext().setTablesToSchedule(Collections.singleton(_realtimeTableName))).get(MinionConstants.RealtimeToOfflineSegmentsTask.TASK_TYPE));
        assertTrue(_taskResourceManager.getTaskQueues().contains(PinotHelixTaskResourceManager.getHelixJobQueueName(MinionConstants.RealtimeToOfflineSegmentsTask.TASK_TYPE)));
        // Should not generate more tasks
        MinionTaskTestUtils.assertNoTaskSchedule(new TaskSchedulingContext().setTablesToSchedule(Collections.singleton(_realtimeTableName)).setTasksToSchedule(Collections.singleton(MinionConstants.RealtimeToOfflineSegmentsTask.TASK_TYPE)), _taskManager);
        // Wait at most 600 seconds for all tasks COMPLETED
        waitForTaskToComplete(expectedWatermark, _realtimeTableName);
        // check segment is in offline
        segmentsZKMetadata = _helixResourceManager.getSegmentsZKMetadata(_offlineTableName);
        assertEquals(segmentsZKMetadata.size(), (numOfflineSegmentsPerTask * (i + 1)));
        long expectedOfflineSegmentTimeMs = expectedWatermark - 86400000;
        for (int j = (numOfflineSegmentsPerTask * i); j < segmentsZKMetadata.size(); j++) {
            SegmentZKMetadata segmentZKMetadata = segmentsZKMetadata.get(j);
            assertEquals(segmentZKMetadata.getStartTimeMs(), expectedOfflineSegmentTimeMs);
            assertEquals(segmentZKMetadata.getEndTimeMs(), expectedOfflineSegmentTimeMs);
            if (segmentPartitionConfig != null) {
                assertEquals(segmentZKMetadata.getPartitionMetadata().getColumnPartitionMap().keySet(), segmentPartitionConfig.getColumnPartitionMap().keySet());
                for (String partitionColumn : segmentPartitionConfig.getColumnPartitionMap().keySet()) {
                    assertEquals(segmentZKMetadata.getPartitionMetadata().getPartitions(partitionColumn).size(), 1);
                }
            }
        }
        expectedWatermark += 86400000;
    }
    testHardcodedQueries();
}

