@Test
public void testStopResumeDeleteTaskQueue() {
    // Hold the task
    HOLD.set(true);
    // No tasks before we start.
    assertEquals(_helixTaskResourceManager.getTasksInProgress(TASK_TYPE).size(), 0);
    // Should create the task queues and generate a task in the same minion instance
    List<String> task1 = _taskManager.scheduleTasks(new TaskSchedulingContext()).get(TASK_TYPE).getScheduledTaskNames();
    assertNotNull(task1);
    assertEquals(task1.size(), 1);
    assertTrue(_helixTaskResourceManager.getTaskQueues().contains(PinotHelixTaskResourceManager.getHelixJobQueueName(TASK_TYPE)));
    assertTrue(_helixTaskResourceManager.getTasksInProgress(TASK_TYPE).contains(task1.get(0)));
    // Since we have two tables, two sub-tasks are generated -- one for each table.
    // The default concurrent sub-tasks per minion instance is 1, and we have one minion
    // instance spun up. So, one sub-tasks gets scheduled in a minion, and the other one
    // waits.
    verifyTaskCount(task1.get(0), 0, 1, 1, 2);
    // Should generate one more task, with two sub-tasks. Both of these sub-tasks will wait
    // since we have one minion instance that is still running one of the sub-tasks.
    List<String> task2 = _taskManager.scheduleTasks(new TaskSchedulingContext()).get(TASK_TYPE).getScheduledTaskNames();
    assertNotNull(task2);
    assertEquals(task2.size(), 1);
    assertTrue(_helixTaskResourceManager.getTasksInProgress(TASK_TYPE).contains(task2.get(0)));
    verifyTaskCount(task2.get(0), 0, 2, 0, 2);
    // Should not generate more tasks since SimpleMinionClusterIntegrationTests.NUM_TASKS is 2.
    // Our test task generator does not generate if there are already this many sub-tasks in the
    // running+waiting count already.
    MinionTaskTestUtils.assertNoTaskSchedule(new TaskSchedulingContext(), _taskManager);
    // Wait at most 60 seconds for all tasks IN_PROGRESS
    TestUtils.waitForCondition(input -> {
        Collection<TaskState> taskStates = _helixTaskResourceManager.getTaskStates(TASK_TYPE).values();
        assertEquals(taskStates.size(), NUM_TASKS);
        for (TaskState taskState : taskStates) {
            if (taskState != TaskState.IN_PROGRESS) {
                return false;
            }
        }
        assertFalse(TASK_SUCCESS_NOTIFIED.get());
        assertFalse(TASK_CANCELLED_NOTIFIED.get());
        assertFalse(TASK_ERROR_NOTIFIED.get());
        // Task start callback is triggered shortly after the task start execution asynchronously
        return TASK_START_NOTIFIED.get();
    }, STATE_TRANSITION_TIMEOUT_MS, "Failed to get all tasks IN_PROGRESS");
    // Wait at most 30 seconds for ZK callback to update the controller gauges
    ControllerMetrics controllerMetrics = _controllerStarter.getControllerMetrics();
    String inProgressGauge = TASK_TYPE + "." + TaskState.IN_PROGRESS;
    String stoppedGauge = TASK_TYPE + "." + TaskState.STOPPED;
    String completedGauge = TASK_TYPE + "." + TaskState.COMPLETED;
    TestUtils.waitForCondition(input -> MetricValueUtils.getGlobalGaugeValue(controllerMetrics, inProgressGauge, ControllerGauge.TASK_STATUS) == NUM_TASKS && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, stoppedGauge, ControllerGauge.TASK_STATUS) == 0 && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, completedGauge, ControllerGauge.TASK_STATUS) == 0, ZK_CALLBACK_TIMEOUT_MS, "Failed to update the controller gauges");
    // Stop the task queue
    _helixTaskResourceManager.stopTaskQueue(TASK_TYPE);
    // Wait at most 60 seconds for all tasks STOPPED
    TestUtils.waitForCondition(input -> {
        Collection<TaskState> taskStates = _helixTaskResourceManager.getTaskStates(TASK_TYPE).values();
        assertEquals(taskStates.size(), NUM_TASKS);
        for (TaskState taskState : taskStates) {
            if (taskState != TaskState.STOPPED) {
                return false;
            }
        }
        assertTrue(TASK_START_NOTIFIED.get());
        assertFalse(TASK_SUCCESS_NOTIFIED.get());
        assertFalse(TASK_ERROR_NOTIFIED.get());
        // Task cancelled callback is triggered shortly after the task framework cancels the task asynchronously
        return TASK_CANCELLED_NOTIFIED.get();
    }, STATE_TRANSITION_TIMEOUT_MS, "Failed to get all tasks STOPPED");
    // Wait at most 30 seconds for ZK callback to update the controller gauges
    TestUtils.waitForCondition(input -> MetricValueUtils.getGlobalGaugeValue(controllerMetrics, inProgressGauge, ControllerGauge.TASK_STATUS) == 0 && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, stoppedGauge, ControllerGauge.TASK_STATUS) == NUM_TASKS && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, completedGauge, ControllerGauge.TASK_STATUS) == 0, ZK_CALLBACK_TIMEOUT_MS, "Failed to update the controller gauges");
    // Task deletion requires the task queue to be stopped,
    // so deleting task1 here before resuming the task queue.
    assertTrue(_helixTaskResourceManager.getTaskStates(TASK_TYPE).containsKey(task1.get(0)));
    _helixTaskResourceManager.deleteTask(task1.get(0), false);
    // Resume the task queue, and let the task complete
    _helixTaskResourceManager.resumeTaskQueue(TASK_TYPE);
    HOLD.set(false);
    // Wait at most 60 seconds for all tasks COMPLETED
    TestUtils.waitForCondition(input -> {
        Collection<TaskState> taskStates = _helixTaskResourceManager.getTaskStates(TASK_TYPE).values();
        for (TaskState taskState : taskStates) {
            if (taskState != TaskState.COMPLETED) {
                return false;
            }
        }
        // Task deletion happens eventually along with other state transitions.
        assertFalse(_helixTaskResourceManager.getTaskStates(TASK_TYPE).containsKey(task1.get(0)));
        assertEquals(taskStates.size(), (NUM_TASKS - 1));
        assertTrue(TASK_START_NOTIFIED.get());
        assertTrue(TASK_SUCCESS_NOTIFIED.get());
        assertTrue(TASK_CANCELLED_NOTIFIED.get());
        assertFalse(TASK_ERROR_NOTIFIED.get());
        return true;
    }, STATE_TRANSITION_TIMEOUT_MS, "Failed to get all tasks COMPLETED");
    // Wait at most 30 seconds for ZK callback to update the controller gauges
    TestUtils.waitForCondition(input -> MetricValueUtils.getGlobalGaugeValue(controllerMetrics, inProgressGauge, ControllerGauge.TASK_STATUS) == 0 && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, stoppedGauge, ControllerGauge.TASK_STATUS) == 0 && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, completedGauge, ControllerGauge.TASK_STATUS) == (NUM_TASKS - 1), ZK_CALLBACK_TIMEOUT_MS, "Failed to update the controller gauges");
    // Delete the task queue
    _helixTaskResourceManager.deleteTaskQueue(TASK_TYPE, false);
    // Wait at most 60 seconds for task queue to be deleted
    TestUtils.waitForCondition(input -> !_helixTaskResourceManager.getTaskTypes().contains(TASK_TYPE), STATE_TRANSITION_TIMEOUT_MS, "Failed to delete the task queue");
    // Wait at most 30 seconds for ZK callback to update the controller gauges
    TestUtils.waitForCondition(input -> MetricValueUtils.getGlobalGaugeValue(controllerMetrics, inProgressGauge, ControllerGauge.TASK_STATUS) == 0 && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, stoppedGauge, ControllerGauge.TASK_STATUS) == 0 && MetricValueUtils.getGlobalGaugeValue(controllerMetrics, completedGauge, ControllerGauge.TASK_STATUS) == 0, ZK_CALLBACK_TIMEOUT_MS, "Failed to update the controller gauges");
}

