// Test that intermediate stages can be spooled.
// In this case Stage 4 is an intermediate stage whose single child is stage 5.
// Stage 4 is spooled and sends data to stages 3 and 7
@Test
public void intermediateSpool() throws Exception {
    JsonNode jsonNode = postQuery("SET useSpools = true;
" + "WITH group_and_sum AS (
" + "  SELECT ArrTimeBlk,
" + "    Dest,
" + "    SUM(ArrTime) AS ArrTime
" + "  FROM mytable
" + "  GROUP BY ArrTimeBlk,
" + "    Dest
" + "  limit 1000
" + "),
" + "aggregated_data AS (
" + "  SELECT
" + "    Dest,
" + "    SUM(ArrTime) AS ArrTime
" + "  FROM group_and_sum
" + "  GROUP BY
" + "    Dest
" + "),
" + "joined AS (
" + "  SELECT
" + "    s.Dest,
" + "    s.ArrTime,
" + "    (o.ArrTime) AS ArrTime2
" + "  FROM group_and_sum s
" + "  JOIN aggregated_data o
" + "  ON s.Dest = o.Dest
" + ")
" + "SELECT *
" + "FROM joined
" + "LIMIT 1");
    JsonNode stats = jsonNode.get("stageStats");
    assertNoError(jsonNode);
    DocumentContext parsed = JsonPath.parse(stats.toString());
    checkSpoolTimes(parsed, 4, 3, 1);
    checkSpoolTimes(parsed, 4, 7, 1);
    checkSpoolSame(parsed, 4, 3, 7);
}

