@Test
public void testStarTreeWithDistinctCountHllConfigurations() throws Exception {
    // Get results of DISTINCTCOUNTHLL with log2m = 4,6,8 before building any star-tree indexes to compare results
    // later and ensure that the star-tree indexes are being built correctly.
    int distinctCountHllLog2m4 = getDistinctCountResult("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 4) FROM mytable " + "WHERE DistanceGroup > 1");
    int distinctCountHllLog2m6 = getDistinctCountResult("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 6) FROM mytable " + "WHERE DistanceGroup > 1");
    int distinctCountHllLog2m8 = getDistinctCountResult("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 8) FROM mytable " + "WHERE DistanceGroup > 1");
    // Ensure that the results are different
    assert distinctCountHllLog2m4 != distinctCountHllLog2m6;
    assert distinctCountHllLog2m6 != distinctCountHllLog2m8;
    assert distinctCountHllLog2m4 != distinctCountHllLog2m8;
    List<StarTreeIndexConfig> starTreeIndexConfigs = _tableConfig.getIndexingConfig().getStarTreeIndexConfigs();
    StarTreeAggregationConfig aggregationConfig = new StarTreeAggregationConfig("OriginAirportSeqID", "DISTINCTCOUNTHLL", Map.of(Constants.HLL_LOG2M_KEY, 4), null, null, null, null, null);
    starTreeIndexConfigs.add(new StarTreeIndexConfig(Collections.singletonList("DistanceGroup"), null, null, List.of(aggregationConfig), 1));
    updateTableConfig(_tableConfig);
    waitForTableConfigUpdate(tableConfig -> tableConfig.getIndexingConfig().getStarTreeIndexConfigs().size() == 1);
    reloadOfflineTable(DEFAULT_TABLE_NAME);
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 4) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m4);
    checkQueryDoesNotUseStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m8);
    checkQueryDoesNotUseStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 8) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m8);
    // Remove the star-tree index for DISTINCTCOUNTHLL with log2m = 4 and add new star-tree index with default log2m
    aggregationConfig = new StarTreeAggregationConfig("OriginAirportSeqID", "DISTINCTCOUNTHLL", null, null, null, null, null, null);
    starTreeIndexConfigs.remove(starTreeIndexConfigs.size() - 1);
    starTreeIndexConfigs.add(new StarTreeIndexConfig(Collections.singletonList("DistanceGroup"), null, null, List.of(aggregationConfig), 1));
    updateTableConfig(_tableConfig);
    waitForTableConfigUpdate(tableConfig -> tableConfig.getIndexingConfig().getStarTreeIndexConfigs().get(starTreeIndexConfigs.size() - 1).getAggregationConfigs().get(0).getFunctionParameters() == null);
    reloadOfflineTable(DEFAULT_TABLE_NAME);
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m8);
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 8) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m8);
    checkQueryDoesNotUseStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 4) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m4);
    // Add the star-tree index for DISTINCTCOUNTHLL with log2m = 4 again to ensure that two star-tree indexes can
    // be created for the same function / column pair with different configurations.
    aggregationConfig = new StarTreeAggregationConfig("OriginAirportSeqID", "DISTINCTCOUNTHLL", Map.of(Constants.HLL_LOG2M_KEY, "4"), null, null, null, null, null);
    starTreeIndexConfigs.add(new StarTreeIndexConfig(Collections.singletonList("DistanceGroup"), null, null, List.of(aggregationConfig), 1));
    updateTableConfig(_tableConfig);
    waitForTableConfigUpdate(tableConfig -> tableConfig.getIndexingConfig().getStarTreeIndexConfigs().size() == 2);
    reloadOfflineTable(DEFAULT_TABLE_NAME);
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 4) FROM mytable WHERE DistanceGroup > 1", distinctCountHllLog2m4);
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 8) FROM mytable WHERE DistanceGroup > 1", distinctCountHllLog2m8);
    // Update the previously added star-tree index to ensure that the star-tree index is rebuilt with new config
    // parameters
    aggregationConfig = new StarTreeAggregationConfig("OriginAirportSeqID", "DISTINCTCOUNTHLL", Map.of(Constants.HLL_LOG2M_KEY, "6"), null, null, null, null, null);
    starTreeIndexConfigs.remove(starTreeIndexConfigs.size() - 1);
    starTreeIndexConfigs.add(new StarTreeIndexConfig(Collections.singletonList("DistanceGroup"), null, null, List.of(aggregationConfig), 1));
    updateTableConfig(_tableConfig);
    waitForTableConfigUpdate(tableConfig -> tableConfig.getIndexingConfig().getStarTreeIndexConfigs().get(starTreeIndexConfigs.size() - 1).getAggregationConfigs().get(0).getFunctionParameters().get(Constants.HLL_LOG2M_KEY).equals("6"));
    reloadOfflineTable(DEFAULT_TABLE_NAME);
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 6) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m6);
    // Ensure that the previous star-tree index was removed
    checkQueryDoesNotUseStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID, 4) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m4);
    // Check that the other star-tree isn't affected
    checkQueryUsesStarTreeIndex("SELECT DISTINCTCOUNTHLL(OriginAirportSeqID) FROM mytable " + "WHERE DistanceGroup > 1", distinctCountHllLog2m8);
}

