@Test
public void testGetGivenSubtaskOrStateProgress() throws IOException {
    MinionEventObserver observer1 = MinionTestUtils.getMinionProgressObserver();
    observer1.notifyTaskStart(MinionTestUtils.getPinotTaskConfig("t01"));
    MinionEventObservers.getInstance().addMinionEventObserver("t01", observer1);
    MinionEventObserver observer2 = MinionTestUtils.getMinionProgressObserver();
    observer2.notifyTaskStart(MinionTestUtils.getPinotTaskConfig("t02"));
    observer2.notifyProgress(MinionTestUtils.getPinotTaskConfig("t02"), "");
    MinionEventObservers.getInstance().addMinionEventObserver("t02", observer2);
    MinionEventObserver observer3 = MinionTestUtils.getMinionProgressObserver();
    observer3.notifyTaskStart(MinionTestUtils.getPinotTaskConfig("t03"));
    observer3.notifyTaskSuccess(MinionTestUtils.getPinotTaskConfig("t03"), "");
    MinionEventObservers.getInstance().addMinionEventObserver("t03", observer3);
    PinotTaskProgressResource pinotTaskProgressResource = new PinotTaskProgressResource();
    // get all sub task progress
    String allSubTaskProgress = pinotTaskProgressResource.getSubtaskProgress(null, null);
    Map<String, Object> subtaskProgressMap = JsonUtils.stringToObject(allSubTaskProgress, Map.class);
    assertEquals(subtaskProgressMap.size(), 3);
    // get subtasks with given state
    String subtaskWithInProgressState = pinotTaskProgressResource.getSubtaskProgress(null, MinionTaskState.IN_PROGRESS.toString());
    assertInProgressSubtasks(subtaskWithInProgressState);
    String subtaskWithUndefinedState = pinotTaskProgressResource.getSubtaskProgress(null, "Undefined");
    assertInProgressSubtasks(subtaskWithUndefinedState);
    String subtaskWithSucceededState = pinotTaskProgressResource.getSubtaskProgress(null, MinionTaskState.SUCCEEDED.toString());
    subtaskProgressMap = JsonUtils.stringToObject(subtaskWithSucceededState, Map.class);
    assertEquals(subtaskProgressMap.size(), 1);
    String subtaskWithUnknownState = pinotTaskProgressResource.getSubtaskProgress(null, MinionTaskState.UNKNOWN.toString());
    assertNoSubtaskWithTheGivenState(subtaskWithUnknownState);
    String subtaskWithCancelledState = pinotTaskProgressResource.getSubtaskProgress(null, MinionTaskState.CANCELLED.toString());
    assertNoSubtaskWithTheGivenState(subtaskWithCancelledState);
    String subtaskWithErrorState = pinotTaskProgressResource.getSubtaskProgress(null, MinionTaskState.ERROR.toString());
    assertNoSubtaskWithTheGivenState(subtaskWithErrorState);
    // get subtasks with given name
    String subTasksWithGivenNamesProgress = pinotTaskProgressResource.getSubtaskProgress(" t01 , t02 ", null);
    assertInProgressSubtasks(subTasksWithGivenNamesProgress);
    // get subtasks with given names and state
    assertThrows(WebApplicationException.class, () -> pinotTaskProgressResource.getSubtaskProgress(" t01 , t02 ", MinionTaskState.IN_PROGRESS.toString()));
}

