@Test(dataProvider = "storageClasses")
public void testMoveFile(StorageClass storageClass, String scheme) throws Exception {
    _s3PinotFS.setStorageClass(storageClass);
    String sourceFilename = "source-file-" + System.currentTimeMillis();
    String targetFilename = "target-file-" + System.currentTimeMillis();
    int fileSize = 5000;
    File file = new File(TEMP_FILE, sourceFilename);
    try {
        createDummyFile(file, fileSize);
        URI sourceUri = URI.create(String.format(FILE_FORMAT, scheme, BUCKET, sourceFilename));
        _s3PinotFS.copyFromLocalFile(file, sourceUri);
        HeadObjectResponse sourceHeadObjectResponse = _s3Client.headObject(S3TestUtils.getHeadObjectRequest(BUCKET, sourceFilename));
        URI targetUri = URI.create(String.format(FILE_FORMAT, scheme, BUCKET, targetFilename));
        boolean moveResult = _s3PinotFS.move(sourceUri, targetUri, false);
        Assert.assertTrue(moveResult);
        Assert.assertFalse(_s3PinotFS.exists(sourceUri));
        Assert.assertTrue(_s3PinotFS.exists(targetUri));
        HeadObjectResponse targetHeadObjectResponse = _s3Client.headObject(S3TestUtils.getHeadObjectRequest(BUCKET, targetFilename));
        Assert.assertEquals(targetHeadObjectResponse.contentLength(), fileSize);
        Assert.assertEquals(targetHeadObjectResponse.storageClass(), sourceHeadObjectResponse.storageClass());
        Assert.assertEquals(targetHeadObjectResponse.archiveStatus(), sourceHeadObjectResponse.archiveStatus());
        Assert.assertEquals(targetHeadObjectResponse.contentType(), sourceHeadObjectResponse.contentType());
        Assert.assertEquals(targetHeadObjectResponse.expiresString(), sourceHeadObjectResponse.expiresString());
        Assert.assertEquals(targetHeadObjectResponse.eTag(), sourceHeadObjectResponse.eTag());
        Assert.assertEquals(targetHeadObjectResponse.replicationStatusAsString(), sourceHeadObjectResponse.replicationStatusAsString());
        // Last modified time might not be exactly the same, hence we give 5 seconds buffer.
        Assert.assertTrue(Math.abs(targetHeadObjectResponse.lastModified().getEpochSecond() - sourceHeadObjectResponse.lastModified().getEpochSecond()) < 5);
    } finally {
        FileUtils.deleteQuietly(file);
    }
}

