@Test
public void testCodeForComplexFieldExtractionRepeated() {
    MessageCodeGen messageCodeGen = new MessageCodeGen();
    // Repeated decoder method is non-empty
    Descriptors.FieldDescriptor fd = ComplexTypes.TestMessage.getDescriptor().findFieldByName(REPEATED_NESTED_MESSAGES);
    String fieldNameInCode = ProtobufInternalUtils.underScoreToCamelCase(fd.getName(), true);
    String javaType = ProtoBufUtils.getFullJavaName(fd.getMessageType());
    String expectedCode = "  List<Object> list2 = new ArrayList<>();
" + "  for (org.apache.pinot.plugin.inputformat.protobuf.ComplexTypes.TestMessage.NestedMessage " + "row: msg.getRepeatedNestedMessagesList()) {
" + "    list2.add(decodeNestedMessage(row));
" + "  }
" + "  if (!list2.isEmpty()) {
" + "    msgMap.put("repeated_nested_messages", list2.toArray());
" + "  }
";
    assertEquals(messageCodeGen.codeForComplexFieldExtraction(fd, fieldNameInCode, javaType, 1, 1, "decodeNestedMessage", "").toString(), expectedCode);
    assertEquals(messageCodeGen.codeForComplexFieldExtraction(fd, fieldNameInCode, javaType, 1, 1, "decodeNestedMessage", null).toString(), expectedCode);
    // Repeated both decoder methods and additional extractions present
    expectedCode = "  List<Object> list2 = new ArrayList<>();
" + "  for (org.apache.pinot.plugin.inputformat.protobuf.ComplexTypes.TestMessage.NestedMessage " + "row: msg.getRepeatedNestedMessagesList()) {
" + "    list2.add(decodeNestedMessage(row.toString()));
" + "  }
" + "  if (!list2.isEmpty()) {
" + "    msgMap.put("repeated_nested_messages", list2.toArray());
" + "  }
";
    assertEquals(messageCodeGen.codeForComplexFieldExtraction(fd, fieldNameInCode, javaType, 1, 1, "decodeNestedMessage", ".toString()").toString(), expectedCode);
    // Repeated decoder method is non empty
    fd = ComplexTypes.TestMessage.getDescriptor().findFieldByName(REPEATED_BYTES);
    fieldNameInCode = ProtobufInternalUtils.underScoreToCamelCase(fd.getName(), true);
    javaType = "String";
    expectedCode = "  List<Object> list2 = new ArrayList<>();
" + "  for (String row: msg.getRepeatedBytesList()) {
" + "    list2.add(row.name());
" + "  }
" + "  if (!list2.isEmpty()) {
" + "    msgMap.put("repeated_bytes", list2.toArray());
" + "  }
";
    assertEquals(messageCodeGen.codeForComplexFieldExtraction(fd, fieldNameInCode, javaType, 1, 1, "", ".name()").toString(), expectedCode);
    assertEquals(messageCodeGen.codeForComplexFieldExtraction(fd, fieldNameInCode, javaType, 1, 1, null, ".name()").toString(), expectedCode);
}

