public void testDimensionValueTransformer() {
    Map<String, String> taskConfig = new HashMap<>();
    taskConfig.put(MinionConstants.MergeRollupTask.ERASE_DIMENSION_VALUES_KEY, "svInt, svLong, svFloat, svDouble, svBoolean, svTimestamp, svJson, svBytes, mvInt, mvLong, mvFloat, mvDouble," + " mvString1, $virtual");
