    tableTaskConfigs.put("daily.maxNumRecordsPerSegment", "1000000");
    taskConfigsMap.put(MinionConstants.MergeRollupTask.TASK_TYPE, tableTaskConfigs);
    TableConfig offlineTableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTimeColumnName(TIME_COLUMN_NAME).setSegmentPartitionConfig(new SegmentPartitionConfig(Collections.singletonMap("memberId", new ColumnPartitionConfig("murmur", 10)))).setTaskConfig(new TableTaskConfig(taskConfigsMap)).build();
    String segmentName1 = "testTable__1";
    String segmentName2 = "testTable__2";
    String segmentName3 = "testTable__3";
    String segmentName4 = "testTable__4";
    SegmentZKMetadata metadata1 = getSegmentZKMetadata(segmentName1, 86_400_000L, 90_000_000L, TimeUnit.MILLISECONDS, null);
    metadata1.setPartitionMetadata(new SegmentPartitionMetadata(Collections.singletonMap("memberId", new ColumnPartitionMetadata("murmur", 10, Collections.singleton(0), null))));
    SegmentZKMetadata metadata2 = getSegmentZKMetadata(segmentName2, 86_400_000L, 100_000_000L, TimeUnit.MILLISECONDS, null);
    metadata2.setPartitionMetadata(new SegmentPartitionMetadata(Collections.singletonMap("memberId", new ColumnPartitionMetadata("murmur", 10, Collections.singleton(0), null))));
    SegmentZKMetadata metadata3 = getSegmentZKMetadata(segmentName3, 86_400_000L, 110_000_000L, TimeUnit.MILLISECONDS, null);
    metadata3.setPartitionMetadata(new SegmentPartitionMetadata(Collections.singletonMap("memberId", new ColumnPartitionMetadata("murmur", 10, Collections.singleton(1), null))));
    SegmentZKMetadata metadata4 = getSegmentZKMetadata(segmentName4, 90_000_000L, 110_000_000L, TimeUnit.MILLISECONDS, null);
    metadata4.setPartitionMetadata(new SegmentPartitionMetadata(Collections.singletonMap("memberId", new ColumnPartitionMetadata("murmur", 10, Collections.singleton(1), null))));
    ClusterInfoAccessor mockClusterInfoProvide = mock(ClusterInfoAccessor.class);
    when(mockClusterInfoProvide.getSegmentsZKMetadata(OFFLINE_TABLE_NAME)).thenReturn(Lists.newArrayList(metadata1, metadata2, metadata3, metadata4));
    when(mockClusterInfoProvide.getIdealState(OFFLINE_TABLE_NAME)).thenReturn(getIdealState(OFFLINE_TABLE_NAME, Lists.newArrayList(segmentName1, segmentName2, segmentName3, segmentName4)));
    MergeRollupTaskGenerator generator = new MergeRollupTaskGenerator();
    generator.init(mockClusterInfoProvide);
    List<PinotTaskConfig> pinotTaskConfigs = generator.generateTasks(Lists.newArrayList(offlineTableConfig));
    assertEquals(pinotTaskConfigs.size(), 2);
    String partitionedSegmentsGroup1 = segmentName1 + "," + segmentName2;
    String partitionedSegmentsGroup2 = segmentName3 + "," + segmentName4;
    boolean isPartitionedSegmentsGroup1Seen = false;
    boolean isPartitionedSegmentsGroup2Seen = false;
    for (PinotTaskConfig pinotTaskConfig : pinotTaskConfigs) {
        if (!isPartitionedSegmentsGroup1Seen) {
            isPartitionedSegmentsGroup1Seen = pinotTaskConfig.getConfigs().get(MinionConstants.SEGMENT_NAME_KEY).equals(partitionedSegmentsGroup1);
        }
        if (!isPartitionedSegmentsGroup2Seen) {
            isPartitionedSegmentsGroup2Seen = pinotTaskConfig.getConfigs().get(MinionConstants.SEGMENT_NAME_KEY).equals(partitionedSegmentsGroup2);
        }
        assertTrue(isPartitionedSegmentsGroup1Seen || isPartitionedSegmentsGroup2Seen);
        checkPinotTaskConfig(pinotTaskConfigs.get(0).getConfigs(), DAILY, "concat", "1d", null, "1000000");
    }
    assertTrue(isPartitionedSegmentsGroup1Seen && isPartitionedSegmentsGroup2Seen);
    // With numMaxRecordsPerTask constraints
    tableTaskConfigs.put("daily.maxNumRecordsPerTask", "5000000");
    metadata1.setTotalDocs(2000000L);
    metadata2.setTotalDocs(4000000L);
    metadata3.setTotalDocs(5000000L);
    metadata4.setTotalDocs(6000000L);
    pinotTaskConfigs = generator.generateTasks(Lists.newArrayList(offlineTableConfig));
    assertEquals(pinotTaskConfigs.size(), 3);
    isPartitionedSegmentsGroup1Seen = false;
    isPartitionedSegmentsGroup2Seen = false;
    boolean isPartitionedSegmentsGroup3Seen = false;
    for (PinotTaskConfig pinotTaskConfig : pinotTaskConfigs) {
        if (!isPartitionedSegmentsGroup1Seen) {
            isPartitionedSegmentsGroup1Seen = pinotTaskConfig.getConfigs().get(MinionConstants.SEGMENT_NAME_KEY).equals(partitionedSegmentsGroup1);
        }
        if (!isPartitionedSegmentsGroup2Seen) {
            isPartitionedSegmentsGroup2Seen = pinotTaskConfig.getConfigs().get(MinionConstants.SEGMENT_NAME_KEY).equals(segmentName3);
        }
        if (!isPartitionedSegmentsGroup3Seen) {
            isPartitionedSegmentsGroup3Seen = pinotTaskConfig.getConfigs().get(MinionConstants.SEGMENT_NAME_KEY).equals(segmentName4);
        }
        assertTrue(isPartitionedSegmentsGroup1Seen || isPartitionedSegmentsGroup2Seen || isPartitionedSegmentsGroup3Seen);
        checkPinotTaskConfig(pinotTaskConfigs.get(1).getConfigs(), DAILY, "concat", "1d", null, "1000000");
    }
    assertTrue(isPartitionedSegmentsGroup1Seen && isPartitionedSegmentsGroup2Seen && isPartitionedSegmentsGroup3Seen);
}

