    // Test when the configuration is set to false
    configs.put(TableTaskConfig.MINION_ALLOW_DOWNLOAD_FROM_SERVER, "false");
    tableTaskConfig = new TableTaskConfig(Collections.singletonMap(MinionConstants.MergeRollupTask.TASK_TYPE, configs));
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("sampleTable").setTaskConfig(tableTaskConfig).build();
    assertFalse(MinionTaskUtils.extractMinionAllowDownloadFromServer(tableConfig, MinionConstants.MergeRollupTask.TASK_TYPE, false));
}

@Test
public void testConvert() throws Exception {
    PurgeTaskExecutor purgeTaskExecutor = new PurgeTaskExecutor();
    purgeTaskExecutor.setMinionEventObserver(MinionTaskTestUtils.getMinionProgressObserver());
    PinotTaskConfig pinotTaskConfig = new PinotTaskConfig(MinionConstants.PurgeTask.TASK_TYPE, Collections.singletonMap(MinionConstants.TABLE_NAME_KEY, TableNameBuilder.OFFLINE.tableNameWithType(TABLE_NAME)));
    File purgedIndexDir = purgeTaskExecutor.convert(pinotTaskConfig, _originalIndexDir, PURGED_SEGMENT_DIR).getFile();
    try (PinotSegmentRecordReader pinotSegmentRecordReader = new PinotSegmentRecordReader(purgedIndexDir)) {
        int numRecordsRemaining = 0;
        int numRecordsModified = 0;
        GenericRow row = new GenericRow();
        while (pinotSegmentRecordReader.hasNext()) {
            row = pinotSegmentRecordReader.next(row);
            numRecordsRemaining++;
            if (row.getValue(D1).equals(Integer.MAX_VALUE)) {
                numRecordsModified++;
            }
        }
        Assert.assertEquals(numRecordsRemaining, NUM_ROWS - 1);
        Assert.assertEquals(numRecordsModified, NUM_ROWS - 1);
    }
}

