@Test
public void testRelDataTypeConversion() {
    TypeFactory typeFactory = new TypeFactory();
    Schema testSchema = new Schema.SchemaBuilder().addSingleValueDimension("INT_COL", FieldSpec.DataType.INT).addSingleValueDimension("LONG_COL", FieldSpec.DataType.LONG).addSingleValueDimension("FLOAT_COL", FieldSpec.DataType.FLOAT).addSingleValueDimension("DOUBLE_COL", FieldSpec.DataType.DOUBLE).addSingleValueDimension("STRING_COL", FieldSpec.DataType.STRING).addSingleValueDimension("BYTES_COL", FieldSpec.DataType.BYTES).addSingleValueDimension("JSON_COL", FieldSpec.DataType.JSON).addMultiValueDimension("INT_ARRAY_COL", FieldSpec.DataType.INT).addMultiValueDimension("LONG_ARRAY_COL", FieldSpec.DataType.LONG).addMultiValueDimension("FLOAT_ARRAY_COL", FieldSpec.DataType.FLOAT).addMultiValueDimension("DOUBLE_ARRAY_COL", FieldSpec.DataType.DOUBLE).addMultiValueDimension("STRING_ARRAY_COL", FieldSpec.DataType.STRING).addMultiValueDimension("BYTES_ARRAY_COL", FieldSpec.DataType.BYTES).build();
    RelDataType relDataTypeFromSchema = typeFactory.createRelDataTypeFromSchema(testSchema);
    List<RelDataTypeField> fieldList = relDataTypeFromSchema.getFieldList();
    for (RelDataTypeField field : fieldList) {
        switch(field.getName()) {
            case "INT_COL":
                BasicSqlType intBasicSqlType = new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.INTEGER);
                Assert.assertEquals(field.getType(), intBasicSqlType);
                checkPrecisionScale(field, intBasicSqlType);
                break;
            case "LONG_COL":
                BasicSqlType bigIntBasicSqlType = new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.BIGINT);
                Assert.assertEquals(field.getType(), bigIntBasicSqlType);
                checkPrecisionScale(field, bigIntBasicSqlType);
                break;
            case "FLOAT_COL":
                BasicSqlType realBasicSqlType = new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.REAL);
                Assert.assertEquals(field.getType(), realBasicSqlType);
                checkPrecisionScale(field, realBasicSqlType);
                break;
            case "DOUBLE_COL":
                BasicSqlType doubleBasicSqlType = new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.DOUBLE);
                Assert.assertEquals(field.getType(), doubleBasicSqlType);
                checkPrecisionScale(field, doubleBasicSqlType);
                break;
            case "STRING_COL":
            case "JSON_COL":
                Assert.assertEquals(field.getType(), TYPE_FACTORY.createTypeWithCharsetAndCollation(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.VARCHAR), StandardCharsets.UTF_8, SqlCollation.IMPLICIT));
                break;
            case "BYTES_COL":
                Assert.assertEquals(field.getType(), new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.VARBINARY));
                break;
            case "INT_ARRAY_COL":
                Assert.assertEquals(field.getType(), new ArraySqlType(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.INTEGER), false));
                break;
            case "LONG_ARRAY_COL":
                Assert.assertEquals(field.getType(), new ArraySqlType(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.BIGINT), false));
                break;
            case "FLOAT_ARRAY_COL":
                Assert.assertEquals(field.getType(), new ArraySqlType(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.REAL), false));
                break;
            case "DOUBLE_ARRAY_COL":
                Assert.assertEquals(field.getType(), new ArraySqlType(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.DOUBLE), false));
                break;
            case "STRING_ARRAY_COL":
                Assert.assertEquals(field.getType(), new ArraySqlType(TYPE_FACTORY.createTypeWithCharsetAndCollation(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.VARCHAR), StandardCharsets.UTF_8, SqlCollation.IMPLICIT), false));
                break;
            case "BYTES_ARRAY_COL":
                Assert.assertEquals(field.getType(), new ArraySqlType(new BasicSqlType(TypeSystem.INSTANCE, SqlTypeName.VARBINARY), false));
                break;
            default:
                Assert.fail("Unexpected column name: " + field.getName());
                break;
        }
    }
}

@Test
public void testLocalHappyPathSendFirst() throws Exception {
    String mailboxId = MailboxIdUtils.toMailboxId(_requestId++, SENDER_STAGE_ID, 0, RECEIVER_STAGE_ID, 0);
    // Sends are non-blocking as long as channel capacity is not breached
    SendingMailbox sendingMailbox = _mailboxService1.getSendingMailbox("localhost", _mailboxService1.getPort(), mailboxId, Long.MAX_VALUE, _stats);
    for (int i = 0; i < ReceivingMailbox.DEFAULT_MAX_PENDING_BLOCKS - 1; i++) {
        sendingMailbox.send(OperatorTestUtil.block(DATA_SCHEMA, new Object[] { i }));
    }
    sendingMailbox.send(SuccessMseBlock.INSTANCE, MultiStageQueryStats.emptyStats(SENDER_STAGE_ID).serialize());
    sendingMailbox.complete();
    ReceivingMailbox receivingMailbox = _mailboxService1.getReceivingMailbox(mailboxId);
    receivingMailbox.registeredReader(() -> {
    });
    for (int i = 0; i < ReceivingMailbox.DEFAULT_MAX_PENDING_BLOCKS - 1; i++) {
        assertEquals(receivingMailbox.getNumPendingBlocks(), ReceivingMailbox.DEFAULT_MAX_PENDING_BLOCKS - i);
        List<Object[]> rows = getRows(receivingMailbox);
        assertEquals(rows.size(), 1);
        assertEquals(rows.get(0), new Object[] { i });
    }
    assertEquals(receivingMailbox.getNumPendingBlocks(), 1);
    ReceivingMailbox.MseBlockWithStats block = receivingMailbox.poll();
    assertNotNull(block);
    assertTrue(block.getBlock().isSuccess());
    assertEquals(receivingMailbox.getNumPendingBlocks(), 0);
    assertNull(receivingMailbox.poll());
}

