@Test
public void testShouldThrowOnWindowFrameWithInvalidOffsetBounds() {
    // Given:
    DataSchema inputSchema = new DataSchema(new String[] { "group", "arg" }, new ColumnDataType[] { INT, STRING });
    MultiStageOperator input = new BlockListMultiStageOperator.Builder(inputSchema).addBlock(OperatorTestUtil.block(inputSchema, new Object[] { 2, "foo" })).buildWithEos();
    DataSchema resultSchema = new DataSchema(new String[] { "group", "arg", "sum" }, new ColumnDataType[] { INT, STRING, DOUBLE });
    List<Integer> keys = List.of(0);
    List<RexExpression.FunctionCall> aggCalls = List.of(getSum(new RexExpression.InputRef(1)));
    // Then:
    IllegalStateException e = Assert.expectThrows(IllegalStateException.class, () -> getOperator(inputSchema, resultSchema, keys, List.of(), aggCalls, ROWS, 5, 2, input));
    assertEquals(e.getMessage(), "Window frame lower bound can't be greater than upper bound");
    e = Assert.expectThrows(IllegalStateException.class, () -> getOperator(inputSchema, resultSchema, keys, List.of(), aggCalls, ROWS, -2, -3, input));
    assertEquals(e.getMessage(), "Window frame lower bound can't be greater than upper bound");
}

