@Test(dataProvider = "testDataWithSqlExecutionExceptions")
public void testSqlWithExceptionMsgChecker(String sql, String expectedError) {
    try {
        // query pinot
        ResultTable resultTable = queryRunner(sql, false).getResultTable();
        Assert.fail("Expected error with message '" + expectedError + "'. But instead rows were returned: " + JsonUtils.objectToPrettyString(resultTable));
    } catch (Exception e) {
        // NOTE: The actual message is (usually) something like:
        //   Received error query execution result block: {200=QueryExecutionError:
        //   Query execution error on: Server_localhost_12345
        //     java.lang.IllegalArgumentException: Illegal Json Path: $['path'] does not match document
        //   In some cases there is no prefix.
        String exceptionMessage = e.getMessage();
        boolean isFromQueryDispatcher = Pattern.compile("^Received \\d+ errors? from servers?.*", Pattern.MULTILINE).matcher(exceptionMessage).find();
        Assert.assertTrue(exceptionMessage.startsWith("Error occurred during stage submission") || exceptionMessage.equals(expectedError) || isFromQueryDispatcher, "Exception message didn't start with proper heading: " + exceptionMessage);
        Assert.assertTrue(exceptionMessage.contains(expectedError), "Exception should contain: " + expectedError + ", but found: " + exceptionMessage);
    }
}

