@Test
public void testCompileQueryContext() {
    final String planId = "id";
    final String tableName = "orderTable";
    final String timeColumn = "orderTime";
    final AggInfo aggInfo = new AggInfo("SUM", false, Collections.emptyMap());
    final String filterExpr = "cityName = 'Chicago'";
    PhysicalTimeSeriesServerPlanVisitor serverPlanVisitor = new PhysicalTimeSeriesServerPlanVisitor(mock(QueryExecutor.class), mock(ExecutorService.class), mock(ServerMetrics.class));
    // Case-1: Without offset, simple column based group-by expression, simple column based value, and non-empty filter.
    {
        TimeSeriesExecutionContext context = new TimeSeriesExecutionContext(LANGUAGE, TimeBuckets.ofSeconds(1000L, Duration.ofSeconds(10), 100), DUMMY_DEADLINE_MS, Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap());
        LeafTimeSeriesPlanNode leafNode = new LeafTimeSeriesPlanNode(planId, Collections.emptyList(), tableName, timeColumn, TimeUnit.SECONDS, 0L, filterExpr, "orderCount", aggInfo, Collections.singletonList("cityName"), SERIES_LIMIT, QUERY_OPTIONS);
        QueryContext queryContext = serverPlanVisitor.compileQueryContext(leafNode, context);
        assertEquals(queryContext.getFilter().toString(), "(cityName = 'Chicago' AND orderTime > '990' AND orderTime <= '1990')");
        assertTrue(isNumber(queryContext.getQueryOptions().get(QueryOptionKey.TIMEOUT_MS)));
        assertEquals(queryContext.getLimit(), SERIES_LIMIT);
    }
    // Case-2: With offset, complex group-by expression, complex value, non-empty filter, 0 limit, query options.
    {
        Map<String, String> queryOptions = ImmutableMap.of("numGroupsLimit", "1000");
        TimeSeriesExecutionContext context = new TimeSeriesExecutionContext(LANGUAGE, TimeBuckets.ofSeconds(1000L, Duration.ofSeconds(10), 100), DUMMY_DEADLINE_MS, Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap());
        LeafTimeSeriesPlanNode leafNode = new LeafTimeSeriesPlanNode(planId, Collections.emptyList(), tableName, timeColumn, TimeUnit.SECONDS, 10L, filterExpr, "orderCount*2", aggInfo, Collections.singletonList("concat(cityName, stateName, '-')"), 0, /* limit */
        queryOptions);
        QueryContext queryContext = serverPlanVisitor.compileQueryContext(leafNode, context);
        assertNotNull(queryContext);
        assertNotNull(queryContext.getGroupByExpressions());
        assertEquals("concat(cityName,stateName,'-')", queryContext.getGroupByExpressions().get(0).toString());
        assertNotNull(queryContext.getFilter());
        assertEquals(queryContext.getFilter().toString(), "(cityName = 'Chicago' AND orderTime > '980' AND orderTime <= '1980')");
        assertTrue(isNumber(queryContext.getQueryOptions().get(QueryOptionKey.TIMEOUT_MS)));
        assertEquals(queryContext.getLimit(), RangeTimeSeriesRequest.DEFAULT_SERIES_LIMIT);
        assertEquals(queryContext.getQueryOptions().get("numGroupsLimit"), "1000");
    }
}

@Test
public void testSerde() throws IOException {
    // To test serde of TimeSeriesBlock, we do the following:
    // 1. Serialize the time-series block (say Block-1) to get ByteString-1
    // 2. Deserialize ByteString-1 to get Block-2.
    // 3. Serialize Block-2 to get ByteString-2.
    // 4. Compare ByteString-1 and ByteString-2.
    // 5. Compare values of Block-1 and Block-2.
    List<TimeSeriesBlock> blocks = List.of(buildBlockWithNoTags(), buildBlockWithSingleTag(), buildBlockWithMultipleTags(), buildBlockWithByteValues());
    for (TimeSeriesBlock block1 : blocks) {
        // Serialize, deserialize and serialize again
        ByteString byteString1 = TimeSeriesBlockSerde.serializeTimeSeriesBlock(block1);
        String serializedBlockString1 = byteString1.toStringUtf8();
        TimeSeriesBlock block2 = TimeSeriesBlockSerde.deserializeTimeSeriesBlock(byteString1.asReadOnlyByteBuffer());
        String serializedBlockString2 = TimeSeriesBlockSerde.serializeTimeSeriesBlock(block2).toStringUtf8();
        // Serialized blocks in both cases should be the same since serialization is deterministic.
        assertEquals(serializedBlockString1, serializedBlockString2);
        // Compare block1 and block2
        compareBlocks(block1, block2);
    }
}

