@Test
public void overflowTest() throws Exception {
    int numArrays = 1024;
    int avgArrayLen = 32;
    try (MutableOffHeapByteArrayStore store = new MutableOffHeapByteArrayStore(_memoryManager, "stringColumn", numArrays, avgArrayLen)) {
        final int maxSize = MutableOffHeapByteArrayStore.getStartSize(numArrays, avgArrayLen) - 4;
        byte[] b1 = new byte[3];
        for (int i = 0; i < b1.length; i++) {
            b1[i] = (byte) i;
        }
        byte[] b2 = new byte[maxSize];
        for (int i = 0; i < b2.length; i++) {
            b2[i] = (byte) (i % Byte.MAX_VALUE);
        }
        // Add small array
        final int i1 = store.add(b1);
        Assert.assertTrue(Arrays.equals(store.get(i1), b1));
        // And now the larger one, should result in a new buffer
        final int i2 = store.add(b2);
        Assert.assertTrue(Arrays.equals(store.get(i2), b2));
        // And now one more, should result in a new buffer but exact fit.
        final int i3 = store.add(b2);
        Assert.assertTrue(Arrays.equals(store.get(i3), b2));
        // One more buffer when we add the small one again.
        final int i4 = store.add(b1);
        Assert.assertTrue(Arrays.equals(store.get(i4), b1));
        // Test with one more 'get' to ensure that things have not changed.
        Assert.assertTrue(Arrays.equals(store.get(i1), b1));
        Assert.assertTrue(Arrays.equals(store.get(i2), b2));
        Assert.assertTrue(Arrays.equals(store.get(i3), b2));
        Assert.assertTrue(Arrays.equals(store.get(i4), b1));
        byte[] b3 = new byte[5];
        for (int i = 0; i < b3.length; i++) {
            b3[i] = (byte) (i + 1);
        }
        int ix = -1;
        final int iters = 1_000_000;
        // Now add the small one multiple times causing many additions.
        for (int i = 0; i < iters; i++) {
            if (ix == -1) {
                ix = store.add(b3);
            }
            store.add(b3);
        }
        for (int i = 0; i < iters; i++) {
            Assert.assertTrue(Arrays.equals(store.get(ix++), b3));
        }
        // Original values should still be good.
        Assert.assertTrue(Arrays.equals(store.get(i1), b1));
        Assert.assertTrue(Arrays.equals(store.get(i2), b2));
        Assert.assertTrue(Arrays.equals(store.get(i3), b2));
        Assert.assertTrue(Arrays.equals(store.get(i4), b1));
    }
}

@Test(dataProvider = "params")
public void testPutStrings(ChunkCompressionType compressionType, int totalDocs, int numDocsPerChunk, int[] lengths, int version) throws IOException {
    String column = "testCol-" + UUID.randomUUID();
    File file = new File(OUTPUT_DIR, column + V1Constants.Indexes.RAW_SV_FORWARD_INDEX_FILE_EXTENSION);
    List<String[]> arrays = generateStringArrays(totalDocs, lengths, 50);
    int maxEntryLengthInBytes = arrays.stream().mapToInt(array -> Integer.BYTES + Arrays.stream(array).mapToInt(str -> Integer.BYTES + str.getBytes(UTF_8).length).sum()).max().orElse(0);
    try (VarByteChunkForwardIndexWriter writer = new VarByteChunkForwardIndexWriter(file, compressionType, totalDocs, numDocsPerChunk, maxEntryLengthInBytes, version)) {
        for (String[] array : arrays) {
            writer.putStringMV(array);
        }
    }
    try (PinotDataBuffer dataBuffer = PinotDataBuffer.loadBigEndianFile(file);
        VarByteChunkSVForwardIndexReader reader = new VarByteChunkSVForwardIndexReader(dataBuffer, DataType.STRING);
        ChunkReaderContext context = reader.createContext()) {
        for (int i = 0; i < arrays.size(); i++) {
            String[] array = arrays.get(i);
            byte[] bytes = reader.getBytes(i, context);
            ByteBuffer buffer = ByteBuffer.wrap(bytes);
            assertEquals(buffer.getInt(), array.length);
            int offset = Integer.BYTES * (array.length + 1);
            for (String value : array) {
                int length = buffer.getInt();
                assertEquals(length, value.length());
                assertEquals(new String(bytes, offset, length, UTF_8), value);
                offset += length;
            }
        }
    }
}

