// Test the realtime segment conversion of a table with an index that reuses mutable index artifacts during conversion
@Test(dataProvider = "reuseParams")
public void testSegmentBuilderWithReuse(boolean columnMajorSegmentBuilder, String sortedColumn, boolean reuseMutableIndex, int luceneNRTCachingDirectoryMaxBufferSizeMB, String rawValueForTextIndex, DictionaryIndexConfig dictionaryIndexConfig) throws Exception {
    File tmpDir = new File(TMP_DIR, "tmp_" + System.nanoTime());
    Map<String, String> fieldConfigColumnProperties = new HashMap<>();
    fieldConfigColumnProperties.put(FieldConfig.TEXT_INDEX_LUCENE_REUSE_MUTABLE_INDEX, String.valueOf(reuseMutableIndex));
    fieldConfigColumnProperties.put(FieldConfig.TEXT_INDEX_USE_AND_FOR_MULTI_TERM_QUERIES, "true");
    if (rawValueForTextIndex != null) {
        fieldConfigColumnProperties.put(FieldConfig.TEXT_INDEX_RAW_VALUE, rawValueForTextIndex);
    }
    FieldConfig textIndexFieldConfig = new FieldConfig.Builder(STRING_COLUMN1).withEncodingType(FieldConfig.EncodingType.RAW).withIndexTypes(Collections.singletonList(FieldConfig.IndexType.TEXT)).withProperties(fieldConfigColumnProperties).build();
    List<FieldConfig> fieldConfigList = Collections.singletonList(textIndexFieldConfig);
    TableConfig tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName("testTable").setTimeColumnName(DATE_TIME_COLUMN).setInvertedIndexColumns(Lists.newArrayList(LONG_COLUMN1)).setNoDictionaryColumns(Lists.newArrayList(STRING_COLUMN1)).setSortedColumn(sortedColumn).setColumnMajorSegmentBuilderEnabled(columnMajorSegmentBuilder).setFieldConfigList(fieldConfigList).build();
    Schema schema = new Schema.SchemaBuilder().addSingleValueDimension(STRING_COLUMN1, FieldSpec.DataType.STRING).addSingleValueDimension(LONG_COLUMN1, FieldSpec.DataType.LONG).addDateTime(DATE_TIME_COLUMN, FieldSpec.DataType.LONG, "1:MILLISECONDS:EPOCH", "1:MILLISECONDS").build();
    String tableNameWithType = tableConfig.getTableName();
    String segmentName = "testTable__0__0__123456";
    TextIndexConfig textIndexConfig = new TextIndexConfigBuilder().withUseANDForMultiTermQueries(false).withReuseMutableIndex(reuseMutableIndex).withLuceneNRTCachingDirectoryMaxBufferSizeMB(luceneNRTCachingDirectoryMaxBufferSizeMB).withRawValueForTextIndex(rawValueForTextIndex).build();
    RealtimeSegmentConfig.Builder realtimeSegmentConfigBuilder = new RealtimeSegmentConfig.Builder().setTableNameWithType(tableNameWithType).setSegmentName(segmentName).setStreamName(tableNameWithType).setSchema(schema).setTimeColumnName(DATE_TIME_COLUMN).setCapacity(1000).setIndex(Sets.newHashSet(LONG_COLUMN1), StandardIndexes.inverted(), IndexConfig.ENABLED).setIndex(Sets.newHashSet(STRING_COLUMN1), StandardIndexes.text(), textIndexConfig).setIndex(Sets.newHashSet(STRING_COLUMN1), StandardIndexes.dictionary(), dictionaryIndexConfig).setSegmentZKMetadata(getSegmentZKMetadata(segmentName)).setOffHeap(true).setMemoryManager(new DirectMemoryManager(segmentName)).setStatsHistory(RealtimeSegmentStatsHistory.deserialzeFrom(new File(tmpDir, "stats"))).setConsumerDir(new File(tmpDir, "consumerDir").getAbsolutePath());
    // create mutable segment impl
    RealtimeLuceneTextIndexSearcherPool.init(1);
    RealtimeLuceneIndexRefreshManager.init(1, 10);
    ImmutableSegmentImpl segmentFile = null;
    MutableSegmentImpl mutableSegmentImpl = new MutableSegmentImpl(realtimeSegmentConfigBuilder.build(), null);
    try {
        List<GenericRow> rows = generateTestDataForReusePath();
        for (GenericRow row : rows) {
            mutableSegmentImpl.index(row, null);
        }
        // build converted segment
        File outputDir = new File(new File(tmpDir, segmentName), "tmp-" + segmentName + "-" + System.currentTimeMillis());
        SegmentZKPropsConfig segmentZKPropsConfig = new SegmentZKPropsConfig();
        segmentZKPropsConfig.setStartOffset("1");
        segmentZKPropsConfig.setEndOffset("100");
        RealtimeSegmentConverter converter = new RealtimeSegmentConverter(mutableSegmentImpl, segmentZKPropsConfig, outputDir.getAbsolutePath(), schema, tableNameWithType, tableConfig, segmentName, false);
        converter.build(SegmentVersion.v3, null);
        File indexDir = new File(outputDir, segmentName);
        SegmentMetadataImpl segmentMetadata = new SegmentMetadataImpl(indexDir);
        assertEquals(segmentMetadata.getVersion(), SegmentVersion.v3);
        assertEquals(segmentMetadata.getTotalDocs(), rows.size());
        assertEquals(segmentMetadata.getTimeColumn(), DATE_TIME_COLUMN);
        assertEquals(segmentMetadata.getTimeUnit(), TimeUnit.MILLISECONDS);
        long expectedStartTime = (long) rows.get(0).getValue(DATE_TIME_COLUMN);
        assertEquals(segmentMetadata.getStartTime(), expectedStartTime);
        long expectedEndTime = (long) rows.get(rows.size() - 1).getValue(DATE_TIME_COLUMN);
        assertEquals(segmentMetadata.getEndTime(), expectedEndTime);
        assertTrue(segmentMetadata.getAllColumns().containsAll(schema.getColumnNames()));
        assertEquals(segmentMetadata.getStartOffset(), "1");
        assertEquals(segmentMetadata.getEndOffset(), "100");
        // read converted segment
        SegmentLocalFSDirectory segmentDir = new SegmentLocalFSDirectory(indexDir, segmentMetadata, ReadMode.mmap);
        SegmentDirectory.Reader segmentReader = segmentDir.createReader();
        Map<String, ColumnIndexContainer> indexContainerMap = new HashMap<>();
        Map<String, ColumnMetadata> columnMetadataMap = segmentMetadata.getColumnMetadataMap();
        IndexLoadingConfig indexLoadingConfig = new IndexLoadingConfig(null, tableConfig);
        for (Map.Entry<String, ColumnMetadata> entry : columnMetadataMap.entrySet()) {
            indexContainerMap.put(entry.getKey(), new PhysicalColumnIndexContainer(segmentReader, entry.getValue(), indexLoadingConfig));
        }
        segmentFile = new ImmutableSegmentImpl(segmentDir, segmentMetadata, indexContainerMap, null);
        // test forward index contents
        GenericRow readRow = new GenericRow();
        int docId = 0;
        for (int i = 0; i < rows.size(); i++) {
            GenericRow row;
            if (sortedColumn == null) {
                row = rows.get(i);
            } else {
                row = rows.get(rows.size() - i - 1);
            }
            segmentFile.getRecord(docId, readRow);
            // if rawValueForTextIndex is set and mutable index is reused, the forward index should return the dummy value
            if (rawValueForTextIndex != null && reuseMutableIndex) {
                assertEquals(readRow.getValue(STRING_COLUMN1), rawValueForTextIndex);
                assertEquals(readRow.getValue(DATE_TIME_COLUMN), row.getValue(DATE_TIME_COLUMN));
            } else {
                assertEquals(readRow.getValue(STRING_COLUMN1), row.getValue(STRING_COLUMN1));
                assertEquals(readRow.getValue(DATE_TIME_COLUMN), row.getValue(DATE_TIME_COLUMN));
            }
            docId += 1;
        }
        // test docId conversion
        TextIndexReader textIndexReader = segmentFile.getIndex(STRING_COLUMN1, StandardIndexes.text());
        if (sortedColumn == null) {
            assertEquals(textIndexReader.getDocIds("str-8"), ImmutableRoaringBitmap.bitmapOf(0));
            assertEquals(textIndexReader.getDocIds("str-4"), ImmutableRoaringBitmap.bitmapOf(4));
        } else {
            assertEquals(textIndexReader.getDocIds("str-8"), ImmutableRoaringBitmap.bitmapOf(7));
            assertEquals(textIndexReader.getDocIds("str-4"), ImmutableRoaringBitmap.bitmapOf(3));
        }
    } finally {
        mutableSegmentImpl.destroy();
        if (segmentFile != null) {
            segmentFile.destroy();
        }
    }
}

@Test
public void testElementLength() {
    int numElements = 10;
    String[] elements = new String[numElements];
    int minElementLength = Integer.MAX_VALUE;
    int maxElementLength = 0;
    for (int i = 0; i < numElements; i++) {
        String randomString = RandomStringUtils.random(100);
        elements[i] = randomString;
        int elementLength = randomString.getBytes(StandardCharsets.UTF_8).length;
        minElementLength = Math.min(minElementLength, elementLength);
        maxElementLength = Math.max(maxElementLength, elementLength);
    }
    DataSource dataSource = mock(DataSource.class);
    Dictionary dictionary = mock(Dictionary.class);
    when(dataSource.getDictionary()).thenReturn(dictionary);
    when(dictionary.getValueType()).thenReturn(DataType.STRING);
    when(dictionary.length()).thenReturn(numElements);
    when(dictionary.getStringValue(anyInt())).thenAnswer((Answer<String>) invocation -> elements[(int) invocation.getArgument(0)]);
    MutableColumnStatistics columnStatistics = new MutableColumnStatistics(dataSource, null);
    assertEquals(columnStatistics.getLengthOfShortestElement(), minElementLength);
    assertEquals(columnStatistics.getLengthOfLargestElement(), maxElementLength);
}

@Test
public void testMultiValueIndexingWithDictionary() {
    long seed = System.nanoTime();
    try (LongOnHeapMutableDictionary dict = new LongOnHeapMutableDictionary();
        DirectMemoryManager memManager = new DirectMemoryManager("test");
        FixedByteMVMutableForwardIndex indexer = new FixedByteMVMutableForwardIndex(MAX_N_VALUES, MAX_N_VALUES / 2, NROWS / 3, Integer.BYTES, memManager, "indexer", true, FieldSpec.DataType.INT)) {
        // Insert rows into the indexer and dictionary
        Random random = new Random(seed);
        for (int row = 0; row < NROWS; row++) {
            int numValues = Math.abs(random.nextInt()) % MAX_N_VALUES;
            Long[] values = new Long[numValues];
            for (int i = 0; i < numValues; i++) {
                values[i] = random.nextLong();
            }
            int[] dictIds = dict.index(values);
            assertEquals(dictIds.length, numValues);
            indexer.setDictIdMV(row, dictIds);
        }
        // Read back rows and make sure that the values are good.
        random = new Random(seed);
        int[] dictIds = new int[MAX_N_VALUES];
        for (int row = 0; row < NROWS; row++) {
            int numValues = indexer.getDictIdMV(row, dictIds);
            assertEquals(numValues, Math.abs(random.nextInt()) % MAX_N_VALUES);
            for (int i = 0; i < numValues; i++) {
                long value = dict.getLongValue(dictIds[i]);
                assertEquals(value, random.nextLong());
            }
        }
    } catch (Throwable t) {
        fail("Failed with random seed: " + seed, t);
    }
}

