@Test
public void testOrderForTransformers() {
    // This test checks that the specified order is maintained for different transformers.
    // Build Schema and ingestionConfig in such a way that all the transformers are loaded.
    Schema schema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", DataType.INT).addSingleValueDimension("svDouble", DataType.DOUBLE).addSingleValueDimension("expressionTestColumn", DataType.INT).addSingleValueDimension("svNaN", DataType.FLOAT).addMultiValueDimension("mvNaN", DataType.FLOAT).addSingleValueDimension("emptyDimensionForNullValueTransformer", DataType.FLOAT).addSingleValueDimension("svStringNull", DataType.STRING).addSingleValueDimension("indexableExtras", DataType.JSON).addDateTime("timeCol", DataType.TIMESTAMP, "1:MILLISECONDS:TIMESTAMP", "1:MILLISECONDS").build();
    IngestionConfig ingestionConfig = new IngestionConfig();
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTable").setIngestionConfig(ingestionConfig).setTimeColumnName("timeCol").build();
    ingestionConfig.setFilterConfig(new FilterConfig("svInt = 123 AND svDouble <= 200"));
    ingestionConfig.setTransformConfigs(List.of(new TransformConfig("expressionTestColumn", "plus(x,10)")));
    ingestionConfig.setSchemaConformingTransformerConfig(new SchemaConformingTransformerConfig(null, "indexableExtras", false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null));
    ingestionConfig.setRowTimeValueCheck(true);
    ingestionConfig.setContinueOnError(false);
    // Get the list of transformers.
    List<RecordTransformer> currentListOfTransformers = CompositeTransformer.getDefaultTransformers(tableConfig, schema);
    // Create a list of transformers in the original order to compare.
    List<RecordTransformer> expectedListOfTransformers = List.of(new ExpressionTransformer(tableConfig, schema), new FilterTransformer(tableConfig), new SchemaConformingTransformer(tableConfig, schema), new DataTypeTransformer(tableConfig, schema), new TimeValidationTransformer(tableConfig, schema), new SpecialValueTransformer(schema), new NullValueTransformer(tableConfig, schema), new SanitizationTransformer(schema));
    // Check that the number of current transformers match the expected number of transformers.
    assertEquals(currentListOfTransformers.size(), NUMBER_OF_TRANSFORMERS);
    GenericRow record = new GenericRow();
    // Data for expression Transformer.
    record.putValue("expressionTestColumn", 100);
    // Data for filter transformer.
    record.putValue("svDouble", 123d);
    // Data for DataType Transformer.
    record.putValue("svInt", (byte) 123);
    // Data for TimeValidation transformer.
    record.putValue("timeCol", System.currentTimeMillis());
    // Data for SpecialValue Transformer.
    record.putValue("svNaN", Float.NaN);
    record.putValue("mvNaN", new Float[] { 1.0f, Float.NaN, 2.0f });
    // Data for sanitization transformer.
    record.putValue("svStringNull", null);
    for (int i = 0; i < NUMBER_OF_TRANSFORMERS; i++) {
        GenericRow copyRecord = record.copy();
        GenericRow currentRecord = currentListOfTransformers.get(i).transform(record);
        GenericRow expectedRecord = expectedListOfTransformers.get(i).transform(copyRecord);
        assertEquals(currentRecord, expectedRecord);
        record = expectedRecord;
    }
}

