@Test
public void testDictionaryForMixedCardinalities() throws Exception {
    ImmutableSegment heapSegment = ImmutableSegmentLoader.load(_segmentDirectory, ReadMode.heap);
    try {
        Schema schema = heapSegment.getSegmentMetadata().getSchema();
        for (FieldSpec fieldSpec : schema.getAllFieldSpecs()) {
            // Skip virtual columns
            if (fieldSpec.isVirtualColumn()) {
                continue;
            }
            String columnName = fieldSpec.getName();
            if (columnName.contains("low_cardinality")) {
                Assert.assertTrue(heapSegment.getForwardIndex(columnName).isDictionaryEncoded(), "No dictionary found for low cardinality columns");
            }
            if (columnName.contains("high_cardinality")) {
                Assert.assertFalse(heapSegment.getForwardIndex(columnName).isDictionaryEncoded(), "No Raw index for high cardinality columns");
            }
            if (columnName.contains("key")) {
                Assert.assertFalse(heapSegment.getSegmentMetadata().getColumnMetadataFor(columnName).hasDictionary(), "Dictionary found for text index column");
            }
        }
    } finally {
        heapSegment.destroy();
    }
}

