@Test
public void testFixedBitMVForwardIndex() throws Exception {
    for (int numBitsPerValue = 1; numBitsPerValue <= 31; numBitsPerValue++) {
        // Generate random values
        int[][] valuesArray = new int[NUM_DOCS][];
        int totalNumValues = 0;
        int maxValue = numBitsPerValue != 31 ? 1 << numBitsPerValue : Integer.MAX_VALUE;
        for (int i = 0; i < NUM_DOCS; i++) {
            int numValues = RANDOM.nextInt(MAX_NUM_VALUES_PER_MV_ENTRY) + 1;
            int[] values = new int[numValues];
            for (int j = 0; j < numValues; j++) {
                values[j] = RANDOM.nextInt(maxValue);
            }
            valuesArray[i] = values;
            totalNumValues += numValues;
        }
        // Create the forward index
        try (FixedBitMVForwardIndexWriter writer = new FixedBitMVForwardIndexWriter(INDEX_FILE, NUM_DOCS, totalNumValues, numBitsPerValue)) {
            for (int[] values : valuesArray) {
                writer.putDictIds(values);
            }
        }
        // Read the forward index
        try (PinotDataBuffer dataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(INDEX_FILE);
            FixedBitMVForwardIndexReader reader = new FixedBitMVForwardIndexReader(dataBuffer, NUM_DOCS, totalNumValues, numBitsPerValue);
            FixedBitMVForwardIndexReader.Context readerContext = reader.createContext()) {
            int[] valueBuffer = new int[MAX_NUM_VALUES_PER_MV_ENTRY];
            for (int i = 0; i < NUM_DOCS; i++) {
                int numValues = reader.getDictIdMV(i, valueBuffer, readerContext);
                for (int j = 0; j < numValues; j++) {
                    assertEquals(valueBuffer[j], valuesArray[i][j]);
                }
            }
        }
        // Byte range test
        try (PinotDataBuffer dataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(INDEX_FILE);
            FixedBitMVForwardIndexReader reader = new FixedBitMVForwardIndexReader(dataBuffer, NUM_DOCS, totalNumValues, numBitsPerValue);
            FixedBitMVForwardIndexReader.Context readerContext = reader.createContext()) {
            Assert.assertTrue(reader.isBufferByteRangeInfoSupported());
            Assert.assertFalse(reader.isFixedOffsetMappingType());
            List<ForwardIndexReader.ByteRange> rangeList = new ArrayList<>();
            for (int i = 0; i < NUM_DOCS; i++) {
                try {
                    reader.recordDocIdByteRanges(i, readerContext, rangeList);
                } catch (Exception e) {
                    Assert.fail("Should not throw exception when calling recordDocIdByteRanges()", e);
                }
            }
        }
        FileUtils.forceDelete(INDEX_FILE);
    }
}

@Test
public void testFixedBitMVForwardIndex() throws Exception {
    for (int numBitsPerValue = 1; numBitsPerValue <= 31; numBitsPerValue++) {
        // Generate random values
        int[] valuesArray = new int[NUM_DOCS];
        int totalNumValues = 0;
        int maxValue = numBitsPerValue != 31 ? 1 << numBitsPerValue : Integer.MAX_VALUE;
        for (int i = 0; i < NUM_DOCS; i++) {
            valuesArray[i] = RANDOM.nextInt(maxValue);
        }
        // Create the forward index
        try (FixedBitSVForwardIndexWriter writer = new FixedBitSVForwardIndexWriter(INDEX_FILE, NUM_DOCS, numBitsPerValue)) {
            for (int value : valuesArray) {
                writer.putDictId(value);
            }
        }
        // Read the forward index
        try (PinotDataBuffer dataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(INDEX_FILE);
            FixedBitSVForwardIndexReader reader = new FixedBitSVForwardIndexReader(dataBuffer, NUM_DOCS, numBitsPerValue)) {
            for (int i = 0; i < NUM_DOCS; i++) {
                assertEquals(valuesArray[i], reader.getDictId(i, null));
            }
        }
        // Byte range test
        try (PinotDataBuffer dataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(INDEX_FILE);
            FixedBitSVForwardIndexReader reader = new FixedBitSVForwardIndexReader(dataBuffer, NUM_DOCS, numBitsPerValue)) {
            Assert.assertTrue(reader.isBufferByteRangeInfoSupported());
            Assert.assertTrue(reader.isFixedOffsetMappingType());
            Assert.assertEquals(reader.getRawDataStartOffset(), 0);
            Assert.assertEquals(reader.getDocLength(), numBitsPerValue);
            Assert.assertTrue(reader.isDocLengthInBits());
            try {
                reader.recordDocIdByteRanges(0, null, new ArrayList<>());
                Assert.fail("Should have failed to record byte ranges");
            } catch (UnsupportedOperationException e) {
                // expected
                Assert.assertEquals(e.getMessage(), "Forward index is fixed length type");
            }
        }
        FileUtils.forceDelete(INDEX_FILE);
    }
}

@Test(dataProvider = "combinations")
public void testInt(ChunkCompressionType compressionType, int version) throws Exception {
    int[] expected = new int[NUM_VALUES];
    for (int i = 0; i < NUM_VALUES; i++) {
        expected[i] = RANDOM.nextInt();
    }
    File outFileFourByte = new File(TEST_FILE);
    File outFileEightByte = new File(TEST_FILE + "8byte");
    FileUtils.deleteQuietly(outFileFourByte);
    FileUtils.deleteQuietly(outFileEightByte);
    // test both formats (4-byte chunk offsets and 8-byte chunk offsets)
    try (FixedByteChunkForwardIndexWriter fourByteOffsetWriter = new FixedByteChunkForwardIndexWriter(outFileFourByte, compressionType, NUM_VALUES, NUM_DOCS_PER_CHUNK, Integer.BYTES, version);
        FixedByteChunkForwardIndexWriter eightByteOffsetWriter = new FixedByteChunkForwardIndexWriter(outFileEightByte, compressionType, NUM_VALUES, NUM_DOCS_PER_CHUNK, Integer.BYTES, version)) {
        for (int value : expected) {
            fourByteOffsetWriter.putInt(value);
            eightByteOffsetWriter.putInt(value);
        }
    }
    try (PinotDataBuffer buffer1 = PinotDataBuffer.mapReadOnlyBigEndianFile(outFileFourByte);
        ForwardIndexReader<ChunkReaderContext> fourByteOffsetReader = version >= 4 ? new FixedBytePower2ChunkSVForwardIndexReader(buffer1, DataType.INT) : new FixedByteChunkSVForwardIndexReader(buffer1, DataType.INT);
        ChunkReaderContext fourByteOffsetReaderContext = fourByteOffsetReader.createContext();
        PinotDataBuffer buffer2 = PinotDataBuffer.mapReadOnlyBigEndianFile(outFileEightByte);
        ForwardIndexReader<ChunkReaderContext> eightByteOffsetReader = version >= 4 ? new FixedBytePower2ChunkSVForwardIndexReader(buffer2, DataType.INT) : new FixedByteChunkSVForwardIndexReader(buffer2, DataType.INT);
        ChunkReaderContext eightByteOffsetReaderContext = eightByteOffsetReader.createContext()) {
        for (int i = 0; i < NUM_VALUES; i++) {
            Assert.assertEquals(fourByteOffsetReader.getInt(i, fourByteOffsetReaderContext), expected[i]);
            Assert.assertEquals(eightByteOffsetReader.getInt(i, eightByteOffsetReaderContext), expected[i]);
        }
        Assert.assertTrue(fourByteOffsetReader.isBufferByteRangeInfoSupported());
        Assert.assertTrue(eightByteOffsetReader.isBufferByteRangeInfoSupported());
        // Validate byte range provider behaviour
        if (compressionType == ChunkCompressionType.PASS_THROUGH) {
            // For pass through compression, the buffer is fixed offset mapping type
            Assert.assertTrue(fourByteOffsetReader.isFixedOffsetMappingType());
            Assert.assertEquals(fourByteOffsetReader.getDocLength(), Integer.BYTES);
            Assert.assertFalse(fourByteOffsetReader.isDocLengthInBits());
            Assert.assertTrue(eightByteOffsetReader.isFixedOffsetMappingType());
            Assert.assertEquals(eightByteOffsetReader.getDocLength(), Integer.BYTES);
            Assert.assertFalse(eightByteOffsetReader.isDocLengthInBits());
        } else {
            Assert.assertFalse(eightByteOffsetReader.isFixedOffsetMappingType());
            Assert.assertFalse(eightByteOffsetReader.isFixedOffsetMappingType());
        }
    }
    FileUtils.deleteQuietly(outFileFourByte);
    FileUtils.deleteQuietly(outFileEightByte);
}

