        _fieldConfigMap.put(DIM_LZ4_STRING, new FieldConfig(DIM_LZ4_STRING, FieldConfig.EncodingType.RAW, List.of(FieldConfig.IndexType.TEXT), CompressionCodec.LZ4, null));
