        _invertedIndexColumns.add(DIM_DICT_STRING);
        _fieldConfigMap.put(DIM_DICT_LONG, new FieldConfig(DIM_DICT_LONG, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.INVERTED), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        _fieldConfigMap.put(DIM_DICT_STRING, new FieldConfig(DIM_DICT_STRING, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.INVERTED), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertEquals(computeOperations(), Map.of(DIM_DICT_LONG, List.of(ForwardIndexHandler.Operation.DISABLE_FORWARD_INDEX), DIM_DICT_STRING, List.of(ForwardIndexHandler.Operation.DISABLE_FORWARD_INDEX)));
        // TEST4: Disable forward index for two raw columns with forward index enabled and enable dictionary
        resetIndexConfigs();
        _noDictionaryColumns.remove(DIM_LZ4_LONG);
        _noDictionaryColumns.remove(DIM_SNAPPY_STRING);
        _invertedIndexColumns.add(DIM_LZ4_LONG);
        _invertedIndexColumns.add(DIM_SNAPPY_STRING);
        _fieldConfigMap.put(DIM_LZ4_LONG, new FieldConfig(DIM_LZ4_LONG, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.INVERTED), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        _fieldConfigMap.put(DIM_SNAPPY_STRING, new FieldConfig(DIM_SNAPPY_STRING, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.INVERTED), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
