        _fieldConfigMap.put(DIM_DICT_STRING, new FieldConfig(DIM_DICT_STRING, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.INVERTED), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertEquals(computeOperations(), Map.of(DIM_ZSTANDARD_INTEGER, List.of(ForwardIndexHandler.Operation.DISABLE_FORWARD_INDEX, ForwardIndexHandler.Operation.ENABLE_DICTIONARY), DIM_DICT_STRING, List.of(ForwardIndexHandler.Operation.DISABLE_FORWARD_INDEX)));
        // TEST6: Disable forward index for a raw column without enabling dictionary or inverted index
        resetIndexConfigs();
        _fieldConfigMap.put(DIM_LZ4_INTEGER, new FieldConfig(DIM_LZ4_INTEGER, FieldConfig.EncodingType.RAW, List.of(), CompressionCodec.LZ4, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertEquals(computeOperations(), Map.of(DIM_LZ4_INTEGER, List.of(ForwardIndexHandler.Operation.DISABLE_FORWARD_INDEX)));
        // TEST7: Disable forward index for a dictionary column and also disable dictionary and inverted index
        resetIndexConfigs();
        _noDictionaryColumns.add(DIM_DICT_LONG);
        _fieldConfigMap.put(DIM_DICT_LONG, new FieldConfig(DIM_DICT_LONG, FieldConfig.EncodingType.RAW, List.of(), CompressionCodec.LZ4, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertEquals(computeOperations(), Map.of(DIM_DICT_LONG, List.of(ForwardIndexHandler.Operation.DISABLE_FORWARD_INDEX, ForwardIndexHandler.Operation.DISABLE_DICTIONARY)));
        // TEST8: Disable dictionary on a column that already has forward index disabled
        resetIndexConfigs();
        _noDictionaryColumns.add(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER);
        _invertedIndexColumns.remove(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER);
        _fieldConfigMap.put(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, new FieldConfig(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, FieldConfig.EncodingType.RAW, List.of(), CompressionCodec.LZ4, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertEquals(computeOperations(), Map.of(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, List.of(ForwardIndexHandler.Operation.DISABLE_DICTIONARY)));
        // TEST9: Disable inverted index on a column that already has forward index disabled
        resetIndexConfigs();
        _invertedIndexColumns.remove(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER);
        _fieldConfigMap.put(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, new FieldConfig(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, FieldConfig.EncodingType.DICTIONARY, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertTrue(computeOperations().isEmpty());
        // TEST10: Disable dictionary on a column that already has forward index disabled and inverted index disabled
        resetIndexConfigs();
        _noDictionaryColumns.add(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITHOUT_INV_IDX);
        _fieldConfigMap.put(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITHOUT_INV_IDX, new FieldConfig(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITHOUT_INV_IDX, FieldConfig.EncodingType.RAW, List.of(), CompressionCodec.LZ4, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        assertEquals(computeOperations(), Map.of(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITHOUT_INV_IDX, List.of(ForwardIndexHandler.Operation.DISABLE_DICTIONARY)));
        // TEST11: Enable dictionary on a column that already has forward index disabled and dictionary disabled
        resetIndexConfigs();
        _noDictionaryColumns.remove(DIM_RAW_SV_FORWARD_INDEX_DISABLED_INTEGER);
        _fieldConfigMap.put(DIM_RAW_SV_FORWARD_INDEX_DISABLED_INTEGER, new FieldConfig(DIM_RAW_SV_FORWARD_INDEX_DISABLED_INTEGER, FieldConfig.EncodingType.DICTIONARY, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        try {
            computeOperations();
            fail("Enabling dictionary on forward index disabled column is not possible");
        } catch (IllegalStateException e) {
            assertEquals(e.getMessage(), "Cannot regenerate the dictionary for column: " + "DIM_RAW_SV_FORWARD_INDEX_DISABLED_INTEGER of segment: testSegment with forward index disabled. Please " + "refresh or back-fill the data to add back the forward index");
        }
        // TEST12: Disable dictionary on a column that already has forward index disabled without an inverted index but
        // with a range index
        resetIndexConfigs();
        _noDictionaryColumns.add(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITH_RANGE_INDEX);
        _fieldConfigMap.put(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITH_RANGE_INDEX, new FieldConfig(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITH_RANGE_INDEX, FieldConfig.EncodingType.RAW, List.of(FieldConfig.IndexType.RANGE), CompressionCodec.LZ4, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        try {
            computeOperations();
            fail("Disabling dictionary on forward index disabled column without inverted index but which has a " + "range index is not possible");
        } catch (IllegalStateException e) {
            assertEquals(e.getMessage(), "Must disable range index (enabled) to disable the dictionary for a " + "forwardIndexDisabled column: DIM_SV_FORWARD_INDEX_DISABLED_INTEGER_WITH_RANGE_INDEX of segment: " + "testSegment or refresh / back-fill the forward index");
        }
        // TEST13: Disable dictionary on a column that already has forward index disabled and inverted index enabled with
        // a range index
        resetIndexConfigs();
        _noDictionaryColumns.add(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER);
        _rangeIndexColumns.add(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER);
        _fieldConfigMap.put(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, new FieldConfig(DIM_SV_FORWARD_INDEX_DISABLED_INTEGER, FieldConfig.EncodingType.RAW, List.of(FieldConfig.IndexType.INVERTED, FieldConfig.IndexType.RANGE), CompressionCodec.LZ4, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
        try {
            computeOperations();
            fail("Disabling dictionary on forward index disabled column with inverted index and a range index " + "is not possible");
        } catch (IllegalStateException e) {
            assertEquals(e.getMessage(), "Must disable range index (enabled) to disable the dictionary for a " + "forwardIndexDisabled column: DIM_SV_FORWARD_INDEX_DISABLED_INTEGER of segment: testSegment or refresh " + "/ back-fill the forward index");
        }
    }
}

