        assertEquals(computeOperations(), Map.of(DIM_SV_FORWARD_INDEX_DISABLED_STRING, List.of(ForwardIndexHandler.Operation.ENABLE_FORWARD_INDEX), DIM_MV_FORWARD_INDEX_DISABLED_LONG, List.of(ForwardIndexHandler.Operation.ENABLE_FORWARD_INDEX)));
        // TEST6: Enable forward index in dictionary format and one in raw format for columns with forward index disabled
        resetIndexConfigs();
        _noDictionaryColumns.add(DIM_MV_FORWARD_INDEX_DISABLED_LONG);
        _invertedIndexColumns.remove(DIM_MV_FORWARD_INDEX_DISABLED_LONG);
        _fieldConfigMap.put(DIM_MV_FORWARD_INDEX_DISABLED_LONG, new FieldConfig(DIM_MV_FORWARD_INDEX_DISABLED_LONG, FieldConfig.EncodingType.RAW, List.of(), CompressionCodec.LZ4, null));
        _fieldConfigMap.remove(DIM_SV_FORWARD_INDEX_DISABLED_BYTES);
        assertEquals(computeOperations(), Map.of(DIM_MV_FORWARD_INDEX_DISABLED_LONG, List.of(ForwardIndexHandler.Operation.ENABLE_FORWARD_INDEX), DIM_SV_FORWARD_INDEX_DISABLED_BYTES, List.of(ForwardIndexHandler.Operation.ENABLE_FORWARD_INDEX)));
