@Test
public void testEnableDictAndOtherIndexesSV() throws Exception {
    // TEST 1: EXISTING_STRING_COL_RAW. Enable dictionary. Also add inverted index and text index. Reload code path
    // will create dictionary, inverted index and text index.
    buildV3Segment();
    _noDictionaryColumns.remove(EXISTING_STRING_COL_RAW);
    _invertedIndexColumns.add(EXISTING_STRING_COL_RAW);
    _fieldConfigMap.put(EXISTING_STRING_COL_RAW, new FieldConfig(EXISTING_STRING_COL_RAW, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.INVERTED, FieldConfig.IndexType.TEXT), null, null));
    checkForwardIndexCreation(EXISTING_STRING_COL_RAW, 5, 3, _schema, false, true, false, 4, null, true, 0, DataType.STRING, 100000);
    validateIndex(StandardIndexes.inverted(), EXISTING_STRING_COL_RAW, 5, 3, false, true, false, 4, true, 0, null, false, DataType.STRING, 100000);
    validateIndex(StandardIndexes.text(), EXISTING_STRING_COL_RAW, 5, 3, false, true, false, 4, true, 0, null, false, DataType.STRING, 100000);
    // TEST 2: EXISTING_STRING_COL_RAW. Enable dictionary on a raw column that already has text index.
    resetIndexConfigs();
    _fieldConfigMap.put(EXISTING_STRING_COL_RAW, new FieldConfig(EXISTING_STRING_COL_RAW, FieldConfig.EncodingType.RAW, List.of(FieldConfig.IndexType.TEXT), null, null));
    buildV3Segment();
    validateIndex(StandardIndexes.text(), EXISTING_STRING_COL_RAW, 5, 3, false, false, false, 0, true, 0, null, false, DataType.STRING, 100000);
    // At this point, the segment has text index. Now, the reload path should create a dictionary.
    _noDictionaryColumns.remove(EXISTING_STRING_COL_RAW);
    _fieldConfigMap.put(EXISTING_STRING_COL_RAW, new FieldConfig(EXISTING_STRING_COL_RAW, FieldConfig.EncodingType.DICTIONARY, List.of(FieldConfig.IndexType.TEXT), null, null));
    checkForwardIndexCreation(EXISTING_STRING_COL_RAW, 5, 3, _schema, false, true, false, 4, null, true, 0, DataType.STRING, 100000);
    validateIndex(StandardIndexes.text(), EXISTING_STRING_COL_RAW, 5, 3, false, true, false, 4, true, 0, null, false, DataType.STRING, 100000);
    // TEST 3: EXISTING_INT_COL_RAW. Enable dictionary on a column that already has range index.
    resetIndexConfigs();
    _rangeIndexColumns.add(EXISTING_INT_COL_RAW);
    buildV3Segment();
    validateIndex(StandardIndexes.range(), EXISTING_INT_COL_RAW, 42242, 16, false, false, false, 0, true, 0, ChunkCompressionType.LZ4, false, DataType.INT, 100000);
    long oldRangeIndexSize = new SegmentMetadataImpl(INDEX_DIR).getColumnMetadataFor(EXISTING_INT_COL_RAW).getIndexSizeMap().get(StandardIndexes.range());
    // At this point, the segment has range index. Now the reload path should create a dictionary and rewrite the
    // range index.
    _noDictionaryColumns.remove(EXISTING_INT_COL_RAW);
    checkForwardIndexCreation(EXISTING_INT_COL_RAW, 42242, 16, _schema, false, true, false, 0, null, true, 0, DataType.INT, 100000);
    validateIndex(StandardIndexes.range(), EXISTING_INT_COL_RAW, 42242, 16, false, true, false, 0, true, 0, null, false, DataType.INT, 100000);
    long newRangeIndexSize = new SegmentMetadataImpl(INDEX_DIR).getColumnMetadataFor(EXISTING_INT_COL_RAW).getIndexSizeMap().get(StandardIndexes.range());
    assertNotEquals(oldRangeIndexSize, newRangeIndexSize);
}

