@Test
public void testStarTreeCreationWithDictionaryChanges() throws Exception {
    // Build the sample segment
    String[] stringValues = { "A", "C", "B", "C", "D", "E", "E", "E" };
    long[] longValues = { 2, 1, 2, 3, 4, 5, 3, 2 };
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTable").build();
    Schema schema = new Schema.SchemaBuilder().addSingleValueDimension("stringCol", FieldSpec.DataType.STRING).addMetric("longCol", DataType.LONG).build();
    // Build good segment, no need for preprocess
    buildTestSegment(tableConfig, schema, stringValues, longValues);
    try (SegmentDirectory segmentDirectory = new SegmentLocalFSDirectory(INDEX_DIR, ReadMode.mmap);
        SegmentPreProcessor processor = new SegmentPreProcessor(segmentDirectory, new IndexLoadingConfig(tableConfig, schema), schema)) {
        assertFalse(processor.needProcess());
    }
    // Update table config to convert dict to noDict for longCol
    IndexingConfig indexingConfig = tableConfig.getIndexingConfig();
    indexingConfig.setNoDictionaryColumns(List.of("longCol"));
    try (SegmentDirectory segmentDirectory = new SegmentLocalFSDirectory(INDEX_DIR, ReadMode.mmap);
        SegmentPreProcessor processor = new SegmentPreProcessor(segmentDirectory, new IndexLoadingConfig(tableConfig, schema), schema)) {
        assertTrue(processor.needProcess());
        processor.process(SEGMENT_OPERATIONS_THROTTLER);
    }
    // Update table config to convert noDict to dict for longCol
    indexingConfig.setNoDictionaryColumns(null);
    try (SegmentDirectory segmentDirectory = new SegmentLocalFSDirectory(INDEX_DIR, ReadMode.mmap);
        SegmentPreProcessor processor = new SegmentPreProcessor(segmentDirectory, new IndexLoadingConfig(tableConfig, schema), schema)) {
        assertTrue(processor.needProcess());
        processor.process(SEGMENT_OPERATIONS_THROTTLER);
    }
    // Update table config to convert dict to noDict for longCol and add the Startree index config
    indexingConfig.setNoDictionaryColumns(List.of("longCol"));
    indexingConfig.setEnableDynamicStarTreeCreation(true);
    StarTreeIndexConfig starTreeIndexConfig = new StarTreeIndexConfig(List.of("stringCol"), null, List.of("SUM__longCol"), null, 1000);
    indexingConfig.setStarTreeIndexConfigs(List.of(starTreeIndexConfig));
    try (SegmentDirectory segmentDirectory = new SegmentLocalFSDirectory(INDEX_DIR, ReadMode.mmap);
        SegmentPreProcessor processor = new SegmentPreProcessor(segmentDirectory, new IndexLoadingConfig(tableConfig, schema), schema)) {
        assertTrue(processor.needProcess());
        processor.process(SEGMENT_OPERATIONS_THROTTLER);
    }
    // Remove Startree index but keep the no dictionary for longCol
    indexingConfig.setStarTreeIndexConfigs(null);
    try (SegmentDirectory segmentDirectory = new SegmentLocalFSDirectory(INDEX_DIR, ReadMode.mmap);
        SegmentPreProcessor processor = new SegmentPreProcessor(segmentDirectory, new IndexLoadingConfig(tableConfig, schema), schema)) {
        assertTrue(processor.needProcess());
        processor.process(SEGMENT_OPERATIONS_THROTTLER);
    }
    // Update table config to convert noDict to dict for longCol and also add the Startree index
    indexingConfig.setNoDictionaryColumns(null);
    indexingConfig.setStarTreeIndexConfigs(List.of(starTreeIndexConfig));
    try (SegmentDirectory segmentDirectory = new SegmentLocalFSDirectory(INDEX_DIR, ReadMode.mmap);
        SegmentPreProcessor processor = new SegmentPreProcessor(segmentDirectory, new IndexLoadingConfig(tableConfig, schema), schema)) {
        assertTrue(processor.needProcess());
        processor.process(SEGMENT_OPERATIONS_THROTTLER);
    }
}

/**
 * Test to check the behavior of the forward index disabled feature when enabled on a new SV column
 */
@Test(dataProvider = "bothV1AndV3")
public void testForwardIndexDisabledOnNewColumnsSV(SegmentVersion segmentVersion) throws Exception {
    // Add a new column with no forward index, but with inverted index
    buildSegment(segmentVersion);
    _invertedIndexColumns.add(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV);
    _fieldConfigMap.put(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, new FieldConfig(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, FieldConfig.EncodingType.DICTIONARY, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
    // Forward index is always going to be present for default SV columns with forward index disabled. This is because
    // such default columns are going to be sorted and the forwardIndexDisabled flag is a no-op for sorted columns
    createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, true, true, 4, true, 0, null, true, DataType.STRING, 100000);
    // Add a new raw column with no forward index
    resetIndexConfigs();
    buildSegment(segmentVersion);
    _noDictionaryColumns.add(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV);
    _fieldConfigMap.put(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, new FieldConfig(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, FieldConfig.EncodingType.RAW, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
    // Forward index is always going to be present for default SV columns with forward index disabled. This is because
    // such default columns are going to be sorted and the forwardIndexDisabled flag is a no-op for sorted columns
    // Even raw columns are created with dictionary and forward index
    createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, true, true, 4, true, 0, null, true, DataType.STRING, 100000);
    // Add a new column with no forward index or inverted index
    resetIndexConfigs();
    buildSegment(segmentVersion);
    _fieldConfigMap.put(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, new FieldConfig(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, FieldConfig.EncodingType.DICTIONARY, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
    // Disabling inverted index should be fine for disabling the forward index
    createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_SV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, true, true, 4, true, 0, null, true, DataType.STRING, 100000);
}

/**
 * Test to check the behavior of the forward index disabled feature when enabled on a new MV column
 */
@Test(dataProvider = "bothV1AndV3")
public void testForwardIndexDisabledOnNewColumnsMV(SegmentVersion segmentVersion) throws Exception {
    // Add a new column with no forward index, but with inverted index
    buildSegment(segmentVersion);
    _invertedIndexColumns.add(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV);
    _fieldConfigMap.put(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, new FieldConfig(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, FieldConfig.EncodingType.DICTIONARY, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
    createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, true, false, 4, false, 1, null, true, DataType.STRING, 100000);
    validateIndex(StandardIndexes.inverted(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, 1, 1, true, true, false, 4, false, 1, null, true, DataType.STRING, 100000);
    // Add a new raw column with no forward index
    resetIndexConfigs();
    buildSegment(segmentVersion);
    _noDictionaryColumns.add(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV);
    _fieldConfigMap.put(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, new FieldConfig(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, FieldConfig.EncodingType.RAW, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
    if (segmentVersion == SegmentVersion.v1) {
        // For V1 segments reload doesn't support modifying the forward index yet. Since for MV columns we create a
        // dictionary in the default column handler, the forward index should indeed be disabled but we should still have
        // the dictionary.
        createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, true, false, 4, false, 1, null, true, DataType.STRING, 100000);
        validateIndexExists(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, StandardIndexes.dictionary());
    } else {
        createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, false, false, 0, false, 1, null, true, DataType.STRING, 100000);
        validateIndexDoesNotExist(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, StandardIndexes.dictionary());
    }
    validateIndexDoesNotExist(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, StandardIndexes.inverted());
    // Add a new column with no forward index or inverted index
    resetIndexConfigs();
    buildSegment(segmentVersion);
    _fieldConfigMap.put(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, new FieldConfig(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, FieldConfig.EncodingType.DICTIONARY, List.of(), null, Map.of(FieldConfig.FORWARD_INDEX_DISABLED, "true")));
    createAndValidateIndex(StandardIndexes.forward(), NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, 1, 1, _newColumnsSchemaWithForwardIndexDisabled, true, true, false, 4, false, 1, null, true, DataType.STRING, 100000);
    validateIndexDoesNotExist(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, StandardIndexes.inverted());
    validateIndexExists(NEWLY_ADDED_FORWARD_INDEX_DISABLED_COL_MV, StandardIndexes.dictionary());
}

