@Test(dataProvider = "params")
public void testFixedByteValueReaderWriter(int maxStringLength, int configuredMaxLength, ByteOrder byteOrder) throws IOException {
    byte[] bytes = new byte[configuredMaxLength];
    try (PinotDataBuffer buffer = PinotDataBuffer.allocateDirect(configuredMaxLength * 1000L, byteOrder, "testFixedByteValueReaderWriter")) {
        FixedByteValueReaderWriter readerWriter = new FixedByteValueReaderWriter(buffer);
        List<String> inputs = new ArrayList<>(1000);
        for (int i = 0; i < 1000; i++) {
            int length = ThreadLocalRandom.current().nextInt(maxStringLength);
            Arrays.fill(bytes, 0, length, (byte) 'a');
            readerWriter.writeBytes(i, configuredMaxLength, bytes);
            inputs.add(new String(bytes, 0, length, StandardCharsets.UTF_8));
            Arrays.fill(bytes, 0, length, (byte) 0);
        }
        for (int i = 0; i < 1000; i++) {
            assertEquals(readerWriter.getUnpaddedString(i, configuredMaxLength, bytes), inputs.get(i));
        }
    }
}

@Test(dataProvider = "text")
public void testUtf8Comparison(TextTestCase testCase) throws IOException {
    String[] strings = testCase.generateStrings();
    int maxUtf8Length = Integer.MIN_VALUE;
    for (String string : strings) {
        maxUtf8Length = Math.max(string.getBytes(StandardCharsets.UTF_8).length, maxUtf8Length);
    }
    // round up to next power of 2
    int numBytesPerValue = (maxUtf8Length & -maxUtf8Length) == 0 ? maxUtf8Length : 1 << (32 - Integer.numberOfLeadingZeros(maxUtf8Length));
    Pair<ValueReader, PinotDataBuffer> readerAndBuffer = prepare(testCase.isFixed(), numBytesPerValue, testCase.getByteOrder(), strings);
    ValueReader reader = readerAndBuffer.getKey();
    try {
        testCase.testEqual(reader, numBytesPerValue, strings);
        testCase.testEmpty(reader, numBytesPerValue, strings);
        testCase.testCommonPrefixStoredLonger(reader, numBytesPerValue, strings);
        testCase.testCommonPrefixParameterLonger(reader, numBytesPerValue, strings);
        testCase.testCommonPrefixParameterOverflowing(reader, numBytesPerValue, strings);
        testCase.testInferiorPrefixes(reader, numBytesPerValue, strings);
        testCase.testSuperiorPrefixes(reader, numBytesPerValue, strings);
        testCase.testConsistent(reader, numBytesPerValue, strings.length);
    } finally {
        readerAndBuffer.getValue().close();
    }
}

