    indexMap.add(Pair.of(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dim1"), new StarTreeIndexMapUtils.IndexValue(2, 1)));
    indexMap.add(Pair.of(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "count__*"), new StarTreeIndexMapUtils.IndexValue(3, 1)));
    indexMaps.add(indexMap);
    indexMap = new ArrayList<>();
    indexMap.add(Pair.of(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.STAR_TREE, null), new StarTreeIndexMapUtils.IndexValue(10, 3)));
    indexMap.add(Pair.of(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dimX"), new StarTreeIndexMapUtils.IndexValue(13, 3)));
    indexMap.add(Pair.of(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dimY"), new StarTreeIndexMapUtils.IndexValue(16, 3)));
    indexMap.add(Pair.of(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "sum__dimX"), new StarTreeIndexMapUtils.IndexValue(19, 3)));
