@Test
public void testValidateDedupConfig() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).build();
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(TABLE_NAME).setDedupConfig(new DedupConfig()).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert/Dedup table is for realtime table only.");
    }
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setDedupConfig(new DedupConfig()).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert/Dedup table must have primary key columns in the schema");
    }
    schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).setPrimaryKeyColumns(Lists.newArrayList("myCol")).build();
    Map<String, String> streamConfigs = getStreamConfigs();
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setDedupConfig(new DedupConfig()).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert/Dedup table must use strict replica-group (i.e. strictReplicaGroup) based routing");
    }
    StarTreeIndexConfig starTreeIndexConfig = new StarTreeIndexConfig(Lists.newArrayList("myCol"), null, Collections.singletonList(new AggregationFunctionColumnPair(AggregationFunctionType.COUNT, "myCol").toColumnName()), null, 10);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setDedupConfig(new DedupConfig()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStarTreeIndexConfigs(Lists.newArrayList(starTreeIndexConfig)).setStreamConfigs(streamConfigs).build();
    TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
    // Dedup and upsert can't be enabled simultaneously
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setDedupConfig(new DedupConfig()).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertAndDedupConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "A table can have either Upsert or Dedup enabled, but not both");
    }
}

