@Test
public void testValidatePartialUpsertConfig() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol1", FieldSpec.DataType.LONG).addSingleValueDimension("myCol2", FieldSpec.DataType.STRING).addDateTime("myTimeCol", FieldSpec.DataType.LONG, "1:DAYS:EPOCH", "1:DAYS").setPrimaryKeyColumns(Lists.newArrayList("myCol1")).build();
    Map<String, String> streamConfigs = getStreamConfigs();
    Map<String, UpsertConfig.Strategy> partialUpsertStratgies = new HashMap<>();
    partialUpsertStratgies.put("myCol2", UpsertConfig.Strategy.IGNORE);
    UpsertConfig partialUpsertConfig = new UpsertConfig(UpsertConfig.Mode.PARTIAL);
    partialUpsertConfig.setPartialUpsertStrategies(partialUpsertStratgies);
    partialUpsertConfig.setDefaultPartialUpsertStrategy(UpsertConfig.Strategy.OVERWRITE);
    partialUpsertConfig.setComparisonColumn("myCol2");
    TableConfig tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(partialUpsertConfig).setNullHandlingEnabled(true).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Merger cannot be applied to comparison column");
    }
    partialUpsertConfig = new UpsertConfig(UpsertConfig.Mode.PARTIAL);
    partialUpsertConfig.setPartialUpsertStrategies(partialUpsertStratgies);
    partialUpsertConfig.setDefaultPartialUpsertStrategy(UpsertConfig.Strategy.OVERWRITE);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName("myCol2").setUpsertConfig(partialUpsertConfig).setNullHandlingEnabled(true).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Merger cannot be applied to time column");
    }
    partialUpsertStratgies.put("myCol1", UpsertConfig.Strategy.INCREMENT);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setTimeColumnName("timeCol").setUpsertConfig(partialUpsertConfig).setNullHandlingEnabled(true).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE, false)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Merger cannot be applied to primary key columns");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("randomCol", UpsertConfig.Strategy.OVERWRITE);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Merger cannot be applied to non-existing column: randomCol");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("myCol2", UpsertConfig.Strategy.INCREMENT);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "INCREMENT merger cannot be applied to non-numeric column: myCol2");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("myCol2", UpsertConfig.Strategy.APPEND);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "APPEND merger cannot be applied to single-value column: myCol2");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("myTimeCol", UpsertConfig.Strategy.INCREMENT);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "INCREMENT merger cannot be applied to date time column: myTimeCol");
    }
}

/**
 * Tests that the partial upsert config fails when the null handling is disabled.
 *
 * This means that both table config and schema nullability is turned off.
 */
@Test
public void partialUpsertConfigFailWhenNotNullableColumns() {
    try {
        testPartialUpsertConfigNullability((tableConfigBuilder, schemaBuilder) -> {
            tableConfigBuilder.setNullHandlingEnabled(false);
            schemaBuilder.setEnableColumnBasedNullHandling(false);
        });
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Null handling must be enabled for partial upsert tables");
    }
}

/**
 * Tests that the partial upsert config succeeds when table null handling is used.
 *
 * This means that schema nullability is turned off, but table null handling is turned on.
 */
@Test
public void partialUpsertConfigSuccessWhenUsingTableLevelNullability() {
    testPartialUpsertConfigNullability((tableConfigBuilder, schemaBuilder) -> {
        tableConfigBuilder.setNullHandlingEnabled(true);
        schemaBuilder.setEnableColumnBasedNullHandling(false);
    });
}

/**
 * Tests that the partial upsert config succeeds when column null handling is used.
 *
 * This means that schema nullability is turned on, but table null handling can be either true or false.
 */
@Test
public void partialUpsertConfigSuccessWhenUsingColumnLevelNullability() {
    testPartialUpsertConfigNullability((tableConfigBuilder, schemaBuilder) -> {
        tableConfigBuilder.setNullHandlingEnabled(false);
        schemaBuilder.setEnableColumnBasedNullHandling(true);
    });
    testPartialUpsertConfigNullability((tableConfigBuilder, schemaBuilder) -> {
        tableConfigBuilder.setNullHandlingEnabled(true);
        schemaBuilder.setEnableColumnBasedNullHandling(true);
    });
}

@Test
