@Test
public void testViewAndToDirectByteBuffer() throws Exception {
    int startOffset = RANDOM.nextInt(BUFFER_SIZE);
    ByteOrder nativeOrder = PinotDataBuffer.NATIVE_ORDER;
    ByteOrder nonNativeOrder = PinotDataBuffer.NON_NATIVE_ORDER;
    try (PinotDataBuffer writeBuffer = PinotByteBuffer.mapFile(TEMP_FILE, false, FILE_OFFSET, 3 * BUFFER_SIZE, nativeOrder)) {
        putLongs(writeBuffer, startOffset);
        try (PinotDataBuffer readBuffer = PinotByteBuffer.loadFile(TEMP_FILE, FILE_OFFSET, 3 * BUFFER_SIZE, nativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = PinotByteBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, 3 * BUFFER_SIZE, nativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = PinotByteBuffer.loadFile(TEMP_FILE, FILE_OFFSET, 3 * BUFFER_SIZE, nativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = PinotByteBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, 3 * BUFFER_SIZE, nativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
    } finally {
        FileUtils.forceDelete(TEMP_FILE);
    }
    try (PinotDataBuffer writeBuffer = PinotByteBuffer.mapFile(TEMP_FILE, false, FILE_OFFSET, 3 * BUFFER_SIZE, nonNativeOrder)) {
        putLongs(writeBuffer, startOffset);
        try (PinotDataBuffer readBuffer = PinotByteBuffer.loadFile(TEMP_FILE, FILE_OFFSET, 3 * BUFFER_SIZE, nonNativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = PinotByteBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, 3 * BUFFER_SIZE, nonNativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = _factory.readFile(TEMP_FILE, FILE_OFFSET, 3 * BUFFER_SIZE, nonNativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = _factory.mapFile(TEMP_FILE, true, FILE_OFFSET, 3 * BUFFER_SIZE, nonNativeOrder)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
    } finally {
        FileUtils.forceDelete(TEMP_FILE);
    }
}

@Test
public void testConstructors() throws Exception {
    testBufferStats(0, 0, 0, 0);
    if (prioritizeByteBuffer()) {
        try (RandomAccessFile randomAccessFile = new RandomAccessFile(TEMP_FILE, "rw")) {
            randomAccessFile.setLength(FILE_OFFSET + BUFFER_SIZE);
            try (PinotDataBuffer buffer1 = PinotDataBuffer.allocateDirect(BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER, null)) {
                Assert.assertTrue(buffer1 instanceof PinotByteBuffer);
                testBufferStats(1, BUFFER_SIZE, 0, 0);
                try (PinotDataBuffer buffer2 = PinotDataBuffer.loadFile(TEMP_FILE, FILE_OFFSET, BUFFER_SIZE, ByteOrder.BIG_ENDIAN, null)) {
                    Assert.assertTrue(buffer2 instanceof PinotByteBuffer);
                    testBufferStats(2, 2 * BUFFER_SIZE, 0, 0);
                    try (PinotDataBuffer buffer3 = PinotDataBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, BUFFER_SIZE, ByteOrder.BIG_ENDIAN, null)) {
                        Assert.assertTrue(buffer3 instanceof PinotByteBuffer);
                        testBufferStats(2, 2 * BUFFER_SIZE, 1, BUFFER_SIZE);
                    }
                    testBufferStats(2, 2 * BUFFER_SIZE, 0, 0);
                }
                testBufferStats(1, BUFFER_SIZE, 0, 0);
            }
            testBufferStats(0, 0, 0, 0);
        } finally {
            FileUtils.forceDelete(TEMP_FILE);
        }
    }
    try (RandomAccessFile randomAccessFile = new RandomAccessFile(TEMP_FILE, "rw")) {
        randomAccessFile.setLength(FILE_OFFSET + LARGE_BUFFER_SIZE);
        try (PinotDataBuffer buffer1 = PinotDataBuffer.allocateDirect(LARGE_BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER, null)) {
            Assert.assertSame(buffer1.order(), PinotDataBuffer.NATIVE_ORDER);
            testBufferStats(1, LARGE_BUFFER_SIZE, 0, 0);
            try (PinotDataBuffer buffer2 = PinotDataBuffer.loadFile(TEMP_FILE, FILE_OFFSET, LARGE_BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER, null)) {
                Assert.assertSame(buffer2.order(), PinotDataBuffer.NATIVE_ORDER);
                testBufferStats(2, 2 * LARGE_BUFFER_SIZE, 0, 0);
                try (PinotDataBuffer buffer3 = PinotDataBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, LARGE_BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER, null)) {
                    Assert.assertSame(buffer3.order(), PinotDataBuffer.NATIVE_ORDER);
                    testBufferStats(2, 2 * LARGE_BUFFER_SIZE, 1, LARGE_BUFFER_SIZE);
                }
                testBufferStats(2, 2 * LARGE_BUFFER_SIZE, 0, 0);
            }
            testBufferStats(1, LARGE_BUFFER_SIZE, 0, 0);
        }
        testBufferStats(0, 0, 0, 0);
    } finally {
        FileUtils.forceDelete(TEMP_FILE);
    }
    try (RandomAccessFile randomAccessFile = new RandomAccessFile(TEMP_FILE, "rw")) {
        randomAccessFile.setLength(FILE_OFFSET + LARGE_BUFFER_SIZE);
        try (PinotDataBuffer buffer1 = PinotDataBuffer.allocateDirect(LARGE_BUFFER_SIZE, PinotDataBuffer.NON_NATIVE_ORDER, null)) {
            Assert.assertSame(buffer1.order(), PinotDataBuffer.NON_NATIVE_ORDER);
            testBufferStats(1, LARGE_BUFFER_SIZE, 0, 0);
            try (PinotDataBuffer buffer2 = PinotDataBuffer.loadFile(TEMP_FILE, FILE_OFFSET, LARGE_BUFFER_SIZE, PinotDataBuffer.NON_NATIVE_ORDER, null)) {
                Assert.assertSame(buffer2.order(), PinotDataBuffer.NON_NATIVE_ORDER);
