@Test
public void checkHealthProbes() {
    String healthPath = "/health";
    String livenessPath = "/health/liveness";
    String readinessPath = "/health/readiness";
    ServiceStatus.ServiceStatusCallback mockSuccessCallback = mock(ServiceStatus.ServiceStatusCallback.class);
    ServiceStatus.ServiceStatusCallback mockFailureCallback = mock(ServiceStatus.ServiceStatusCallback.class);
    when(mockSuccessCallback.getServiceStatus()).thenReturn(ServiceStatus.Status.GOOD);
    when(mockFailureCallback.getServiceStatus()).thenReturn(ServiceStatus.Status.BAD);
    assertEquals(_webTarget.path(livenessPath).request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "liveness").request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).request().get(Response.class).getStatus(), 503);
    assertEquals(_webTarget.path(readinessPath).request().get(Response.class).getStatus(), 503);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "readiness").request().get(Response.class).getStatus(), 503);
    ServiceStatus.setServiceStatusCallback(_instanceId, mockSuccessCallback);
    assertEquals(_webTarget.path(livenessPath).request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "liveness").request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(readinessPath).request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "readiness").request().get(Response.class).getStatus(), 200);
    ServiceStatus.setServiceStatusCallback(_instanceId, mockFailureCallback);
    assertEquals(_webTarget.path(livenessPath).request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "liveness").request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).request().get(Response.class).getStatus(), 503);
    assertEquals(_webTarget.path(readinessPath).request().get(Response.class).getStatus(), 503);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "readiness").request().get(Response.class).getStatus(), 503);
    // Start shutting down the HTTP server, only liveness check should go through
    ServiceStatus.setServiceStatusCallback(_instanceId, mockSuccessCallback);
    _adminApiApplication.startShuttingDown();
    assertEquals(_webTarget.path(livenessPath).request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "liveness").request().get(Response.class).getStatus(), 200);
    assertEquals(_webTarget.path(healthPath).request().get(Response.class).getStatus(), 503);
    assertEquals(_webTarget.path(readinessPath).request().get(Response.class).getStatus(), 503);
    assertEquals(_webTarget.path(healthPath).queryParam("checkType", "readiness").request().get(Response.class).getStatus(), 503);
}

/**
 * Asserts that application configs returned by the server endpoint are as expected.
 *
 * @throws JsonProcessingException In case an exception is encountered during JSON processing.
 */
@Test
public void testAppConfigs() throws JsonProcessingException, SocketException, UnknownHostException {
    PinotConfiguration expectedServerConf = new PinotConfiguration();
    String hostname = expectedServerConf.getProperty(CommonConstants.Helix.KEY_OF_SERVER_NETTY_HOST, expectedServerConf.getProperty(CommonConstants.Helix.SET_INSTANCE_ID_TO_HOSTNAME_KEY, false) ? NetUtils.getHostnameOrAddress() : NetUtils.getHostAddress());
    int port = expectedServerConf.getProperty(CommonConstants.Helix.KEY_OF_SERVER_NETTY_PORT, CommonConstants.Helix.DEFAULT_SERVER_NETTY_PORT);
    expectedServerConf.setProperty(CommonConstants.Server.CONFIG_OF_INSTANCE_ID, CommonConstants.Helix.PREFIX_OF_SERVER_INSTANCE + hostname + "_" + port);
    PinotAppConfigs expected = new PinotAppConfigs(expectedServerConf);
    Response response = _webTarget.path("/appconfigs").request().get(Response.class);
    String configsJson = response.readEntity(String.class);
    PinotAppConfigs actual = JsonUtils.stringToObject(configsJson, PinotAppConfigs.class);
    // RuntimeConfig is not checked as it has information that can change during the test run.
    // Also, some of the system configs can change, so compare the ones that don't.
    PinotAppConfigs.SystemConfig actualSystemConfig = actual.getSystemConfig();
    PinotAppConfigs.SystemConfig expectedSystemConfig = expected.getSystemConfig();
    Assert.assertEquals(actualSystemConfig.getName(), expectedSystemConfig.getName());
    Assert.assertEquals(actualSystemConfig.getVersion(), expectedSystemConfig.getVersion());
    Assert.assertEquals(actualSystemConfig.getAvailableProcessors(), expectedSystemConfig.getAvailableProcessors());
    Assert.assertEquals(actualSystemConfig.getTotalPhysicalMemory(), expectedSystemConfig.getTotalPhysicalMemory());
    Assert.assertEquals(actualSystemConfig.getTotalSwapSpace(), expectedSystemConfig.getTotalSwapSpace());
    // tests Equals on obfuscated expected and actual
    Obfuscator obfuscator = new Obfuscator();
    String obfuscatedExpectedJson = obfuscator.toJsonString(expected);
    PinotAppConfigs obfuscatedExpected = JsonUtils.stringToObject(obfuscatedExpectedJson, PinotAppConfigs.class);
    Assert.assertEquals(actual.getJvmConfig(), obfuscatedExpected.getJvmConfig());
    Assert.assertEquals(actual.getPinotConfig(), obfuscatedExpected.getPinotConfig());
}

