@Test
public void testValidateFormat() {
    DateTimeFormatPatternSpec dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyy-MM-dd");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyy-MM-dd");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.UTC);
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyy-MM-dd", null));
    dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd tz(CST)");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyyMMdd");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.forTimeZone(TimeZone.getTimeZone("CST")));
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd", "CST"));
    dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd HH tz(GMT+0700)");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyyMMdd HH");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.forTimeZone(TimeZone.getTimeZone("GMT+0700")));
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd HH", "GMT+0700"));
    dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMddHH tz(America/Chicago)");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyyMMddHH");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.forTimeZone(TimeZone.getTimeZone("America/Chicago")));
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMddHH", "America/Chicago"));
    // Unknown time zone is treated as UTC
    dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd tz(CSEMT)");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyyMMdd");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.UTC);
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd", "CSEMT"));
    dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd tz(GMT+5000)");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyyMMdd");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.UTC);
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd", "GMT+5000"));
    dateTimeFormatPatternSpec = new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd tz(HAHA/Chicago)");
    assertEquals(dateTimeFormatPatternSpec.getSdfPattern(), "yyyyMMdd");
    assertEquals(dateTimeFormatPatternSpec.getDateTimeZone(), DateTimeZone.UTC);
    assertEquals(dateTimeFormatPatternSpec, new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyyMMdd", "HAHA/Chicago"));
    // Invalid pattern
    assertThrows(IllegalArgumentException.class, () -> new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyc-MM-dd"));
    assertThrows(IllegalArgumentException.class, () -> new DateTimeFormatPatternSpec(TimeFormat.SIMPLE_DATE_FORMAT, "yyyy-MM-dd ff(a)"));
}

