    String json;
    if (declared == null) {
        json = "{\"name\": \"col1\", \"dataType\":\"BOOLEAN\"}";
    } else {
        json = "{\"name\": \"col1\", \"dataType\":\"BOOLEAN\", \"notNull\": " + declared + "}";
    }
    DimensionFieldSpec fieldSpec = JsonUtils.stringToObject(json, DimensionFieldSpec.class);
