public void testStringToBooleanSchemaBackwardCompatibility() {
    Schema oldSchema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", FieldSpec.DataType.INT).addSingleValueDimension("svString", FieldSpec.DataType.STRING).addSingleValueDimension("svStringWithDefault", FieldSpec.DataType.STRING, "false").build();
    // INT to BOOLEAN - incompatible
    Schema newSchema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", FieldSpec.DataType.BOOLEAN).addSingleValueDimension("svString", FieldSpec.DataType.STRING).addSingleValueDimension("svStringWithDefault", FieldSpec.DataType.STRING, "false").build();
    newSchema.updateBooleanFieldsIfNeeded(oldSchema);
    Assert.assertFalse(newSchema.isBackwardCompatibleWith(oldSchema));
    // STRING to BOOLEAN - compatible
    newSchema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", FieldSpec.DataType.INT).addSingleValueDimension("svString", FieldSpec.DataType.BOOLEAN).addSingleValueDimension("svStringWithDefault", FieldSpec.DataType.STRING, "false").build();
    newSchema.updateBooleanFieldsIfNeeded(oldSchema);
    Assert.assertTrue(newSchema.isBackwardCompatibleWith(oldSchema));
    Assert.assertEquals(newSchema, oldSchema);
    // STRING with default to BOOLEAN with default - compatible
    newSchema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", FieldSpec.DataType.INT).addSingleValueDimension("svString", FieldSpec.DataType.STRING).addSingleValueDimension("svStringWithDefault", FieldSpec.DataType.BOOLEAN, "false").build();
    newSchema.updateBooleanFieldsIfNeeded(oldSchema);
    Assert.assertTrue(newSchema.isBackwardCompatibleWith(oldSchema));
    Assert.assertEquals(newSchema, oldSchema);
    // STRING with default to BOOLEAN without default - backward compatible change
    newSchema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", FieldSpec.DataType.INT).addSingleValueDimension("svString", FieldSpec.DataType.STRING).addSingleValueDimension("svStringWithDefault", FieldSpec.DataType.BOOLEAN).build();
    newSchema.updateBooleanFieldsIfNeeded(oldSchema);
    Assert.assertTrue(newSchema.isBackwardCompatibleWith(oldSchema));
    // New added BOOLEAN - compatible
    newSchema = new Schema.SchemaBuilder().addSingleValueDimension("svInt", FieldSpec.DataType.INT).addSingleValueDimension("svString", FieldSpec.DataType.STRING).addSingleValueDimension("svStringWithDefault", FieldSpec.DataType.STRING, "false").addSingleValueDimension("svBoolean", FieldSpec.DataType.BOOLEAN).addSingleValueDimension("svBooleanWithDefault", FieldSpec.DataType.BOOLEAN, true).build();
    newSchema.updateBooleanFieldsIfNeeded(oldSchema);
    Assert.assertTrue(newSchema.isBackwardCompatibleWith(oldSchema));
    Assert.assertEquals(newSchema.getFieldSpecFor("svBoolean").getDataType(), FieldSpec.DataType.BOOLEAN);
    Assert.assertEquals(newSchema.getFieldSpecFor("svBooleanWithDefault").getDataType(), FieldSpec.DataType.BOOLEAN);
}

@Test
public void testWithoutVirtualColumns() {
    DimensionFieldSpec virtualField = new DimensionFieldSpec(CommonConstants.Segment.BuiltInVirtualColumn.DOCID, FieldSpec.DataType.INT, true, Integer.class);
    Schema schema = new Schema.SchemaBuilder().setSchemaName("testSchema").setEnableColumnBasedNullHandling(true).addMetricField("metric", FieldSpec.DataType.INT).addField(virtualField).setPrimaryKeyColumns(Lists.newArrayList("metric")).build();
    Schema withoutVirtualColumns = schema.withoutVirtualColumns();
    Assert.assertTrue(withoutVirtualColumns.getAllFieldSpecs().stream().noneMatch(field -> field.getName().equals(CommonConstants.Segment.BuiltInVirtualColumn.DOCID)), "Virtual column " + CommonConstants.Segment.BuiltInVirtualColumn.DOCID + " should be removed");
    Assert.assertEquals(withoutVirtualColumns.getPrimaryKeyColumns(), schema.getPrimaryKeyColumns(), "Primary key columns should be equal");
    Assert.assertNotSame(withoutVirtualColumns.getPrimaryKeyColumns(), schema.getPrimaryKeyColumns(), "Primary key columns should not be the same object");
    withoutVirtualColumns.addField(virtualField);
    Assert.assertEquals(withoutVirtualColumns, schema, "After adding the virtual field both schemas should be equal");
}

