// pinot-dropwizard is a limited plugin, meaning it cannot access every class from the pinot realm
@Test
public void limitedPluginRealm() throws Exception {
    String pluginName = "pinot-dropwizard";
    // Create fresh pluginManager, so it can pick up the system property for the pluginDirectory
    PluginManager pluginManager = new PluginManager();
    // make sure pinot-dropwizard-0.10.0-shaded.jar has been downloaded
    assertTrue(Files.exists(PLUGINS_DIRECTORY.resolve(pluginName + "/pinot-dropwizard-0.10.0-shaded.jar")), "Plugin not found. Run 'mvn -f pinot-spi/pom.xml generate-test-resources' once to prepare this artifact");
    assertNotNull(pluginManager.loadClass(pluginName, DROPWIZARD_METRICS_REGISTRY), "Expected o.a.p.p.m.d.DropwizardMetricsRegistry to be available");
    assertNotNull(pluginManager.createInstance(pluginName, DROPWIZARD_METRICS_REGISTRY), "Expected to be able to create instance of o.a.p.p.m.d.DropwizardMetricsRegistry");
    assertNotNull(pluginManager.loadClass(pluginName, SPI_TIME_UTILS), "Expected o.a.p.spi.utils.TimeUtils to be available via dropwizard-realm");
    assertEquals(pluginManager.loadClass(pluginName, SPI_TIME_UTILS).getProtectionDomain().getCodeSource().getLocation(), Path.of("target/classes").toUri().toURL(), "Expected o.a.p.spi.utils.TimeUtils to be loaded from pinot-realm");
    assertThrows("Class is part of a different plugin, so should not be accessible", ClassNotFoundException.class, () -> pluginManager.loadClass(pluginName, YAMMER_METRICS_REGISTRY));
    assertThrows("Class is dependency of pinot-spi, but is not an exported package", ClassNotFoundException.class, () -> pluginManager.loadClass(pluginName, COMMONS_MATH_UTILS));
    assertTrue(pluginManager.loadClass(pluginName, COMMONS_IO_UTILS).getProtectionDomain().getCodeSource().getLocation().getPath().endsWith("pinot-dropwizard-0.10.0-shaded.jar"), "Expected o.a.c.i.IOUtils to be available via dropwizard-realm");
}

