@Test
public void classicPluginClassloader() throws Exception {
    String pluginName = "pinot-shaded-yammer";
    // Create fresh pluginManager, so it can pick up the system property for the pluginDirectory
    PluginManager pluginManager = new PluginManager();
    // pinot-shaded-yammer is a shaded jar using the legacy PluginClassloader instead of classRealm
    assertTrue(Files.exists(PLUGINS_DIRECTORY.resolve(pluginName + "/pinot-yammer-0.10.0-shaded.jar")), "Plugin not found. Run 'mvn -f pinot-spi/pom.xml generate-test-resources' once to prepare this artifact");
    assertNotNull(pluginManager.loadClass(pluginName, YAMMER_METRICS_REGISTRY), "Expected o.a.p.p.m.y.YammerMetricsRegistry to be available");
    assertNotNull(pluginManager.createInstance(pluginName, YAMMER_METRICS_REGISTRY), "Expected to be able to create instance of o.a.p.p.m.y.YammerMetricsRegistry");
    assertNotNull(pluginManager.loadClass(pluginName, SPI_TIME_UTILS), "Expected o.a.p.spi.utils.TimeUtils to be available via yammer-realm");
    assertEquals(pluginManager.loadClass(pluginName, SPI_TIME_UTILS).getProtectionDomain().getCodeSource().getLocation(), Path.of("target/classes").toUri().toURL(), "Expected o.a.p.spi.utils.TimeUtils to be loaded from pinot-realm");
    assertNotNull(pluginManager.loadClass(pluginName, COMMONS_MATH_UTILS), "Class is dependency of pinot-spi, must be accessible for unlimited plugins");
    // THIS IS THE MAIN REASON FOR CLASSREALMS: classes are here loaded from pinot first, not from shaded plugin
    String urlPath = pluginManager.loadClass(pluginName, COMMONS_IO_UTILS).getProtectionDomain().getCodeSource().getLocation().getPath();
    // unpredictable version, as it depends on this pinot-spi
    assertTrue(Pattern.matches(".*/commons-io/commons-io/[^/]+/commons-io-[.\\d]+.jar$", urlPath), "This is using the PluginClassloader, so class should come from the system class laoder");
    assertThrows("Class is part of a different plugin, so should not be accessible", ClassNotFoundException.class, () -> pluginManager.loadClass(pluginName, DROPWIZARD_METRICS_REGISTRY));
}

@Test
public void testGetPluginsToLoad() throws IOException {
    /* We have two plugin directories (../plugins/d1/ and ../plugins/d2/)
     * plugins to include = [ p1, p2, p3 ]
     * d1 has plugins: p1
     * d2 has plugins: p1, p2, p3, p4
     * We expect d1/p1, d2/p2, d2/p3 to be picked up
     *   - ensuring second instance of p1 is ignored
     *   - ensuring p4 is ignored as it's not on the plugins to include list
     */
    String pluginsDirs = _tempDir + "/plugins/d1;" + _tempDir + "/plugins/d2;";
    // specifically excluding p3.jar
    String pluginsToInclude = "p1;p2;p3";
    File pluginsDir = new File(_tempDir + "/plugins");
    pluginsDir.mkdir();
    File subPluginsDir1 = new File(pluginsDir + "/d1");
    subPluginsDir1.mkdir();
    File subPluginsDir2 = new File(pluginsDir + "/d2");
    subPluginsDir2.mkdir();
    _p1 = new File(pluginsDir + "/d1/p1/p1.jar");
    FileUtils.touch(_p1);
    _p1Copy = new File(pluginsDir + "/d2/p1/p1.jar");
    FileUtils.touch(_p1Copy);
    _p2 = new File(pluginsDir + "/d2/p2/p2.jar");
    FileUtils.touch(_p2);
    _p3 = new File(pluginsDir + "/d2/p3/p3.jar");
    FileUtils.touch(_p3);
    _p4 = new File(pluginsDir + "/d2/p4/p4.jar");
    FileUtils.touch(_p4);
    HashMap<String, File> actualPluginsMap = PluginManager.get().getPluginsToLoad(pluginsDirs, pluginsToInclude);
    Assert.assertEquals(actualPluginsMap.size(), 3);
    HashMap<String, String> actualPluginNamesAndPaths = new HashMap<>();
    for (Map.Entry<String, File> entry : actualPluginsMap.entrySet()) {
        actualPluginNamesAndPaths.put(entry.getKey(), entry.getValue().getAbsolutePath());
    }
    HashMap<String, String> expectedPluginNamesAndPaths = new HashMap<>();
    expectedPluginNamesAndPaths.put("p1", _p1.getParentFile().getAbsolutePath());
    expectedPluginNamesAndPaths.put("p2", _p2.getParentFile().getAbsolutePath());
    expectedPluginNamesAndPaths.put("p3", _p3.getParentFile().getAbsolutePath());
    Assert.assertEquals(actualPluginNamesAndPaths, expectedPluginNamesAndPaths);
}

