@Test
public void testBigDecimal() throws IOException {
    BigDecimal[] testCases = { new BigDecimal("0"), new BigDecimal("0.0"), new BigDecimal("0.123456789"), new BigDecimal("-0.123456789"), new BigDecimal("123456789"), new BigDecimal("-123456789"), new BigDecimal("123456789.0123456789"), new BigDecimal("-123456789.0123456789"), new BigDecimal("9223372036854775808.123"), new BigDecimal("-9223372036854775808.123"), // Set the scale to a negative value
    new BigDecimal("123456789.0123456789").setScale(-1, RoundingMode.HALF_UP), new BigDecimal("-123456789.0123456789").setScale(-1, RoundingMode.HALF_UP), // Set the scale to a negative value in byte
    new BigDecimal("123456789.0123456789").setScale(128, RoundingMode.HALF_UP), new BigDecimal("-123456789.0123456789").setScale(128, RoundingMode.HALF_UP) };
    for (BigDecimal value : testCases) {
        byte[] serializedValue = BigDecimalUtils.serialize(value);
        assertEquals(BigDecimalUtils.byteSize(value), serializedValue.length);
        BigDecimal deserializedValue = BigDecimalUtils.deserialize(serializedValue);
        assertEquals(deserializedValue, value);
        ByteArrayOutputStream byteArr = new ByteArrayOutputStream();
        DataOutputStream output = new DataOutputStream(byteArr);
        BigDecimalUtils.serialize(value, output);
        DataInputStream input = new DataInputStream(new ByteArrayInputStream(byteArr.toByteArray()));
        deserializedValue = BigDecimalUtils.deserialize(input);
        assertEquals(deserializedValue, value);
    }
}

@Test
public void testBigDecimalSerializeWithSize() {
    BigDecimal[] testCases = { new BigDecimal("0.123456789"), new BigDecimal("-0.123456789"), new BigDecimal("123456789"), new BigDecimal("-123456789"), new BigDecimal("123456789.0123456789"), new BigDecimal("-123456789.0123456789"), new BigDecimal("123456789.0123456789").setScale(-1, RoundingMode.HALF_UP), new BigDecimal("-123456789.0123456789").setScale(-1, RoundingMode.HALF_UP), new BigDecimal("123456789.0123456789").setScale(128, RoundingMode.HALF_UP), new BigDecimal("-123456789.0123456789").setScale(128, RoundingMode.HALF_UP) };
    // One case of serialization with and without padding
    int[] sizes = { 0, 4 };
    for (BigDecimal value : testCases) {
        int actualSize = BigDecimalUtils.byteSize(value);
        for (int size : sizes) {
            byte[] serializedValue = BigDecimalUtils.serializeWithSize(value, actualSize + size);
            assertEquals(actualSize + size, serializedValue.length);
            BigDecimal deserializedValue = BigDecimalUtils.deserialize(serializedValue);
            assertEquals(deserializedValue, value);
        }
    }
}

