    {
        JsonNode jsonNode = JsonUtils.stringToJsonNode("[{\"country\":\"us\",\"street\":\"main st\",\"number\":1},{\"country\":\"ca\",\"street\":\"second st\"," + "\"number\":2}]");
        List<Map<String, String>> flattenedRecords = JsonUtils.flatten(jsonNode, jsonIndexConfig);
