@Test
public void testApplyTimestampIndex() {
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTable").setFieldConfigList(Arrays.asList(new FieldConfig("ts1", FieldConfig.EncodingType.DICTIONARY, FieldConfig.IndexType.TIMESTAMP, null, null, new TimestampConfig(Arrays.asList(TimestampIndexGranularity.SECOND, TimestampIndexGranularity.MINUTE, TimestampIndexGranularity.HOUR)), null), new FieldConfig("ts2", FieldConfig.EncodingType.RAW, FieldConfig.IndexType.TIMESTAMP, null, null, new TimestampConfig(Arrays.asList(TimestampIndexGranularity.DAY, TimestampIndexGranularity.WEEK, TimestampIndexGranularity.MONTH)), null))).build();
    Schema schema = new Schema.SchemaBuilder().setSchemaName("testTable").addDateTime("ts1", DataType.TIMESTAMP, "TIMESTAMP", "1:MILLISECONDS").addDateTime("ts2", DataType.TIMESTAMP, "TIMESTAMP", "1:MILLISECONDS").build();
    // Apply TIMESTAMP index multiple times should get the same result
    for (int i = 0; i < 5; i++) {
        TimestampIndexUtils.applyTimestampIndex(tableConfig, schema);
        // Check schema
        assertEquals(schema.size(), 8);
        FieldSpec ts1SecondFieldSpec = schema.getFieldSpecFor("$ts1$SECOND");
        assertNotNull(ts1SecondFieldSpec);
        assertTrue(ts1SecondFieldSpec instanceof DateTimeFieldSpec);
        DateTimeFieldSpec ts1SecondDateTimeFieldSpec = (DateTimeFieldSpec) ts1SecondFieldSpec;
        assertEquals(ts1SecondDateTimeFieldSpec.getDataType(), DataType.TIMESTAMP);
        assertEquals(ts1SecondDateTimeFieldSpec.getFormat(), "TIMESTAMP");
        assertEquals(ts1SecondDateTimeFieldSpec.getGranularity(), "1:SECONDS");
        // Check ingestion transform
        assertNotNull(tableConfig.getIngestionConfig());
        List<TransformConfig> transformConfigs = tableConfig.getIngestionConfig().getTransformConfigs();
        assertNotNull(transformConfigs);
        assertEquals(transformConfigs.size(), 6);
        Set<String> transformColumns = new HashSet<>();
        for (TransformConfig transformConfig : transformConfigs) {
            String columnName = transformConfig.getColumnName();
            assertTrue(transformColumns.add(columnName));
            if (columnName.equals("$ts2$DAY")) {
                assertEquals(transformConfig.getTransformFunction(), "dateTrunc('DAY',\"ts2\")");
            }
        }
        assertEquals(transformColumns, new HashSet<>(Arrays.asList("$ts1$SECOND", "$ts1$MINUTE", "$ts1$HOUR", "$ts2$DAY", "$ts2$WEEK", "$ts2$MONTH")));
        // Check range index
        List<String> rangeIndexColumns = tableConfig.getIndexingConfig().getRangeIndexColumns();
        assertNotNull(rangeIndexColumns);
        assertEquals(new HashSet<>(rangeIndexColumns), transformColumns);
    }
}

@Test
public void testValidTimestampFormats() {
    // Test ISO8601 variations with and without milliseconds and timezones
    assertEquals(TimestampUtils.toTimestamp("2024-07-12T15:32:36Z"), Timestamp.from(LocalDateTime.of(2024, 7, 12, 15, 32, 36).atZone(ZoneOffset.UTC).toInstant()));
    assertEquals(TimestampUtils.toTimestamp("2024-07-12 15:32:36.111Z"), Timestamp.from(LocalDateTime.of(2024, 7, 12, 15, 32, 36, 111000000).atZone(ZoneOffset.UTC).toInstant()));
    for (int i = 1; i < 7; i++) {
        int fraction = Integer.parseInt("1".repeat(i) + "0".repeat(9 - i));
        assertEquals(TimestampUtils.toTimestamp("2024-07-12T15:32:36." + fraction), Timestamp.valueOf("2024-07-12 15:32:36." + fraction));
        assertEquals(TimestampUtils.toTimestamp("2024-07-12T15:32:36." + fraction + "Z"), Timestamp.from(LocalDateTime.of(2024, 7, 12, 15, 32, 36, fraction).atZone(ZoneOffset.UTC).toInstant()));
    }
    // Test date and time variations without 'T'
    assertEquals(TimestampUtils.toTimestamp("2024-07-12 15:32:36.111"), Timestamp.valueOf("2024-07-12 15:32:36.111"));
    assertEquals(TimestampUtils.toTimestamp("2024-07-12 15:32:36"), Timestamp.valueOf("2024-07-12 15:32:36"));
    assertEquals(TimestampUtils.toTimestamp("2024-07-12 15:32"), Timestamp.valueOf("2024-07-12 15:32:00"));
    assertEquals(TimestampUtils.toTimestamp("2024-07-12"), Timestamp.valueOf("2024-07-12 00:00:00"));
    assertEquals(TimestampUtils.toTimestamp("1720798356111"), new Timestamp(1720798356111L));
}

