@Test
public void testGetEffectiveFilter() {
    TimeBuckets timeBuckets = TimeBuckets.ofSeconds(1000, Duration.ofSeconds(13), 9);
    final long expectedStartTimeInFilter = timeBuckets.getTimeRangeStartExclusive();
    final long expectedEndTimeInFilter = timeBuckets.getTimeRangeEndInclusive();
    final String nonEmptyFilter = "cityName = 'Chicago'";
    // Case-1: No offset, and empty filter.
    {
        LeafTimeSeriesPlanNode planNode = new LeafTimeSeriesPlanNode(ID, Collections.emptyList(), TABLE, TIME_COLUMN, TIME_UNIT, 0L, "", "value_col", new AggInfo("SUM", false, null), Collections.singletonList("cityName"), SERIES_LIMIT, QUERY_OPTIONS);
        assertEquals(planNode.getEffectiveFilter(timeBuckets), "orderTime > " + expectedStartTimeInFilter + " AND orderTime <= " + expectedEndTimeInFilter);
    }
    // Case-2: Offset, but empty filter
    {
        LeafTimeSeriesPlanNode planNode = new LeafTimeSeriesPlanNode(ID, Collections.emptyList(), TABLE, TIME_COLUMN, TIME_UNIT, 123L, "", "value_col", new AggInfo("SUM", false, null), Collections.singletonList("cityName"), SERIES_LIMIT, QUERY_OPTIONS);
        assertEquals(planNode.getEffectiveFilter(timeBuckets), "orderTime > " + (expectedStartTimeInFilter - 123) + " AND orderTime <= " + (expectedEndTimeInFilter - 123));
    }
    // Case-3: Offset and non-empty filter
    {
        LeafTimeSeriesPlanNode planNode = new LeafTimeSeriesPlanNode(ID, Collections.emptyList(), TABLE, TIME_COLUMN, TIME_UNIT, 123L, nonEmptyFilter, "value_col", new AggInfo("SUM", false, Collections.emptyMap()), Collections.singletonList("cityName"), SERIES_LIMIT, QUERY_OPTIONS);
        assertEquals(planNode.getEffectiveFilter(timeBuckets), String.format("(%s) AND (orderTime > %s AND orderTime <= %s)", nonEmptyFilter, (expectedStartTimeInFilter - 123), (expectedEndTimeInFilter - 123)));
    }
    // Case-4: Offset, and non-empty filter, and time-unit that is not seconds
    {
        LeafTimeSeriesPlanNode planNode = new LeafTimeSeriesPlanNode(ID, Collections.emptyList(), TABLE, TIME_COLUMN, TimeUnit.MILLISECONDS, 123L, nonEmptyFilter, "value_col", new AggInfo("SUM", false, Collections.emptyMap()), Collections.singletonList("cityName"), SERIES_LIMIT, QUERY_OPTIONS);
        assertEquals(planNode.getEffectiveFilter(timeBuckets), String.format("(%s) AND (orderTime > %s AND orderTime <= %s)", nonEmptyFilter, (expectedStartTimeInFilter * 1000 - 123 * 1000), (expectedEndTimeInFilter * 1000 - 123 * 1000)));
    }
}

@Test
public void testSerdeForScanFilterProjectNode() {
    Map<String, String> aggParams = new HashMap<>();
    aggParams.put("window", "5m");
    // create leaf node
    LeafTimeSeriesPlanNode leafTimeSeriesPlanNode = new LeafTimeSeriesPlanNode("sfp#0", new ArrayList<>(), "myTable", "myTimeColumn", TimeUnit.MILLISECONDS, 0L, "myFilterExpression", "myValueExpression", new AggInfo("SUM", false, aggParams), new ArrayList<>(), SERIES_LIMIT, QUERY_OPTIONS);
    // serialize and deserialize to re-create another node
    BaseTimeSeriesPlanNode planNode = TimeSeriesPlanSerde.deserialize(TimeSeriesPlanSerde.serialize(leafTimeSeriesPlanNode));
    assertTrue(planNode instanceof LeafTimeSeriesPlanNode);
    LeafTimeSeriesPlanNode deserializedNode = (LeafTimeSeriesPlanNode) planNode;
    // assert that deserialized node is same as serialized node
    assertEquals(deserializedNode.getTableName(), "myTable");
    assertEquals(deserializedNode.getTimeColumn(), "myTimeColumn");
    assertEquals(deserializedNode.getTimeUnit(), TimeUnit.MILLISECONDS);
    assertEquals(deserializedNode.getOffsetSeconds(), 0L);
    assertEquals(deserializedNode.getFilterExpression(), "myFilterExpression");
    assertEquals(deserializedNode.getValueExpression(), "myValueExpression");
    assertNotNull(deserializedNode.getAggInfo());
    assertFalse(deserializedNode.getAggInfo().getIsPartial());
    assertNotNull(deserializedNode.getAggInfo().getParams());
    assertEquals(deserializedNode.getAggInfo().getParams().get("window"), "5m");
    assertEquals(deserializedNode.getGroupByExpressions().size(), 0);
    assertEquals(deserializedNode.getLimit(), SERIES_LIMIT);
    assertEquals(deserializedNode.getQueryOptions(), QUERY_OPTIONS);
}

